#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
build_mod.py - Secret City Heist: 5 Forbidden Items  (Minecraft Fabric 1.20.1, Java 17, Official Mojang mappings)
=====================================================================================================================

One script that creates the complete, ready-to-build mod workspace:

  * Gradle / Fabric Loom project (build.gradle, settings.gradle, gradle.properties, Gradle 8.8 wrapper incl. jar)
  * every Java class (items, blocks, block entities, entities + AI, renderers, glTF/GLB pipeline, HUD overlays,
    screens, networking, mixins, city generator, /heist command)
  * every resource: blockstates, block/item models, en_us.json, tags, loot tables, recipes, fabric.mod.json,
    procedurally painted textures + entity skins, procedural 3D models (glTF) for every gadget that has no
    hand-made model, the user-supplied Sketchfab models (imported + sanitised), sounds (.ogg) and sounds.json

USAGE
    python3 build_mod.py                         # -> ./SecretCityHeist/
    python3 build_mod.py --out ~/mods/heist      # choose the output folder
    python3 build_mod.py --models ./source_models  # where the supplied glTF/GLB model folders live
    python3 build_mod.py --build                 # also run "gradlew build" (needs JDK 17)
    python3 build_mod.py --sync-assets --out DIR # re-scan dropped-in .ogg / glTF / GLB in an existing workspace

ASSET DROP-ZONES (no Java changes, no re-registration)
    assets/heistmod/models/gltf/<item_id>/model.glb | model.gltf | scene.gltf  (+ textures, + heist_model.json)
    assets/heistmod/sounds/<event/path>.ogg  (+ _2, _3 ... variants; run --sync-assets to refresh sounds.json)
    <texture>.png + <texture>_n.png + <texture>_s.png  (LabPBR albedo / normal / specular, up to 8K)
    assets/heistmod/textures/gui/chingam_splat.png      (replaces the procedural bubblegum splat)
    data/heistmod/structures/<city_part>.nbt            (replaces a procedural city part; see /heist export_city)

Only the Python 3.8+ standard library is used.
"""
import argparse
import base64
import io
import json
import math
import os
import random
import re
import shutil
import struct
import subprocess
import sys
import zlib

MOD_ID = "heistmod"
PKG = "com/heistmod"
SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
ASSETS = "src/main/resources/assets/" + MOD_ID
DATA = "src/main/resources/data/" + MOD_ID

_stats = {"written": 0, "unchanged": 0}
OUT = None  # set in main()


def log(msg):
    print("[build_mod] " + msg, flush=True)


def out_path(rel):
    return os.path.join(OUT, *rel.split("/"))


def write_bytes(rel, data):
    """Writes only when the content changed (keeps Gradle's incremental build fast on re-runs)."""
    path = out_path(rel)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    if os.path.exists(path):
        with open(path, "rb") as f:
            if f.read() == data:
                _stats["unchanged"] += 1
                return
    with open(path, "wb") as f:
        f.write(data)
    _stats["written"] += 1


def write_text(rel, text):
    write_bytes(rel, text.encode("utf-8"))


def write_json(rel, obj):
    write_text(rel, json.dumps(obj, indent=2, ensure_ascii=False) + "\n")



# =====================================================================================================================
#  PNG encode / decode + a tiny painting canvas (stdlib only)
# =====================================================================================================================
def png_encode(width, height, rgba):
    """rgba: bytearray of width*height*4."""
    raw = bytearray()
    stride = width * 4
    for y in range(height):
        raw.append(0)
        raw.extend(rgba[y * stride:(y + 1) * stride])

    def chunk(tag, payload):
        return struct.pack(">I", len(payload)) + tag + payload + struct.pack(">I", zlib.crc32(tag + payload) & 0xFFFFFFFF)

    return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", width, height, 8, 6, 0, 0, 0))
            + chunk(b"IDAT", zlib.compress(bytes(raw), 9)) + chunk(b"IEND", b""))


def png_decode(data):
    """Decodes 8-bit grey / RGB / RGBA / palette PNGs (non-interlaced) to (w, h, bytearray RGBA)."""
    if data[:8] != b"\x89PNG\r\n\x1a\n":
        raise ValueError("not a PNG")
    pos, idat, palette, trns = 8, bytearray(), None, None
    w = h = depth = ctype = 0
    while pos < len(data):
        length = struct.unpack(">I", data[pos:pos + 4])[0]
        tag = data[pos + 4:pos + 8]
        body = data[pos + 8:pos + 8 + length]
        if tag == b"IHDR":
            w, h, depth, ctype, _, _, interlace = struct.unpack(">IIBBBBB", body)
            if interlace:
                raise ValueError("interlaced PNG not supported")
        elif tag == b"PLTE":
            palette = body
        elif tag == b"tRNS":
            trns = body
        elif tag == b"IDAT":
            idat.extend(body)
        pos += 12 + length
    raw = zlib.decompress(bytes(idat))
    channels = {0: 1, 2: 3, 3: 1, 4: 2, 6: 4}[ctype]
    bits = depth * channels
    stride = (w * bits + 7) // 8
    bpp = max(1, bits // 8)
    out = bytearray(w * h * 4)
    prev = bytearray(stride)
    p = 0
    for y in range(h):
        f = raw[p]
        line = bytearray(raw[p + 1:p + 1 + stride])
        p += 1 + stride
        if f == 1:
            for i in range(bpp, stride):
                line[i] = (line[i] + line[i - bpp]) & 255
        elif f == 2:
            for i in range(stride):
                line[i] = (line[i] + prev[i]) & 255
        elif f == 3:
            for i in range(stride):
                a = line[i - bpp] if i >= bpp else 0
                line[i] = (line[i] + ((a + prev[i]) >> 1)) & 255
        elif f == 4:
            for i in range(stride):
                a = line[i - bpp] if i >= bpp else 0
                b = prev[i]
                c = prev[i - bpp] if i >= bpp else 0
                pa, pb, pc = abs(b - c), abs(a - c), abs(a + b - 2 * c)
                line[i] = (line[i] + (a if pa <= pb and pa <= pc else b if pb <= pc else c)) & 255
        prev = line
        for x in range(w):
            o = (y * w + x) * 4
            if ctype == 6:
                out[o:o + 4] = line[x * 4:x * 4 + 4]
            elif ctype == 2:
                out[o:o + 3] = line[x * 3:x * 3 + 3]
                out[o + 3] = 255
            elif ctype == 0:
                v = line[x]
                out[o:o + 4] = bytes((v, v, v, 255))
            elif ctype == 4:
                v = line[x * 2]
                out[o:o + 4] = bytes((v, v, v, line[x * 2 + 1]))
            else:
                per = 8 // depth
                byte = line[x // per]
                shift = 8 - depth * (x % per + 1)
                idx = (byte >> shift) & ((1 << depth) - 1)
                out[o:o + 3] = palette[idx * 3:idx * 3 + 3]
                out[o + 3] = trns[idx] if trns is not None and idx < len(trns) else 255
    return w, h, out


def clamp8(v):
    return 0 if v < 0 else 255 if v > 255 else int(v)


class Canvas:
    """RGBA canvas with the handful of primitives the painters need."""

    def __init__(self, w, h, fill=(0, 0, 0, 0)):
        self.w, self.h = w, h
        self.px = bytearray(bytes(fill) * (w * h))

    def get(self, x, y):
        o = (y * self.w + x) * 4
        return tuple(self.px[o:o + 4])

    def set(self, x, y, c):
        if 0 <= x < self.w and 0 <= y < self.h:
            o = (y * self.w + x) * 4
            if len(c) == 3:
                c = (c[0], c[1], c[2], 255)
            if c[3] >= 255:
                self.px[o:o + 4] = bytes((clamp8(c[0]), clamp8(c[1]), clamp8(c[2]), 255))
            elif c[3] > 0:
                a = c[3] / 255.0
                dst = self.px[o:o + 4]
                out_a = a + dst[3] / 255.0 * (1 - a)
                for i in range(3):
                    dst[i] = clamp8((c[i] * a + dst[i] * (dst[3] / 255.0) * (1 - a)) / max(out_a, 1e-6))
                dst[3] = clamp8(out_a * 255)
                self.px[o:o + 4] = dst

    def rect(self, x, y, w, h, c, noise=0, rnd=None):
        rnd = rnd or random.Random(x * 7919 + y * 31 + w)
        for yy in range(y, y + h):
            for xx in range(x, x + w):
                if noise:
                    n = rnd.randint(-noise, noise)
                    self.set(xx, yy, (c[0] + n, c[1] + n, c[2] + n, c[3] if len(c) > 3 else 255))
                else:
                    self.set(xx, yy, c)

    def gradient(self, x, y, w, h, c0, c1, vertical=True):
        for yy in range(y, y + h):
            for xx in range(x, x + w):
                t = ((yy - y) / max(1, h - 1)) if vertical else ((xx - x) / max(1, w - 1))
                self.set(xx, yy, tuple(int(c0[i] + (c1[i] - c0[i]) * t) for i in range(3)) + (255,))

    def circle(self, cx, cy, r, c, ring=0):
        for yy in range(int(cy - r - 1), int(cy + r + 2)):
            for xx in range(int(cx - r - 1), int(cx + r + 2)):
                d = math.hypot(xx + 0.5 - cx, yy + 0.5 - cy)
                if d <= r and (ring == 0 or d >= r - ring):
                    self.set(xx, yy, c)

    def line(self, x0, y0, x1, y1, c):
        n = int(max(abs(x1 - x0), abs(y1 - y0))) + 1
        for i in range(n + 1):
            t = i / max(1, n)
            self.set(int(round(x0 + (x1 - x0) * t)), int(round(y0 + (y1 - y0) * t)), c)

    def frame(self, x, y, w, h, c):
        self.rect(x, y, w, 1, c)
        self.rect(x, y + h - 1, w, 1, c)
        self.rect(x, y, 1, h, c)
        self.rect(x + w - 1, y, 1, h, c)

    def png(self):
        return png_encode(self.w, self.h, self.px)


def shade(c, f):
    return (clamp8(c[0] * f), clamp8(c[1] * f), clamp8(c[2] * f), c[3] if len(c) > 3 else 255)


def mix(a, b, t):
    return tuple(clamp8(a[i] + (b[i] - a[i]) * t) for i in range(3)) + (255,)



