def gltf_bytes(mesh, name, generator="build_mod.py"):
    """Serialises one mesh as glTF 2.0 JSON + binary buffer (positions, normals, uvs, uint32 indices)."""
    n = len(mesh.pos)
    blob = bytearray()

    def add(fmt, values):
        start = len(blob)
        for v in values:
            blob.extend(struct.pack(fmt, *v) if isinstance(v, (tuple, list)) else struct.pack(fmt, v))
        while len(blob) % 4:
            blob.append(0)
        return start, len(blob) - start

    views = [add("<3f", mesh.pos), add("<3f", mesh.nrm), add("<2f", mesh.uv), add("<I", mesh.idx)]
    mins = [min(p[i] for p in mesh.pos) for i in range(3)]
    maxs = [max(p[i] for p in mesh.pos) for i in range(3)]
    doc = {
        "asset": {"version": "2.0", "generator": generator},
        "scene": 0, "scenes": [{"nodes": [0]}],
        "nodes": [{"name": name, "mesh": 0}],
        "meshes": [{"name": name, "primitives": [{"attributes": {"POSITION": 0, "NORMAL": 1, "TEXCOORD_0": 2}, "indices": 3, "material": 0}]}],
        "materials": [{"name": name, "doubleSided": True,
                       "pbrMetallicRoughness": {"baseColorTexture": {"index": 0}, "metallicFactor": 0.0, "roughnessFactor": 0.6},
                       "normalTexture": {"index": 1}}],
        "textures": [{"source": 0, "sampler": 0}, {"source": 1, "sampler": 0}],
        "images": [{"uri": "textures/albedo.png"}, {"uri": "textures/albedo_n.png"}],
        "samplers": [{"magFilter": 9729, "minFilter": 9987, "wrapS": 10497, "wrapT": 10497}],
        "buffers": [{"uri": "model.bin", "byteLength": len(blob)}],
        "bufferViews": [{"buffer": 0, "byteOffset": views[0][0], "byteLength": views[0][1], "target": 34962},
                        {"buffer": 0, "byteOffset": views[1][0], "byteLength": views[1][1], "target": 34962},
                        {"buffer": 0, "byteOffset": views[2][0], "byteLength": views[2][1], "target": 34962},
                        {"buffer": 0, "byteOffset": views[3][0], "byteLength": views[3][1], "target": 34963}],
        "accessors": [{"bufferView": 0, "componentType": 5126, "count": n, "type": "VEC3", "min": mins, "max": maxs},
                      {"bufferView": 1, "componentType": 5126, "count": n, "type": "VEC3"},
                      {"bufferView": 2, "componentType": 5126, "count": n, "type": "VEC2"},
                      {"bufferView": 3, "componentType": 5125, "count": len(mesh.idx), "type": "SCALAR"}],
    }
    return (json.dumps(doc, indent=1) + "\n").encode("utf-8"), bytes(blob)


def generate_procedural_models():
    albedo, normal, spec = build_atlas()
    report = []
    for model_id, factory in PROCEDURAL_MODELS.items():
        base = ASSETS + "/models/gltf/" + model_id + "/"
        if os.path.exists(out_path(base + "model.glb")) or os.path.exists(out_path(base + ".user_model")):
            continue  # a user-dropped model replaced the procedural one
        mesh = factory()
        report.append("%s (%d tris)" % (model_id, mesh.triangles()))
        gltf, blob = gltf_bytes(mesh, model_id)
        write_bytes(base + "model.gltf", gltf)
        write_bytes(base + "model.bin", blob)
        write_bytes(base + "textures/albedo.png", albedo)
        write_bytes(base + "textures/albedo_n.png", normal)
        write_bytes(base + "textures/albedo_s.png", spec)
    log("procedural models: " + ", ".join(report))



# =====================================================================================================================
#  User-supplied glTF / GLB models (source_models/<model_id>/...) + per-model placement sidecars
# =====================================================================================================================
def sanitize_name(part):
    """Mirror of GltfModel.sanitize() on the Java side: lower-case [a-z0-9._-], no leading dots."""
    part = part.replace("%20", " ").lower()
    part = re.sub(r"[^a-z0-9._-]", "_", part)
    while part.startswith(".") and len(part) > 1 and part != "..":
        part = part[1:]
    return part


def sanitize_path(p):
    return "/".join(sanitize_name(x) for x in p.replace("\\", "/").split("/"))


def recolor_police_cap(png_bytes):
    """Indian police khaki: the cap's blue fabric becomes khaki, black visor and gold badge are kept."""
    w, h, px = png_decode(png_bytes)
    for i in range(0, len(px), 4):
        r, g, b = px[i], px[i + 1], px[i + 2]
        if b > r + 25 and b > g + 10:
            lum = (0.3 * r + 0.59 * g + 0.11 * b) / 70.0
            px[i], px[i + 1], px[i + 2] = clamp8(201 * lum), clamp8(176 * lum), clamp8(116 * lum)
    return png_encode(w, h, px)


def import_user_models(models_dir):
    """Copies every model folder from models_dir into assets/heistmod/models/gltf/<folder>/ with sanitised names."""
    imported = []
    if not models_dir or not os.path.isdir(models_dir):
        log("no source model folder (%s) - procedural stand-ins will be used where needed" % models_dir)
        return imported
    for folder in sorted(os.listdir(models_dir)):
        src = os.path.join(models_dir, folder)
        if not os.path.isdir(src):
            continue
        model_id = sanitize_name(folder)
        main = None
        for cand in ("model.glb", "scene.glb", "model.gltf", "scene.gltf"):
            if os.path.exists(os.path.join(src, cand)):
                main = cand
                break
        if main is None:
            glbs = [f for f in os.listdir(src) if f.lower().endswith((".glb", ".gltf"))]
            main = glbs[0] if glbs else None
        if main is None:
            log("  skip %s: no .glb / .gltf inside" % folder)
            continue
        dst = ASSETS + "/models/gltf/" + model_id + "/"
        if main.lower().endswith(".glb"):
            with open(os.path.join(src, main), "rb") as f:
                write_bytes(dst + "model.glb", f.read())
        else:
            with open(os.path.join(src, main), "r", encoding="utf-8") as f:
                doc = json.load(f)
            for coll in ("buffers", "images"):
                for entry in doc.get(coll, []):
                    uri = entry.get("uri")
                    if uri and not uri.startswith("data:"):
                        with open(os.path.join(src, uri.replace("%20", " ")), "rb") as f:
                            data = f.read()
                        clean = sanitize_path(uri)
                        if model_id == "havaldar_cap" and coll == "images" and "basecolor" in clean:
                            data = recolor_police_cap(data)
                        write_bytes(dst + clean, data)
                        entry["uri"] = clean
            write_text(dst + "model.gltf", json.dumps(doc, indent=1) + "\n")
        for extra in os.listdir(src):
            if extra.lower().startswith(("license", "readme", "credits")):
                with open(os.path.join(src, extra), "rb") as f:
                    write_bytes(dst + sanitize_name(extra), f.read())
        write_text(dst + ".user_model", folder + "\n")
        imported.append(model_id)
    log("imported user models: " + (", ".join(imported) or "none"))
    return imported


def ctx(rot=(0, 0, 0), tr=(0, 0, 0), scale=1.0):
    return {"rotation": list(rot), "translation": list(tr), "scale": scale}


