def write_sidecars():
    for model_id, cfg in SIDECARS.items():
        rel = ASSETS + "/models/gltf/" + model_id + "/heist_model.json"
        path = out_path(rel)
        if os.path.exists(path):
            try:
                with open(path, "r", encoding="utf-8") as f:
                    if not json.load(f).get("_generated"):
                        continue  # user-tuned: keep it
            except ValueError:
                pass
        doc = dict(cfg)
        doc["_generated"] = True
        write_json(rel, doc)



