def build_lang():
    lang = dict(LANG)
    for key, fields in MISSION_TEXT.items():
        for field, text in fields.items():
            lang["mission.heistmod.%s.%s" % (key, field)] = text
    for event, subtitle in SOUND_EVENTS:
        lang["subtitles.heistmod." + event] = subtitle
    return lang


# =====================================================================================================================
#  Models, blockstates, tags, loot tables, recipes
# =====================================================================================================================
def generate_data():
    write_json(ASSETS + "/lang/en_us.json", build_lang())
    m = ASSETS + "/models/"
    bs = ASSETS + "/blockstates/"
    for item in GLTF_ITEMS:
        write_json(m + "item/" + item + ".json", {"parent": "minecraft:builtin/entity", "gui_light": "front",
                                                   "textures": {"particle": "heistmod:block/thaila_leather"}})
    for egg in SPAWN_EGGS:
        write_json(m + "item/" + egg + ".json", {"parent": "minecraft:item/template_spawn_egg"})
    for b in SIMPLE_BLOCKS:
        write_json(m + "item/" + b + ".json", {"parent": "heistmod:block/" + b})

    # ---- simple cubes
    for b in ["soundproof_panel", "vault_steel"] + ["neon_" + c for c in NEON]:
        write_json(m + "block/" + b + ".json", {"parent": "minecraft:block/cube_all", "textures": {"all": "heistmod:block/" + b}})
        write_json(bs + b + ".json", {"variants": {"": {"model": "heistmod:block/" + b}}})

    # ---- mission board (corkboard on an easel)
    write_json(m + "block/mission_board.json", {
        "parent": "minecraft:block/block", "textures": {"front": "heistmod:block/mission_board_front", "side": "heistmod:block/mission_board_side",
                                                        "metal": "heistmod:block/metal_dark", "particle": "heistmod:block/mission_board_side"},
        "elements": [
            {"from": [1, 0, 7], "to": [2, 5, 9], "faces": {f: {"texture": "#metal"} for f in ("north", "south", "east", "west", "up", "down")}},
            {"from": [14, 0, 7], "to": [15, 5, 9], "faces": {f: {"texture": "#metal"} for f in ("north", "south", "east", "west", "up", "down")}},
            {"from": [0, 4, 7], "to": [16, 16, 9], "faces": {
                "north": {"uv": [0, 0, 16, 16], "texture": "#front"}, "south": {"uv": [0, 0, 16, 16], "texture": "#side"},
                "east": {"uv": [7, 0, 9, 12], "texture": "#side"}, "west": {"uv": [7, 0, 9, 12], "texture": "#side"},
                "up": {"uv": [0, 7, 16, 9], "texture": "#side"}, "down": {"uv": [0, 7, 16, 9], "texture": "#side"}}},
            {"from": [2, 15.5, 6], "to": [14, 16, 7], "faces": {f: {"texture": "#metal"} for f in ("north", "south", "east", "west", "up", "down")}},
        ]})
    write_json(bs + "mission_board.json", {"variants": {
        "facing=north": {"model": "heistmod:block/mission_board"}, "facing=east": {"model": "heistmod:block/mission_board", "y": 90},
        "facing=south": {"model": "heistmod:block/mission_board", "y": 180}, "facing=west": {"model": "heistmod:block/mission_board", "y": 270}}})

    # ---- trophy pedestal (brass + marble)
    faces = lambda tex: {f: {"texture": tex} for f in ("north", "south", "east", "west", "up", "down")}
    write_json(m + "block/trophy_pedestal.json", {
        "parent": "minecraft:block/block", "textures": {"brass": "heistmod:block/pedestal_brass", "marble": "heistmod:block/pedestal_marble",
                                                        "particle": "heistmod:block/pedestal_marble"},
        "elements": [{"from": [2, 0, 2], "to": [14, 3, 14], "faces": faces("#brass")},
                     {"from": [4, 3, 4], "to": [12, 12, 12], "faces": faces("#marble")},
                     {"from": [1, 12, 1], "to": [15, 16, 15], "faces": faces("#brass")}]})
    write_json(bs + "trophy_pedestal.json", {"variants": {"": {"model": "heistmod:block/trophy_pedestal"}}})

    # ---- laser emitter (model points up; rotated like end rods)
    for state, lens in (("", "laser_lens_on"), ("_off", "laser_lens_off")):
        write_json(m + "block/laser_emitter%s.json" % state, {
            "parent": "minecraft:block/block", "textures": {"metal": "heistmod:block/metal_dark", "lens": "heistmod:block/" + lens,
                                                            "particle": "heistmod:block/metal_dark"},
            "elements": [{"from": [5, 0, 5], "to": [11, 6, 11], "faces": faces("#metal")},
                         {"from": [6, 6, 6], "to": [10, 8, 10], "faces": {**faces("#metal"), "up": {"texture": "#lens"}}}]})
    rot = {"up": {}, "down": {"x": 180}, "north": {"x": 90}, "south": {"x": 90, "y": 180}, "east": {"x": 90, "y": 90}, "west": {"x": 90, "y": 270}}
    variants = {}
    for facing, r in rot.items():
        for powered in ("false", "true"):
            v = {"model": "heistmod:block/laser_emitter" + ("_off" if powered == "true" else "")}
            v.update(r)
            variants["facing=%s,powered=%s" % (facing, powered)] = v
    write_json(bs + "laser_emitter.json", {"variants": variants})

    # ---- alarm beacon
    for lit, lamp in (("", "alarm_lamp_off"), ("_on", "alarm_lamp_on")):
        write_json(m + "block/alarm_beacon%s.json" % lit, {
            "parent": "minecraft:block/block", "textures": {"metal": "heistmod:block/metal_light", "lamp": "heistmod:block/" + lamp,
                                                            "particle": "heistmod:block/" + lamp},
            "elements": [{"from": [4, 0, 4], "to": [12, 2, 12], "faces": faces("#metal")},
                         {"from": [5, 2, 5], "to": [11, 8, 11], "faces": faces("#lamp")},
                         {"from": [6, 8, 6], "to": [10, 9, 10], "faces": faces("#metal")}]})
    write_json(bs + "alarm_beacon.json", {"variants": {"lit=false": {"model": "heistmod:block/alarm_beacon"},
                                                       "lit=true": {"model": "heistmod:block/alarm_beacon_on"}}})
    # ---- bermuda thaila: drawn by its block entity renderer (glTF); the block model only supplies particles
    write_json(m + "block/bermuda_thaila.json", {"textures": {"particle": "heistmod:block/thaila_leather"}})
    write_json(bs + "bermuda_thaila.json", {"variants": {"": {"model": "heistmod:block/bermuda_thaila"}}})

    # ---- tags
    t = "src/main/resources/data/"
    write_json(DATA + "/tags/items/quest_items.json", {"replace": False, "values": [
        "heistmod:wardens_squeaky_toy", "heistmod:piglin_kings_golden_tooth", "heistmod:herobrines_forbidden_diary", "heistmod:ultimate_forbidden_core"]})
    write_json(t + "minecraft/tags/blocks/mineable/pickaxe.json", {"replace": False, "values": [
        "heistmod:" + b for b in ["mission_board", "trophy_pedestal", "laser_emitter", "alarm_beacon", "vault_steel"] + ["neon_" + c for c in NEON]]})
    write_json(t + "minecraft/tags/blocks/needs_iron_tool.json", {"replace": False, "values": ["heistmod:mission_board", "heistmod:laser_emitter"]})
    write_json(t + "minecraft/tags/blocks/needs_diamond_tool.json", {"replace": False, "values": ["heistmod:vault_steel", "heistmod:trophy_pedestal"]})
    write_json(t + "minecraft/tags/blocks/mineable/hoe.json", {"replace": False, "values": ["heistmod:soundproof_panel"]})
    write_json(t + "minecraft/tags/blocks/occludes_vibration_signals.json", {"replace": False, "values": ["heistmod:soundproof_panel"]})
    write_json(t + "minecraft/tags/blocks/dampens_vibrations.json", {"replace": False, "values": ["heistmod:soundproof_panel"]})

    # ---- loot tables: every block drops itself (no unbreakable / un-droppable blocks)
    for b in ALL_BLOCKS:
        write_json(DATA + "/loot_tables/blocks/%s.json" % b, {"type": "minecraft:block", "pools": [{
            "rolls": 1, "entries": [{"type": "minecraft:item", "name": "heistmod:" + b}],
            "conditions": [{"condition": "minecraft:survives_explosion"}]}]})
    write_json(DATA + "/loot_tables/entities/havaldar_thandulal.json", {"type": "minecraft:entity", "pools": [
        {"rolls": 1, "entries": [{"type": "minecraft:item", "name": "heistmod:havaldar_lathi"}],
         "conditions": [{"condition": "minecraft:killed_by_player"}, {"condition": "minecraft:random_chance", "chance": 0.5}]},
        {"rolls": 1, "entries": [{"type": "minecraft:item", "name": "heistmod:havaldar_cap"}],
         "conditions": [{"condition": "minecraft:killed_by_player"}, {"condition": "minecraft:random_chance", "chance": 0.35}]},
        {"rolls": 1, "entries": [{"type": "minecraft:item", "name": "heistmod:heist_diamond",
                                  "functions": [{"function": "minecraft:set_count", "count": {"min": 1, "max": 3}}]}]}]})
    for e in ("agent_zero", "black_market_dealer"):
        write_json(DATA + "/loot_tables/entities/%s.json" % e, {"type": "minecraft:entity", "pools": []})

    # ---- recipes for the decorative / building blocks (gadgets come from Agent Zero)
    def shaped(name, pattern, key, count=1):
        write_json(DATA + "/recipes/%s.json" % name, {"type": "minecraft:crafting_shaped", "category": "building", "pattern": pattern,
                                                      "key": {k: {"item": v} for k, v in key.items()},
                                                      "result": {"item": "heistmod:" + name, "count": count}})
    shaped("vault_steel", ["III", "IBI", "III"], {"I": "minecraft:iron_ingot", "B": "minecraft:iron_block"}, 4)
    shaped("soundproof_panel", ["WWW", "WSW", "WWW"], {"W": "minecraft:black_wool", "S": "minecraft:sculk"}, 8)
    for c, dye in (("cyan", "cyan_dye"), ("pink", "pink_dye"), ("gold", "yellow_dye"), ("red", "red_dye")):
        shaped("neon_" + c, ["GGG", "GDG", "GGG"], {"G": "minecraft:glowstone_dust", "D": "minecraft:" + dye}, 4)
    shaped("alarm_beacon", [" R ", "GLG", "III"], {"R": "minecraft:redstone", "G": "minecraft:red_stained_glass", "L": "minecraft:redstone_lamp",
                                                  "I": "minecraft:iron_ingot"})
    shaped("laser_emitter", ["IRI", "IOI", "III"], {"I": "minecraft:iron_ingot", "R": "minecraft:redstone", "O": "minecraft:observer"}, 2)
    shaped("mission_board", ["SPS", "PMP", "I I"], {"S": "minecraft:string", "P": "minecraft:paper", "M": "minecraft:map", "I": "minecraft:iron_ingot"})
    shaped("trophy_pedestal", ["GGG", " Q ", "BBB"], {"G": "minecraft:glass", "Q": "minecraft:quartz_pillar", "B": "minecraft:gold_ingot"})


# =====================================================================================================================
#  EMBEDDED PROJECT FILES  (Gradle setup, fabric.mod.json, mixin config, every Java class, docs)
# =====================================================================================================================
