FILES['src/main/java/com/heistmod/block/BermudaThailaBlock.java'] = r'''package com.heistmod.block;

import com.heistmod.HeistConfig;
import com.heistmod.blockentity.BermudaThailaBlockEntity;
import com.heistmod.registry.ModBlockEntities;
import com.heistmod.registry.ModSounds;
import com.heistmod.siphon.ChaosSiphonManager;
import net.minecraft.core.BlockPos;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.BaseEntityBlock;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.RenderShape;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.entity.BlockEntityTicker;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.shapes.CollisionContext;
import net.minecraft.world.phys.shapes.VoxelShape;

import org.jetbrains.annotations.Nullable;

/**
 * Tier 5 - the Bermuda Thaila (a leather bag holding a 10M chaos siphon). Placeable. Right-click arms it, a second
 * right-click opens it: entities are pulled in and the surrounding blocks are erased in tick-budgeted batches.
 */
public class BermudaThailaBlock extends BaseEntityBlock {
    private static final VoxelShape SHAPE = Block.box(1.0D, 0.0D, 1.0D, 15.0D, 12.0D, 15.0D);

    public BermudaThailaBlock(Properties properties) {
        super(properties);
    }

    @Override
    public VoxelShape getShape(BlockState state, BlockGetter level, BlockPos pos, CollisionContext context) {
        return SHAPE;
    }

    /** The glTF bag model is drawn by the block entity renderer. */
    @Override
    public RenderShape getRenderShape(BlockState state) {
        return RenderShape.ENTITYBLOCK_ANIMATED;
    }

    @Nullable
    @Override
    public BlockEntity newBlockEntity(BlockPos pos, BlockState state) {
        return new BermudaThailaBlockEntity(pos, state);
    }

    @Nullable
    @Override
    public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level, BlockState state, BlockEntityType<T> type) {
        return level.isClientSide ? null : createTickerHelper(type, ModBlockEntities.BERMUDA_THAILA.get(), BermudaThailaBlockEntity::serverTick);
    }

    @Override
    public InteractionResult use(BlockState state, Level level, BlockPos pos, Player player, InteractionHand hand, BlockHitResult hit) {
        if (level.isClientSide) {
            return InteractionResult.SUCCESS;
        }
        if (!(level instanceof ServerLevel serverLevel) || !(player instanceof ServerPlayer serverPlayer)) {
            return InteractionResult.PASS;
        }
        BlockEntity be = level.getBlockEntity(pos);
        if (!(be instanceof BermudaThailaBlockEntity bag)) {
            return InteractionResult.PASS;
        }
        long now = level.getGameTime();
        switch (bag.getState()) {
            case OPEN -> player.displayClientMessage(Component.translatable("message.heistmod.thaila.already_open"), true);
            case ARMED -> {
                if (now <= bag.getArmedUntil()) {
                    openBag(serverLevel, pos, bag, serverPlayer);
                } else {
                    arm(level, pos, bag, serverPlayer);
                }
            }
            default -> {
                if (HeistConfig.SIPHON_REQUIRES_CONFIRM.get()) {
                    arm(level, pos, bag, serverPlayer);
                } else {
                    openBag(serverLevel, pos, bag, serverPlayer);
                }
            }
        }
        return InteractionResult.CONSUME;
    }

    private static void arm(Level level, BlockPos pos, BermudaThailaBlockEntity bag, ServerPlayer player) {
        long now = level.getGameTime();
        bag.setState(BermudaThailaBlockEntity.State.ARMED, now, now + 160L);
        level.playSound(null, pos, ModSounds.THAILA_ARM.get(), SoundSource.BLOCKS, 1.5F, 1.0F);
        player.displayClientMessage(Component.translatable("message.heistmod.thaila.armed", HeistConfig.SIPHON_RADIUS.get()), true);
    }

    private static void openBag(ServerLevel level, BlockPos pos, BermudaThailaBlockEntity bag, ServerPlayer player) {
        bag.setState(BermudaThailaBlockEntity.State.OPEN, level.getGameTime(), 0L);
        level.playSound(null, pos, ModSounds.THAILA_OPEN.get(), SoundSource.BLOCKS, 4.0F, 1.0F);
        ChaosSiphonManager.start(level, pos, player);
    }
}
'''

FILES['src/main/java/com/heistmod/block/LaserEmitterBlock.java'] = r'''package com.heistmod.block;

import com.heistmod.blockentity.LaserEmitterBlockEntity;
import com.heistmod.registry.ModBlockEntities;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.item.context.BlockPlaceContext;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.BaseEntityBlock;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.DirectionalBlock;
import net.minecraft.world.level.block.Mirror;
import net.minecraft.world.level.block.RenderShape;
import net.minecraft.world.level.block.Rotation;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.entity.BlockEntityTicker;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.StateDefinition;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.level.block.state.properties.BooleanProperty;
import net.minecraft.world.phys.shapes.CollisionContext;
import net.minecraft.world.phys.shapes.VoxelShape;

import org.jetbrains.annotations.Nullable;

/**
 * Laser tripwire emitter. Fires a thin red beam in its facing direction; any living thing crossing the beam raises the
 * alarm. A redstone signal switches it off. The beam itself is drawn by the client BER.
 */
public class LaserEmitterBlock extends BaseEntityBlock {
    public static final net.minecraft.world.level.block.state.properties.DirectionProperty FACING = DirectionalBlock.FACING;
    public static final BooleanProperty POWERED = BlockStateProperties.POWERED;

    public LaserEmitterBlock(Properties properties) {
        super(properties);
        registerDefaultState(stateDefinition.any().setValue(FACING, Direction.NORTH).setValue(POWERED, false));
    }

    @Override
    protected void createBlockStateDefinition(StateDefinition.Builder<Block, BlockState> builder) {
        builder.add(FACING, POWERED);
    }

    @Override
    public BlockState getStateForPlacement(BlockPlaceContext context) {
        return defaultBlockState().setValue(FACING, context.getClickedFace()).setValue(POWERED, context.getLevel().hasNeighborSignal(context.getClickedPos()));
    }

    @Override
    public void neighborChanged(BlockState state, Level level, BlockPos pos, Block block, BlockPos fromPos, boolean moving) {
        if (!level.isClientSide) {
            boolean powered = level.hasNeighborSignal(pos);
            if (powered != state.getValue(POWERED)) {
                level.setBlock(pos, state.setValue(POWERED, powered), 3);
            }
        }
    }

    @Override
    public VoxelShape getShape(BlockState state, BlockGetter level, BlockPos pos, CollisionContext context) {
        Direction facing = state.getValue(FACING);
        // 6x6x6 emitter box pushed against the face opposite to the beam direction.
        double min = 5.0D, max = 11.0D;
        double x0 = min, x1 = max, y0 = min, y1 = max, z0 = min, z1 = max;
        switch (facing) {
            case NORTH -> { z0 = 8.0D; z1 = 16.0D; }
            case SOUTH -> { z0 = 0.0D; z1 = 8.0D; }
            case WEST -> { x0 = 8.0D; x1 = 16.0D; }
            case EAST -> { x0 = 0.0D; x1 = 8.0D; }
            case UP -> { y0 = 0.0D; y1 = 8.0D; }
            case DOWN -> { y0 = 8.0D; y1 = 16.0D; }
        }
        return Block.box(x0, y0, z0, x1, y1, z1);
    }

    @Override
    public BlockState rotate(BlockState state, Rotation rotation) {
        return state.setValue(FACING, rotation.rotate(state.getValue(FACING)));
    }

    @Override
    public BlockState mirror(BlockState state, Mirror mirror) {
        return state.rotate(mirror.getRotation(state.getValue(FACING)));
    }

    @Override
    public RenderShape getRenderShape(BlockState state) {
        return RenderShape.MODEL;
    }

    @Nullable
    @Override
    public BlockEntity newBlockEntity(BlockPos pos, BlockState state) {
        return new LaserEmitterBlockEntity(pos, state);
    }

    @Nullable
    @Override
    public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level, BlockState state, BlockEntityType<T> type) {
        return level.isClientSide ? null : createTickerHelper(type, ModBlockEntities.LASER_EMITTER.get(), LaserEmitterBlockEntity::serverTick);
    }
}
'''

FILES['src/main/java/com/heistmod/block/MissionBoardBlock.java'] = r'''package com.heistmod.block;

import com.heistmod.menu.MissionBoardMenu;
import com.heistmod.registry.ModSounds;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.SimpleMenuProvider;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.ContainerLevelAccess;
import net.minecraft.world.item.context.BlockPlaceContext;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.HorizontalDirectionalBlock;
import net.minecraft.world.level.block.Mirror;
import net.minecraft.world.level.block.Rotation;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.StateDefinition;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.shapes.CollisionContext;
import net.minecraft.world.phys.shapes.VoxelShape;

/** The Secret Bunker's mission board: right-click for the interactive briefing GUI. */
public class MissionBoardBlock extends HorizontalDirectionalBlock {
    private static final VoxelShape SHAPE_Z = Block.box(0.0D, 0.0D, 5.0D, 16.0D, 16.0D, 11.0D);
    private static final VoxelShape SHAPE_X = Block.box(5.0D, 0.0D, 0.0D, 11.0D, 16.0D, 16.0D);

    public MissionBoardBlock(Properties properties) {
        super(properties);
        registerDefaultState(stateDefinition.any().setValue(FACING, Direction.NORTH));
    }

    @Override
    protected void createBlockStateDefinition(StateDefinition.Builder<Block, BlockState> builder) {
        builder.add(FACING);
    }

    @Override
    public BlockState getStateForPlacement(BlockPlaceContext context) {
        return defaultBlockState().setValue(FACING, context.getHorizontalDirection().getOpposite());
    }

    @Override
    public VoxelShape getShape(BlockState state, BlockGetter level, BlockPos pos, CollisionContext context) {
        return state.getValue(FACING).getAxis() == Direction.Axis.Z ? SHAPE_Z : SHAPE_X;
    }

    @Override
    public BlockState rotate(BlockState state, Rotation rotation) {
        return state.setValue(FACING, rotation.rotate(state.getValue(FACING)));
    }

    @Override
    public BlockState mirror(BlockState state, Mirror mirror) {
        return state.rotate(mirror.getRotation(state.getValue(FACING)));
    }

    @Override
    public InteractionResult use(BlockState state, Level level, BlockPos pos, Player player, InteractionHand hand, BlockHitResult hit) {
        if (level.isClientSide) {
            return InteractionResult.SUCCESS;
        }
        if (player instanceof ServerPlayer serverPlayer) {
            level.playSound(null, pos, ModSounds.BOARD_OPEN.get(), SoundSource.BLOCKS, 0.8F, 1.0F);
            serverPlayer.openMenu(new SimpleMenuProvider((id, inv, p) -> new MissionBoardMenu(id, inv, ContainerLevelAccess.create(level, pos)),
                    Component.translatable("block.heistmod.mission_board")));
            com.heistmod.mission.MissionManager.sync(serverPlayer);
        }
        return InteractionResult.CONSUME;
    }
}
'''

FILES['src/main/java/com/heistmod/block/TrophyPedestalBlock.java'] = r'''package com.heistmod.block;

import com.heistmod.blockentity.TrophyPedestalBlockEntity;
import com.heistmod.registry.ModBlockEntities;
import com.heistmod.registry.ModTags;
import net.minecraft.core.BlockPos;
import net.minecraft.network.chat.Component;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.BaseEntityBlock;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.RenderShape;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.entity.BlockEntityTicker;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.shapes.CollisionContext;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;

import org.jetbrains.annotations.Nullable;

/** A glass-and-brass display pedestal. The quest item hovers above it and spins (rendered by the client BER). */
public class TrophyPedestalBlock extends BaseEntityBlock {
    private static final VoxelShape SHAPE = Shapes.or(
            Block.box(2.0D, 0.0D, 2.0D, 14.0D, 3.0D, 14.0D),
            Block.box(4.0D, 3.0D, 4.0D, 12.0D, 12.0D, 12.0D),
            Block.box(1.0D, 12.0D, 1.0D, 15.0D, 16.0D, 15.0D));

    public TrophyPedestalBlock(Properties properties) {
        super(properties);
    }

    @Override
    public VoxelShape getShape(BlockState state, BlockGetter level, BlockPos pos, CollisionContext context) {
        return SHAPE;
    }

    @Override
    public RenderShape getRenderShape(BlockState state) {
        return RenderShape.MODEL;
    }

    @Nullable
    @Override
    public BlockEntity newBlockEntity(BlockPos pos, BlockState state) {
        return new TrophyPedestalBlockEntity(pos, state);
    }

    @Nullable
    @Override
    public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level, BlockState state, BlockEntityType<T> type) {
        return level.isClientSide ? null : createTickerHelper(type, ModBlockEntities.TROPHY_PEDESTAL.get(), TrophyPedestalBlockEntity::serverTick);
    }

    @Override
    public InteractionResult use(BlockState state, Level level, BlockPos pos, Player player, InteractionHand hand, BlockHitResult hit) {
        BlockEntity be = level.getBlockEntity(pos);
        if (!(be instanceof TrophyPedestalBlockEntity pedestal)) {
            return InteractionResult.PASS;
        }
        ItemStack held = player.getItemInHand(hand);
        // Creative convenience: place a quest item on an empty pedestal (and have it restock).
        if (!pedestal.hasItem() && player.getAbilities().instabuild && held.is(ModTags.QUEST_ITEMS)) {
            if (!level.isClientSide) {
                ItemStack one = held.copy();
                one.setCount(1);
                pedestal.setItem(one, true);
            }
            return InteractionResult.sidedSuccess(level.isClientSide);
        }
        // A ghost's hands pass straight through the display glass (Bhootiya Chaddar).
        if (pedestal.hasItem() && com.heistmod.event.GadgetEvents.wearsSheet(player)) {
            if (!level.isClientSide && player instanceof net.minecraft.server.level.ServerPlayer serverPlayer) {
                ItemStack taken = pedestal.take();
                com.heistmod.mission.MissionManager.giveOrDrop(serverPlayer, taken.copy());
                com.heistmod.mission.MissionManager.onQuestItemObtained(serverPlayer, taken);
                level.playSound(null, pos, com.heistmod.registry.ModSounds.CHINGAM_GRAB.get(), net.minecraft.sounds.SoundSource.PLAYERS, 1.0F, 0.7F);
            }
            return InteractionResult.sidedSuccess(level.isClientSide);
        }
        if (!level.isClientSide) {
            player.displayClientMessage(Component.translatable(pedestal.hasItem() ? "message.heistmod.pedestal.locked" : "message.heistmod.pedestal.empty"), true);
        }
        return InteractionResult.sidedSuccess(level.isClientSide);
    }

    @Override
    public void onRemove(BlockState state, Level level, BlockPos pos, BlockState newState, boolean moving) {
        if (!state.is(newState.getBlock())) {
            BlockEntity be = level.getBlockEntity(pos);
            if (be instanceof TrophyPedestalBlockEntity pedestal) {
                pedestal.dropContents();
            }
        }
        super.onRemove(state, level, pos, newState, moving);
    }
}
'''

FILES['src/main/java/com/heistmod/blockentity/BermudaThailaBlockEntity.java'] = r'''package com.heistmod.blockentity;

import com.heistmod.registry.ModBlockEntities;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.protocol.Packet;
import net.minecraft.network.protocol.game.ClientGamePacketListener;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;

import org.jetbrains.annotations.Nullable;

/** Tracks the bag's lifecycle: closed -> armed (waiting for confirmation) -> open (siphoning). */
public class BermudaThailaBlockEntity extends BlockEntity {
    public enum State { IDLE, ARMED, OPEN }

    private State state = State.IDLE;
    private long armedUntil;
    private long changedAt;

    public BermudaThailaBlockEntity(BlockPos pos, BlockState blockState) {
        super(ModBlockEntities.BERMUDA_THAILA.get(), pos, blockState);
    }

    public State getState() {
        return state;
    }

    public long getChangedAt() {
        return changedAt;
    }

    public long getArmedUntil() {
        return armedUntil;
    }

    public void setState(State newState, long gameTime, long armedUntilTime) {
        this.state = newState;
        this.changedAt = gameTime;
        this.armedUntil = armedUntilTime;
        setChanged();
        if (level != null) {
            level.sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), 3);
        }
    }

    public static void serverTick(Level level, BlockPos pos, BlockState blockState, BermudaThailaBlockEntity be) {
        if (be.state == State.ARMED && level.getGameTime() > be.armedUntil) {
            be.setState(State.IDLE, level.getGameTime(), 0L);
        } else if (be.state == State.OPEN && !com.heistmod.siphon.ChaosSiphonManager.isRunningAt(level, pos)) {
            // A reloaded world must never resume a siphon that is no longer running (jobs are not persisted).
            be.setState(State.IDLE, level.getGameTime(), 0L);
        }
    }

    @Override
    protected void saveAdditional(CompoundTag tag) {
        super.saveAdditional(tag);
        tag.putInt("State", state.ordinal());
        tag.putLong("ArmedUntil", armedUntil);
        tag.putLong("ChangedAt", changedAt);
    }

    @Override
    public void load(CompoundTag tag) {
        super.load(tag);
        State[] values = State.values();
        state = values[Math.max(0, Math.min(values.length - 1, tag.getInt("State")))];
        armedUntil = tag.getLong("ArmedUntil");
        changedAt = tag.getLong("ChangedAt");
    }

    @Override
    public CompoundTag getUpdateTag() {
        return saveWithoutMetadata();
    }

    @Nullable
    @Override
    public Packet<ClientGamePacketListener> getUpdatePacket() {
        return ClientboundBlockEntityDataPacket.create(this);
    }
}
'''

FILES['src/main/java/com/heistmod/blockentity/LaserEmitterBlockEntity.java'] = r'''package com.heistmod.blockentity;

import com.heistmod.HeistConfig;
import com.heistmod.block.LaserEmitterBlock;
import com.heistmod.registry.ModBlockEntities;
import com.heistmod.world.AlarmManager;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.protocol.Packet;
import net.minecraft.network.protocol.game.ClientGamePacketListener;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;

import org.jetbrains.annotations.Nullable;
import java.util.List;

/** Server-side beam length + intruder detection; {@link #getBeamLength()} / {@link #isAlert()} are synced for the renderer. */
public class LaserEmitterBlockEntity extends BlockEntity {
    public static final int MAX_LENGTH = 40;

    private int beamLength;
    private boolean alert;
    private long alertUntil;
    private int cooldown;
    private int ticks;

    public LaserEmitterBlockEntity(BlockPos pos, BlockState state) {
        super(ModBlockEntities.LASER_EMITTER.get(), pos, state);
    }

    public int getBeamLength() {
        return beamLength;
    }

    public boolean isAlert() {
        return alert;
    }

    public void setAlert(boolean value, long untilGameTime) {
        if (alert != value) {
            alert = value;
            alertUntil = untilGameTime;
            sync();
        } else if (value) {
            alertUntil = untilGameTime;
        }
    }

    public static void serverTick(Level level, BlockPos pos, BlockState state, LaserEmitterBlockEntity be) {
        if (state.getValue(LaserEmitterBlock.POWERED)) {
            if (be.beamLength != 0) {
                be.beamLength = 0;
                be.sync();
            }
            return;
        }
        if (be.cooldown > 0) {
            be.cooldown--;
        }
        if (be.ticks++ % 10 == 0) {
            be.recompute(level, pos, state.getValue(LaserEmitterBlock.FACING));
        }
        if (be.alert && level.getGameTime() > be.alertUntil) {
            be.alert = false;
            be.sync();
        }
        if (be.beamLength > 0 && be.cooldown == 0 && (be.ticks & 1) == 0) {
            be.detect(level, pos, state.getValue(LaserEmitterBlock.FACING));
        }
    }

    private void recompute(Level level, BlockPos pos, Direction dir) {
        int length = 0;
        for (int i = 1; i <= MAX_LENGTH; i++) {
            BlockPos p = pos.relative(dir, i);
            if (!level.isLoaded(p)) {
                break;
            }
            BlockState s = level.getBlockState(p);
            if (!s.getCollisionShape(level, p).isEmpty()) {
                break;
            }
            length = i;
        }
        if (length != beamLength) {
            beamLength = length;
            sync();
        }
    }

    private void detect(Level level, BlockPos pos, Direction dir) {
        Vec3 from = Vec3.atCenterOf(pos).relative(dir, 0.55D);
        Vec3 to = Vec3.atCenterOf(pos).relative(dir, beamLength + 0.5D);
        AABB box = new AABB(from, to).inflate(0.07D);
        List<Player> intruders = level.getEntitiesOfClass(Player.class, box,
                p -> p.isAlive() && !p.isSpectator() && !p.isCreative() && !AlarmManager.passesThroughLasers(p));
        if (!intruders.isEmpty() && HeistConfig.LASERS_RAISE_ALARM.get()) {
            cooldown = 100;
            Player culprit = intruders.get(0);
            AlarmManager.trip((net.minecraft.server.level.ServerLevel) level, pos, culprit instanceof ServerPlayer sp ? sp : null);
        }
    }

    private void sync() {
        setChanged();
        if (level != null) {
            level.sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), 3);
        }
    }

    @Override
    protected void saveAdditional(CompoundTag tag) {
        super.saveAdditional(tag);
        tag.putInt("Beam", beamLength);
        tag.putBoolean("Alert", alert);
        tag.putLong("AlertUntil", alertUntil);
    }

    @Override
    public void load(CompoundTag tag) {
        super.load(tag);
        beamLength = tag.getInt("Beam");
        alert = tag.getBoolean("Alert");
        alertUntil = tag.getLong("AlertUntil");
    }

    @Override
    public CompoundTag getUpdateTag() {
        return saveWithoutMetadata();
    }

    @Nullable
    @Override
    public Packet<ClientGamePacketListener> getUpdatePacket() {
        return ClientboundBlockEntityDataPacket.create(this);
    }
}
'''

FILES['src/main/java/com/heistmod/blockentity/TrophyPedestalBlockEntity.java'] = r'''package com.heistmod.blockentity;

import com.heistmod.HeistConfig;
import com.heistmod.registry.ModBlockEntities;
import com.heistmod.registry.ModSounds;
import net.minecraft.core.BlockPos;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.protocol.Packet;
import net.minecraft.network.protocol.game.ClientGamePacketListener;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.Containers;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.Vec3;

import org.jetbrains.annotations.Nullable;
import java.util.Collections;
import java.util.Set;
import java.util.WeakHashMap;

/**
 * Holds one quest item and shows it floating above the pedestal (client renderer). The item can only be removed by
 * the Chingam Grappler / Jeb Katra Gloves logic (or by breaking the block); an emptied pedestal restocks itself so the
 * heist can be replayed.
 */
public class TrophyPedestalBlockEntity extends BlockEntity {
    private static final Set<TrophyPedestalBlockEntity> LOADED = Collections.newSetFromMap(new WeakHashMap<>());

    private ItemStack stack = ItemStack.EMPTY;
    private ItemStack restock = ItemStack.EMPTY;
    private int restockTimer = -1;

    public TrophyPedestalBlockEntity(BlockPos pos, BlockState state) {
        super(ModBlockEntities.TROPHY_PEDESTAL.get(), pos, state);
    }

    // ------------------------------------------------------------------ registry of loaded pedestals (server side)
    public static Set<TrophyPedestalBlockEntity> loaded() {
        return LOADED;
    }

    @Override
    public void setLevel(Level newLevel) {
        super.setLevel(newLevel);
        if (!newLevel.isClientSide) {
            LOADED.add(this);
        }
    }

    @Override
    public void clearRemoved() {
        super.clearRemoved();
        if (level != null && !level.isClientSide) {
            LOADED.add(this);
        }
    }

    @Override
    public void setRemoved() {
        LOADED.remove(this);
        super.setRemoved();
    }

    // ------------------------------------------------------------------ content
    public ItemStack getItem() {
        return stack;
    }

    public boolean hasItem() {
        return !stack.isEmpty();
    }

    /** Sets the displayed item. {@code restockToo} also remembers it as the item to restock after being emptied. */
    public void setItem(ItemStack newStack, boolean restockToo) {
        this.stack = newStack.copy();
        if (restockToo && !newStack.isEmpty()) {
            this.restock = newStack.copy();
            this.restock.setCount(1);
        }
        this.restockTimer = -1;
        sync();
    }

    public ItemStack take() {
        ItemStack out = stack;
        stack = ItemStack.EMPTY;
        int delay = HeistConfig.QUEST_ITEM_RESPAWN_TICKS.get();
        restockTimer = (delay > 0 && !restock.isEmpty()) ? delay : -1;
        sync();
        return out;
    }

    public Vec3 displayCenter() {
        return Vec3.atCenterOf(worldPosition).add(0.0D, 0.95D, 0.0D);
    }

    public void dropContents() {
        if (level != null && !stack.isEmpty()) {
            Containers.dropItemStack(level, worldPosition.getX() + 0.5, worldPosition.getY() + 1.0, worldPosition.getZ() + 0.5, stack);
            stack = ItemStack.EMPTY;
        }
    }

    private void sync() {
        setChanged();
        if (level != null) {
            level.sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), 3);
        }
    }

    // ------------------------------------------------------------------ ticking
    public static void serverTick(Level level, BlockPos pos, BlockState state, TrophyPedestalBlockEntity be) {
        if (be.restockTimer > 0 && --be.restockTimer == 0) {
            be.stack = be.restock.copy();
            be.restockTimer = -1;
            be.sync();
            level.playSound(null, pos, ModSounds.PEDESTAL_RESTOCK.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
            if (level instanceof ServerLevel serverLevel) {
                serverLevel.sendParticles(ParticleTypes.END_ROD, pos.getX() + 0.5, pos.getY() + 1.4, pos.getZ() + 0.5, 20, 0.3, 0.4, 0.3, 0.02);
            }
        }
    }

    // ------------------------------------------------------------------ persistence / sync
    @Override
    protected void saveAdditional(CompoundTag tag) {
        super.saveAdditional(tag);
        if (!stack.isEmpty()) {
            tag.put("Item", stack.save(new CompoundTag()));
        }
        if (!restock.isEmpty()) {
            tag.put("Restock", restock.save(new CompoundTag()));
        }
        tag.putInt("RestockTimer", restockTimer);
    }

    @Override
    public void load(CompoundTag tag) {
        super.load(tag);
        stack = tag.contains("Item") ? ItemStack.of(tag.getCompound("Item")) : ItemStack.EMPTY;
        restock = tag.contains("Restock") ? ItemStack.of(tag.getCompound("Restock")) : ItemStack.EMPTY;
        restockTimer = tag.contains("RestockTimer") ? tag.getInt("RestockTimer") : -1;
    }

    @Override
    public CompoundTag getUpdateTag() {
        return saveWithoutMetadata();
    }

    @Nullable
    @Override
    public Packet<ClientGamePacketListener> getUpdatePacket() {
        return ClientboundBlockEntityDataPacket.create(this);
    }
}
'''

FILES['src/main/java/com/heistmod/client/ClientHeistState.java'] = r'''package com.heistmod.client;

import it.unimi.dsi.fastutil.ints.IntOpenHashSet;
import it.unimi.dsi.fastutil.ints.IntSet;

/** Everything the client knows about the campaign, filled by {@link ClientNetwork}. Render-thread only. */
public final class ClientHeistState {
    // campaign
    public static int activeMission = 1;
    public static int completedMask;
    public static int gadgetMask;
    public static int itemMask;
    public static int diamondsEarned;
    // chaos HUD
    public static long chaos;
    public static boolean siphonActive;
    public static long chaosChangedAt = -10_000L;
    // splat overlay
    public static long splatStart = -10_000L;
    public static int splatDuration;
    public static int splatSeed;
    // alarm flash
    public static long alarmUntil;
    // stripped mobs (boxers layer)
    public static final IntSet STRIPPED = new IntOpenHashSet();
    // rocket burn
    public static int rocketBurnTicks;
    public static double rocketVelocity;
    // client tick counter (never pauses with the integrated server)
    public static long ticks;

    private ClientHeistState() {}

    public static void reset() {
        activeMission = 1;
        completedMask = gadgetMask = itemMask = diamondsEarned = 0;
        chaos = 0;
        siphonActive = false;
        splatStart = -10_000L;
        alarmUntil = 0;
        STRIPPED.clear();
        rocketBurnTicks = 0;
    }
}
'''

FILES['src/main/java/com/heistmod/client/ClientNetwork.java'] = r'''package com.heistmod.client;

import com.heistmod.client.screen.DialogueScreen;
import com.heistmod.network.AlarmFlashPacket;
import com.heistmod.network.ChaosSyncPacket;
import com.heistmod.network.DialogueChoicePacket;
import com.heistmod.network.DialoguePacket;
import com.heistmod.network.HeistPacket;
import com.heistmod.network.RocketBurnPacket;
import com.heistmod.network.SplatPacket;
import com.heistmod.network.StripSyncPacket;
import com.heistmod.network.SyncProgressPacket;
import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking;
import net.fabricmc.fabric.api.networking.v1.PacketByteBufs;
import net.minecraft.client.Minecraft;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.resources.ResourceLocation;

import java.util.function.Consumer;
import java.util.function.Function;

/** Client-bound packet receivers. Decoding happens on the network thread, handling on the render thread. */
public final class ClientNetwork {
    private ClientNetwork() {}

    private static <T> void receive(ResourceLocation id, Function<FriendlyByteBuf, T> decoder, Consumer<T> handler) {
        ClientPlayNetworking.registerGlobalReceiver(id, (client, listener, buf, sender) -> {
            T packet = decoder.apply(buf);
            client.execute(() -> handler.accept(packet));
        });
    }

    public static void register() {
        receive(SyncProgressPacket.ID, SyncProgressPacket::decode, p -> {
            ClientHeistState.activeMission = p.active();
            ClientHeistState.completedMask = p.completed();
            ClientHeistState.gadgetMask = p.gadgets();
            ClientHeistState.itemMask = p.items();
            ClientHeistState.diamondsEarned = p.diamonds();
            if (p.chaos() != ClientHeistState.chaos) {
                ClientHeistState.chaos = p.chaos();
            }
        });
        receive(ChaosSyncPacket.ID, ChaosSyncPacket::decode, p -> {
            if (p.value() != ClientHeistState.chaos || p.siphonActive() != ClientHeistState.siphonActive) {
                ClientHeistState.chaosChangedAt = ClientHeistState.ticks;
            }
            ClientHeistState.chaos = p.value();
            ClientHeistState.siphonActive = p.siphonActive();
        });
        receive(SplatPacket.ID, SplatPacket::decode, p -> {
            ClientHeistState.splatStart = ClientHeistState.ticks;
            ClientHeistState.splatDuration = p.durationTicks();
            ClientHeistState.splatSeed = p.seed();
        });
        receive(AlarmFlashPacket.ID, AlarmFlashPacket::decode, p ->
                ClientHeistState.alarmUntil = Math.max(ClientHeistState.alarmUntil, ClientHeistState.ticks + p.durationTicks()));
        receive(StripSyncPacket.ID, StripSyncPacket::decode, p -> {
            if (p.stripped()) {
                ClientHeistState.STRIPPED.add(p.entityId());
            } else {
                ClientHeistState.STRIPPED.remove(p.entityId());
            }
        });
        receive(RocketBurnPacket.ID, RocketBurnPacket::decode, p -> {
            ClientHeistState.rocketBurnTicks = p.ticks();
            ClientHeistState.rocketVelocity = p.velocity();
        });
        receive(DialoguePacket.ID, DialoguePacket::decode, p -> {
            Minecraft mc = Minecraft.getInstance();
            if (p.close()) {
                if (mc.screen instanceof DialogueScreen) {
                    mc.setScreen(null);
                }
            } else if (mc.screen instanceof DialogueScreen screen && screen.entityId() == p.entityId()) {
                screen.show(p);
            } else {
                mc.setScreen(new DialogueScreen(p));
            }
        });
    }

    public static void send(HeistPacket packet) {
        FriendlyByteBuf buf = PacketByteBufs.create();
        packet.encode(buf);
        ClientPlayNetworking.send(packet.id(), buf);
    }

    public static void choose(int entityId, int option) {
        send(new DialogueChoicePacket(entityId, option));
    }
}
'''

FILES['src/main/java/com/heistmod/client/HeistModClient.java'] = r'''package com.heistmod.client;

import com.heistmod.client.gltf.GltfModels;
import com.heistmod.client.hud.HeistHud;
import com.heistmod.client.render.BoxersLayer;
import com.heistmod.client.render.GltfItemRenderer;
import com.heistmod.client.render.GltfWearableRenderer;
import com.heistmod.client.render.HeistHumanoidRenderer;
import com.heistmod.client.render.LaserEmitterRenderer;
import com.heistmod.client.render.PiglinKingRenderer;
import com.heistmod.client.render.ThailaRenderer;
import com.heistmod.client.render.TrophyPedestalRenderer;
import com.heistmod.client.screen.MissionBoardScreen;
import com.heistmod.registry.ModBlockEntities;
import com.heistmod.registry.ModBlocks;
import com.heistmod.registry.ModEntities;
import com.heistmod.registry.ModItems;
import com.heistmod.registry.ModMenus;
import net.fabricmc.api.ClientModInitializer;
import net.fabricmc.fabric.api.blockrenderlayer.v1.BlockRenderLayerMap;
import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;
import net.fabricmc.fabric.api.client.networking.v1.ClientPlayConnectionEvents;
import net.fabricmc.fabric.api.client.rendering.v1.ArmorRenderer;
import net.fabricmc.fabric.api.client.rendering.v1.BuiltinItemRendererRegistry;
import net.fabricmc.fabric.api.client.rendering.v1.EntityRendererRegistry;
import net.fabricmc.fabric.api.client.rendering.v1.HudRenderCallback;
import net.fabricmc.fabric.api.client.rendering.v1.LivingEntityFeatureRendererRegistrationCallback;
import net.fabricmc.fabric.api.resource.ResourceManagerHelper;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.screens.MenuScreens;
import net.minecraft.client.player.LocalPlayer;
import net.minecraft.client.renderer.RenderType;
import net.minecraft.client.renderer.blockentity.BlockEntityRenderers;
import net.minecraft.server.packs.PackType;
import net.minecraft.world.item.Item;
import net.minecraft.world.phys.Vec3;

/** Client entry point: renderers, glTF pipeline, screens, HUD overlays and client-bound networking. */
public class HeistModClient implements ClientModInitializer {
    @Override
    public void onInitializeClient() {
        ClientNetwork.register();
        ResourceManagerHelper.get(PackType.CLIENT_RESOURCES).registerReloadListener(GltfModels.INSTANCE);

        // ---- items drawn from glTF / GLB models (full resolution, zero decimation)
        Item[] gltfItems = {ModItems.CHINGAM_GRAPPLER.get(), ModItems.JEB_KATRA_GLOVES.get(), ModItems.BHOOTIYA_CHADDAR.get(),
                ModItems.DIWALI_ROCKET.get(), ModItems.BERMUDA_THAILA.get(), ModItems.WARDENS_SQUEAKY_TOY.get(),
                ModItems.PIGLIN_KINGS_GOLDEN_TOOTH.get(), ModItems.HEROBRINES_FORBIDDEN_DIARY.get(), ModItems.ULTIMATE_FORBIDDEN_CORE.get(),
                ModItems.HEIST_DIAMOND.get(), ModItems.HEIST_TOKEN.get(), ModItems.HAVALDAR_LATHI.get(), ModItems.HAVALDAR_CAP.get()};
        for (Item item : gltfItems) {
            BuiltinItemRendererRegistry.INSTANCE.register(item, new GltfItemRenderer());
        }
        ArmorRenderer.register(new GltfWearableRenderer(), ModItems.BHOOTIYA_CHADDAR.get(), ModItems.HAVALDAR_CAP.get());

        // ---- entities
        EntityRendererRegistry.register(ModEntities.AGENT_ZERO.get(), ctx -> new HeistHumanoidRenderer<>(ctx, "agent_zero", 1.0F));
        EntityRendererRegistry.register(ModEntities.BLACK_MARKET_DEALER.get(), ctx -> new HeistHumanoidRenderer<>(ctx, "black_market_dealer", 0.98F));
        EntityRendererRegistry.register(ModEntities.HAVALDAR_THANDULAL.get(), ctx -> new HeistHumanoidRenderer<>(ctx, "havaldar_thandulal", 1.04F));
        EntityRendererRegistry.register(ModEntities.PIGLIN_KING.get(), PiglinKingRenderer::new);
        LivingEntityFeatureRendererRegistrationCallback.EVENT.register(BoxersLayer::attach);

        // ---- block entities & cutout blocks
        BlockEntityRenderers.register(ModBlockEntities.TROPHY_PEDESTAL.get(), TrophyPedestalRenderer::new);
        BlockEntityRenderers.register(ModBlockEntities.LASER_EMITTER.get(), LaserEmitterRenderer::new);
        BlockEntityRenderers.register(ModBlockEntities.BERMUDA_THAILA.get(), ThailaRenderer::new);
        BlockRenderLayerMap.INSTANCE.putBlocks(RenderType.translucent(), ModBlocks.TROPHY_PEDESTAL.get(), ModBlocks.ALARM_BEACON.get());
        BlockRenderLayerMap.INSTANCE.putBlocks(RenderType.cutout(), ModBlocks.MISSION_BOARD.get(), ModBlocks.LASER_EMITTER.get());

        // ---- GUI / HUD
        MenuScreens.register(ModMenus.MISSION_BOARD.get(), MissionBoardScreen::new);
        HudRenderCallback.EVENT.register(HeistHud::render);

        ClientTickEvents.END_CLIENT_TICK.register(HeistModClient::tick);
        ClientPlayConnectionEvents.DISCONNECT.register((handler, client) -> client.execute(ClientHeistState::reset));
    }

    private static void tick(Minecraft mc) {
        ClientHeistState.ticks++;
        LocalPlayer player = mc.player;
        if (player != null && ClientHeistState.rocketBurnTicks > 0) {
            // Tier 4: hold the launch velocity for the computed burn so the apex reaches the configured altitude.
            Vec3 dm = player.getDeltaMovement();
            player.setDeltaMovement(dm.x, Math.max(dm.y, ClientHeistState.rocketVelocity), dm.z);
            ClientHeistState.rocketBurnTicks--;
        }
    }
}
'''

FILES['src/main/java/com/heistmod/client/gltf/Bounds.java'] = r'''package com.heistmod.client.gltf;

import org.joml.Matrix4f;
import org.joml.Vector3f;

/** Rest-pose bounding box (after the sidecar rotation) and the matrix that centres + scales the model to its size. */
public record Bounds(float minX, float minY, float minZ, float maxX, float maxY, float maxZ, Matrix4f normalize) {
    public static final Bounds UNIT = new Bounds(-0.5F, -0.5F, -0.5F, 0.5F, 0.5F, 0.5F, new Matrix4f());

    public static Bounds of(GltfModel model, ModelConfig config) {
        Matrix4f rot = new Matrix4f()
                .rotateZ((float) Math.toRadians(config.rotation[2]))
                .rotateY((float) Math.toRadians(config.rotation[1]))
                .rotateX((float) Math.toRadians(config.rotation[0]));
        Matrix4f[] world = GltfPose.rest(model).world;
        float[] min = {Float.MAX_VALUE, Float.MAX_VALUE, Float.MAX_VALUE};
        float[] max = {-Float.MAX_VALUE, -Float.MAX_VALUE, -Float.MAX_VALUE};
        Vector3f v = new Vector3f();
        for (int n = 0; n < model.nodes.size(); n++) {
            GltfModel.Node node = model.nodes.get(n);
            if (node.mesh < 0 || node.mesh >= model.meshes.size()) {
                continue;
            }
            Matrix4f m = new Matrix4f(rot).mul(node.skin >= 0 ? new Matrix4f() : world[n]);
            for (GltfModel.Primitive prim : model.meshes.get(node.mesh)) {
                float[] p = prim.positions;
                Matrix4f[] skinMats = node.skin >= 0 ? GltfPose.rest(model).jointMatrices(model, node.skin) : null;
                for (int i = 0; i < prim.vertexCount; i++) {
                    v.set(p[i * 3], p[i * 3 + 1], p[i * 3 + 2]);
                    if (skinMats != null && prim.joints != null) {
                        GltfRenderer.skin(prim, i, skinMats, v);
                    }
                    m.transformPosition(v);
                    min[0] = Math.min(min[0], v.x); min[1] = Math.min(min[1], v.y); min[2] = Math.min(min[2], v.z);
                    max[0] = Math.max(max[0], v.x); max[1] = Math.max(max[1], v.y); max[2] = Math.max(max[2], v.z);
                }
            }
        }
        if (min[0] > max[0]) {
            return UNIT;
        }
        float longest = Math.max(max[0] - min[0], Math.max(max[1] - min[1], max[2] - min[2]));
        float scale = longest > 1.0E-6F ? config.size / longest : 1.0F;
        Matrix4f normalize = new Matrix4f()
                .translate(config.offset[0], config.offset[1], config.offset[2])
                .scale(scale)
                .translate(-(min[0] + max[0]) * 0.5F, -(min[1] + max[1]) * 0.5F, -(min[2] + max[2]) * 0.5F)
                .mul(rot);
        return new Bounds(min[0], min[1], min[2], max[0], max[1], max[2], normalize);
    }

    /** Height of the normalised model (blocks). */
    public float height(float size) {
        float longest = Math.max(maxX - minX, Math.max(maxY - minY, maxZ - minZ));
        return longest > 0 ? (maxY - minY) * size / longest : size;
    }
}
'''

FILES['src/main/java/com/heistmod/client/gltf/GltfModel.java'] = r'''package com.heistmod.client.gltf;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.packs.resources.ResourceManager;
import org.jetbrains.annotations.Nullable;
import org.joml.Matrix4f;
import org.joml.Quaternionf;

import java.io.IOException;
import java.io.InputStream;
import java.net.URLDecoder;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;

/**
 * A parsed glTF 2.0 asset ({@code .gltf} + {@code .bin} + images, or a single {@code .glb}). Geometry is kept exactly as
 * authored: every vertex and triangle is rendered, nothing is decimated, welded or re-indexed. Supports the node
 * hierarchy (TRS and matrix), multiple meshes / primitives / materials, skins (JOINTS_0 / WEIGHTS_0) and animations
 * (translation / rotation / scale, LINEAR / STEP / CUBICSPLINE).
 */
public final class GltfModel {
    // ------------------------------------------------------------------ data
    public static final class Node {
        public String name = "";
        public int mesh = -1;
        public int skin = -1;
        public int[] children = new int[0];
        @Nullable
        public Matrix4f matrix;
        public final float[] t = {0, 0, 0};
        public final float[] r = {0, 0, 0, 1};
        public final float[] s = {1, 1, 1};
        public int parent = -1;
    }

    public static final class Primitive {
        public float[] positions;
        public float[] normals;
        public float[] uvs;
        public int[] indices;
        @Nullable
        public int[] joints;
        @Nullable
        public float[] weights;
        public int material = -1;
        public int vertexCount;
        /** Per-frame transform scratch (render thread only) so drawing allocates nothing. */
        float[] scratchPos;
        float[] scratchNrm;
    }

    public static final class Material {
        @Nullable
        public ResourceLocation texture;
        public final float[] baseColor = {1, 1, 1, 1};
        public boolean blend;
        public boolean doubleSided = true;
    }

    public static final class Skin {
        public int[] joints;
        public Matrix4f[] inverseBind;
    }

    public static final class Channel {
        public int node;
        public int path; // 0 translation, 1 rotation, 2 scale
        public int interpolation; // 0 linear, 1 step, 2 cubic spline
        public float[] times;
        public float[] values;
    }

    public static final class Animation {
        public String name;
        public float duration;
        public final List<Channel> channels = new ArrayList<>();
    }

    public final String id;
    public final List<Node> nodes = new ArrayList<>();
    public final List<List<Primitive>> meshes = new ArrayList<>();
    public final List<Material> materials = new ArrayList<>();
    public final List<Skin> skins = new ArrayList<>();
    public final List<Animation> animations = new ArrayList<>();
    public int[] roots = new int[0];
    /** Image sources: resource location of the PNG, or raw bytes for embedded images. */
    public final List<Object> images = new ArrayList<>();
    public int triangleCount;

    private GltfModel(String id) {
        this.id = id;
    }

    @Nullable
    public Animation animation(String name) {
        for (Animation a : animations) {
            if (a.name.equalsIgnoreCase(name)) {
                return a;
            }
        }
        return null;
    }

    // ------------------------------------------------------------------ loading
    public static GltfModel load(ResourceManager manager, String id, ResourceLocation file) throws IOException {
        byte[] data = read(manager, file);
        String path = file.getPath();
        String dir = path.substring(0, path.lastIndexOf('/') + 1);
        JsonObject json;
        ByteBuffer glbBin = null;
        if (data.length >= 12 && le(data, 0) == 0x46546C67) {
            ByteBuffer bb = ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN);
            int offset = 12;
            String jsonText = null;
            while (offset + 8 <= data.length) {
                int chunkLength = bb.getInt(offset);
                int chunkType = bb.getInt(offset + 4);
                if (chunkType == 0x4E4F534A) {
                    jsonText = new String(data, offset + 8, chunkLength, StandardCharsets.UTF_8);
                } else if (chunkType == 0x004E4942) {
                    glbBin = ByteBuffer.wrap(data, offset + 8, chunkLength).slice().order(ByteOrder.LITTLE_ENDIAN);
                }
                offset += 8 + chunkLength;
            }
            if (jsonText == null) {
                throw new IOException("GLB without JSON chunk: " + file);
            }
            json = JsonParser.parseString(jsonText).getAsJsonObject();
        } else {
            json = JsonParser.parseString(new String(data, StandardCharsets.UTF_8)).getAsJsonObject();
        }
        GltfModel model = new GltfModel(id);
        new Reader(model, manager, file.getNamespace(), dir, json, glbBin).read();
        return model;
    }

    private static int le(byte[] b, int o) {
        return (b[o] & 0xFF) | (b[o + 1] & 0xFF) << 8 | (b[o + 2] & 0xFF) << 16 | (b[o + 3] & 0xFF) << 24;
    }

    static byte[] read(ResourceManager manager, ResourceLocation file) throws IOException {
        try (InputStream in = manager.getResourceOrThrow(file).open()) {
            return in.readAllBytes();
        }
    }

    private static final class Reader {
        final GltfModel model;
        final ResourceManager manager;
        final String namespace;
        final String dir;
        final JsonObject json;
        final List<ByteBuffer> buffers = new ArrayList<>();

        Reader(GltfModel model, ResourceManager manager, String namespace, String dir, JsonObject json, @Nullable ByteBuffer glbBin) throws IOException {
            this.model = model;
            this.manager = manager;
            this.namespace = namespace;
            this.dir = dir;
            this.json = json;
            for (JsonElement e : arr("buffers")) {
                JsonObject b = e.getAsJsonObject();
                if (!b.has("uri")) {
                    buffers.add(glbBin);
                } else {
                    buffers.add(ByteBuffer.wrap(uri(b.get("uri").getAsString())).order(ByteOrder.LITTLE_ENDIAN));
                }
            }
        }

        JsonArray arr(String key) {
            return json.has(key) ? json.getAsJsonArray(key) : new JsonArray();
        }

        byte[] uri(String uri) throws IOException {
            if (uri.startsWith("data:")) {
                return Base64.getDecoder().decode(uri.substring(uri.indexOf(',') + 1));
            }
            return GltfModel.read(manager, new ResourceLocation(namespace, dir + sanitize(uri)));
        }

        void read() throws IOException {
            readImages();
            readMaterials();
            readNodes();
            readMeshes();
            readSkins();
            readAnimations();
            JsonArray scenes = arr("scenes");
            int scene = json.has("scene") ? json.get("scene").getAsInt() : 0;
            if (scenes.size() > scene && scenes.get(scene).getAsJsonObject().has("nodes")) {
                model.roots = ints(scenes.get(scene).getAsJsonObject().getAsJsonArray("nodes"));
            } else {
                List<Integer> roots = new ArrayList<>();
                for (int i = 0; i < model.nodes.size(); i++) {
                    if (model.nodes.get(i).parent < 0) {
                        roots.add(i);
                    }
                }
                model.roots = roots.stream().mapToInt(Integer::intValue).toArray();
            }
        }

        void readImages() {
            JsonArray images = arr("images");
            for (int i = 0; i < images.size(); i++) {
                JsonObject im = images.get(i).getAsJsonObject();
                if (im.has("uri") && !im.get("uri").getAsString().startsWith("data:")) {
                    model.images.add(new ResourceLocation(namespace, dir + sanitize(im.get("uri").getAsString())));
                } else {
                    try {
                        model.images.add(im.has("uri") ? uri(im.get("uri").getAsString()) : bufferViewBytes(im.get("bufferView").getAsInt()));
                    } catch (IOException e) {
                        model.images.add(null);
                    }
                }
            }
        }

        void readMaterials() {
            JsonArray textures = arr("textures");
            for (JsonElement e : arr("materials")) {
                JsonObject m = e.getAsJsonObject();
                Material mat = new Material();
                mat.doubleSided = !m.has("doubleSided") || m.get("doubleSided").getAsBoolean();
                mat.blend = m.has("alphaMode") && "BLEND".equals(m.get("alphaMode").getAsString());
                if (m.has("pbrMetallicRoughness")) {
                    JsonObject pbr = m.getAsJsonObject("pbrMetallicRoughness");
                    if (pbr.has("baseColorFactor")) {
                        JsonArray f = pbr.getAsJsonArray("baseColorFactor");
                        for (int i = 0; i < 4; i++) {
                            mat.baseColor[i] = f.get(i).getAsFloat();
                        }
                    }
                    if (pbr.has("baseColorTexture")) {
                        int tex = pbr.getAsJsonObject("baseColorTexture").get("index").getAsInt();
                        if (tex < textures.size() && textures.get(tex).getAsJsonObject().has("source")) {
                            mat.texture = GltfModels.textureFor(model, textures.get(tex).getAsJsonObject().get("source").getAsInt());
                        }
                    }
                }
                model.materials.add(mat);
            }
        }

        void readNodes() {
            JsonArray nodes = arr("nodes");
            for (JsonElement e : nodes) {
                JsonObject n = e.getAsJsonObject();
                Node node = new Node();
                node.name = n.has("name") ? n.get("name").getAsString() : "";
                node.mesh = n.has("mesh") ? n.get("mesh").getAsInt() : -1;
                node.skin = n.has("skin") ? n.get("skin").getAsInt() : -1;
                node.children = n.has("children") ? ints(n.getAsJsonArray("children")) : new int[0];
                if (n.has("matrix")) {
                    float[] m = floats(n.getAsJsonArray("matrix"));
                    node.matrix = new Matrix4f().set(m);
                }
                if (n.has("translation")) {
                    System.arraycopy(floats(n.getAsJsonArray("translation")), 0, node.t, 0, 3);
                }
                if (n.has("rotation")) {
                    System.arraycopy(floats(n.getAsJsonArray("rotation")), 0, node.r, 0, 4);
                }
                if (n.has("scale")) {
                    System.arraycopy(floats(n.getAsJsonArray("scale")), 0, node.s, 0, 3);
                }
                model.nodes.add(node);
            }
            for (int i = 0; i < model.nodes.size(); i++) {
                for (int c : model.nodes.get(i).children) {
                    if (c >= 0 && c < model.nodes.size()) {
                        model.nodes.get(c).parent = i;
                    }
                }
            }
        }

        void readMeshes() {
            for (JsonElement e : arr("meshes")) {
                List<Primitive> prims = new ArrayList<>();
                for (JsonElement pe : e.getAsJsonObject().getAsJsonArray("primitives")) {
                    JsonObject p = pe.getAsJsonObject();
                    int mode = p.has("mode") ? p.get("mode").getAsInt() : 4;
                    if (mode != 4) {
                        continue; // points / lines / strips are not drawable as entity triangles
                    }
                    JsonObject attrs = p.getAsJsonObject("attributes");
                    if (!attrs.has("POSITION")) {
                        continue;
                    }
                    Primitive prim = new Primitive();
                    prim.positions = floatAccessor(attrs.get("POSITION").getAsInt());
                    prim.vertexCount = prim.positions.length / 3;
                    prim.normals = attrs.has("NORMAL") ? floatAccessor(attrs.get("NORMAL").getAsInt()) : null;
                    prim.uvs = attrs.has("TEXCOORD_0") ? floatAccessor(attrs.get("TEXCOORD_0").getAsInt()) : new float[prim.vertexCount * 2];
                    if (attrs.has("JOINTS_0") && attrs.has("WEIGHTS_0")) {
                        prim.joints = intAccessor(attrs.get("JOINTS_0").getAsInt());
                        prim.weights = floatAccessor(attrs.get("WEIGHTS_0").getAsInt());
                    }
                    if (p.has("indices")) {
                        prim.indices = intAccessor(p.get("indices").getAsInt());
                    } else {
                        prim.indices = new int[prim.vertexCount];
                        for (int i = 0; i < prim.indices.length; i++) {
                            prim.indices[i] = i;
                        }
                    }
                    if (prim.normals == null) {
                        prim.normals = flatNormals(prim.positions, prim.indices);
                    }
                    prim.material = p.has("material") ? p.get("material").getAsInt() : -1;
                    model.triangleCount += prim.indices.length / 3;
                    prims.add(prim);
                }
                model.meshes.add(prims);
            }
        }

        void readSkins() {
            for (JsonElement e : arr("skins")) {
                JsonObject s = e.getAsJsonObject();
                Skin skin = new Skin();
                skin.joints = ints(s.getAsJsonArray("joints"));
                skin.inverseBind = new Matrix4f[skin.joints.length];
                float[] ibm = s.has("inverseBindMatrices") ? floatAccessor(s.get("inverseBindMatrices").getAsInt()) : null;
                for (int j = 0; j < skin.joints.length; j++) {
                    skin.inverseBind[j] = ibm == null ? new Matrix4f() : new Matrix4f().set(ibm, j * 16);
                }
                model.skins.add(skin);
            }
        }

        void readAnimations() {
            int index = 0;
            for (JsonElement e : arr("animations")) {
                JsonObject a = e.getAsJsonObject();
                Animation anim = new Animation();
                anim.name = a.has("name") ? a.get("name").getAsString() : "animation_" + index;
                index++;
                JsonArray samplers = a.getAsJsonArray("samplers");
                for (JsonElement ce : a.getAsJsonArray("channels")) {
                    JsonObject c = ce.getAsJsonObject();
                    JsonObject target = c.getAsJsonObject("target");
                    if (!target.has("node")) {
                        continue;
                    }
                    String path = target.get("path").getAsString();
                    int p = switch (path) {
                        case "translation" -> 0;
                        case "rotation" -> 1;
                        case "scale" -> 2;
                        default -> -1;
                    };
                    if (p < 0) {
                        continue; // morph target weights are not supported
                    }
                    JsonObject sampler = samplers.get(c.get("sampler").getAsInt()).getAsJsonObject();
                    Channel ch = new Channel();
                    ch.node = target.get("node").getAsInt();
                    ch.path = p;
                    String interp = sampler.has("interpolation") ? sampler.get("interpolation").getAsString() : "LINEAR";
                    ch.interpolation = "STEP".equals(interp) ? 1 : "CUBICSPLINE".equals(interp) ? 2 : 0;
                    ch.times = floatAccessor(sampler.get("input").getAsInt());
                    ch.values = floatAccessor(sampler.get("output").getAsInt());
                    if (ch.times.length > 0) {
                        anim.duration = Math.max(anim.duration, ch.times[ch.times.length - 1]);
                    }
                    anim.channels.add(ch);
                }
                model.animations.add(anim);
            }
        }

        // -------------------------------------------------------------- accessors
        byte[] bufferViewBytes(int view) {
            JsonObject bv = arr("bufferViews").get(view).getAsJsonObject();
            ByteBuffer buf = buffers.get(bv.get("buffer").getAsInt());
            int offset = bv.has("byteOffset") ? bv.get("byteOffset").getAsInt() : 0;
            byte[] out = new byte[bv.get("byteLength").getAsInt()];
            for (int i = 0; i < out.length; i++) {
                out[i] = buf.get(offset + i);
            }
            return out;
        }

        private interface Sink {
            void put(int index, double value);
        }

        private void accessor(int index, boolean normalizeInts, Sink sink) {
            JsonObject acc = arr("accessors").get(index).getAsJsonObject();
            int count = acc.get("count").getAsInt();
            int comps = switch (acc.get("type").getAsString()) {
                case "SCALAR" -> 1;
                case "VEC2" -> 2;
                case "VEC3" -> 3;
                case "VEC4", "MAT2" -> 4;
                case "MAT3" -> 9;
                default -> 16;
            };
            int ctype = acc.get("componentType").getAsInt();
            int csize = ctype == 5120 || ctype == 5121 ? 1 : ctype == 5122 || ctype == 5123 ? 2 : 4;
            boolean normalized = normalizeInts && acc.has("normalized") && acc.get("normalized").getAsBoolean();
            if (!acc.has("bufferView")) {
                for (int i = 0; i < count * comps; i++) {
                    sink.put(i, 0.0D);
                }
                return;
            }
            JsonObject bv = arr("bufferViews").get(acc.get("bufferView").getAsInt()).getAsJsonObject();
            ByteBuffer buf = buffers.get(bv.get("buffer").getAsInt());
            int base = (bv.has("byteOffset") ? bv.get("byteOffset").getAsInt() : 0) + (acc.has("byteOffset") ? acc.get("byteOffset").getAsInt() : 0);
            int stride = bv.has("byteStride") ? bv.get("byteStride").getAsInt() : comps * csize;
            for (int i = 0; i < count; i++) {
                int at = base + i * stride;
                for (int c = 0; c < comps; c++) {
                    int o = at + c * csize;
                    double v = switch (ctype) {
                        case 5120 -> normalized ? Math.max(buf.get(o) / 127.0D, -1.0D) : buf.get(o);
                        case 5121 -> normalized ? (buf.get(o) & 0xFF) / 255.0D : buf.get(o) & 0xFF;
                        case 5122 -> normalized ? Math.max(buf.getShort(o) / 32767.0D, -1.0D) : buf.getShort(o);
                        case 5123 -> normalized ? (buf.getShort(o) & 0xFFFF) / 65535.0D : buf.getShort(o) & 0xFFFF;
                        case 5125 -> buf.getInt(o) & 0xFFFFFFFFL;
                        default -> buf.getFloat(o);
                    };
                    sink.put(i * comps + c, v);
                }
            }
        }

        float[] floatAccessor(int index) {
            JsonObject acc = arr("accessors").get(index).getAsJsonObject();
            int n = acc.get("count").getAsInt() * compCount(acc.get("type").getAsString());
            float[] out = new float[n];
            // integer weights / UVs are normalised per spec when flagged; un-normalised ints stay as-is (KHR_mesh_quantization)
            accessor(index, true, (i, v) -> out[i] = (float) v);
            return out;
        }

        int[] intAccessor(int index) {
            JsonObject acc = arr("accessors").get(index).getAsJsonObject();
            int[] out = new int[acc.get("count").getAsInt() * compCount(acc.get("type").getAsString())];
            accessor(index, false, (i, v) -> out[i] = (int) v);
            return out;
        }

        static int compCount(String type) {
            return switch (type) {
                case "SCALAR" -> 1;
                case "VEC2" -> 2;
                case "VEC3" -> 3;
                case "VEC4", "MAT2" -> 4;
                case "MAT3" -> 9;
                default -> 16;
            };
        }

        static int[] ints(JsonArray a) {
            int[] out = new int[a.size()];
            for (int i = 0; i < out.length; i++) {
                out[i] = a.get(i).getAsInt();
            }
            return out;
        }

        static float[] floats(JsonArray a) {
            float[] out = new float[a.size()];
            for (int i = 0; i < out.length; i++) {
                out[i] = a.get(i).getAsFloat();
            }
            return out;
        }

        static float[] flatNormals(float[] pos, int[] idx) {
            float[] n = new float[pos.length];
            for (int t = 0; t + 2 < idx.length; t += 3) {
                int a = idx[t] * 3, b = idx[t + 1] * 3, c = idx[t + 2] * 3;
                float ux = pos[b] - pos[a], uy = pos[b + 1] - pos[a + 1], uz = pos[b + 2] - pos[a + 2];
                float vx = pos[c] - pos[a], vy = pos[c + 1] - pos[a + 1], vz = pos[c + 2] - pos[a + 2];
                float nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
                for (int k : new int[]{a, b, c}) {
                    n[k] += nx;
                    n[k + 1] += ny;
                    n[k + 2] += nz;
                }
            }
            for (int i = 0; i < n.length; i += 3) {
                float l = (float) Math.sqrt(n[i] * n[i] + n[i + 1] * n[i + 1] + n[i + 2] * n[i + 2]);
                if (l > 1.0E-6F) {
                    n[i] /= l;
                    n[i + 1] /= l;
                    n[i + 2] /= l;
                } else {
                    n[i + 1] = 1.0F;
                }
            }
            return n;
        }
    }

    /**
     * Resource paths must be lower-case {@code [a-z0-9/._-]}. build_mod.py sanitises dropped-in model folders the same way
     * (and rewrites the URIs), so both sides agree on the file names.
     */
    public static String sanitize(String uri) {
        String decoded = URLDecoder.decode(uri, StandardCharsets.UTF_8).replace('\\', '/');
        StringBuilder out = new StringBuilder();
        String[] parts = decoded.split("/");
        for (int p = 0; p < parts.length; p++) {
            String part = parts[p].toLowerCase(java.util.Locale.ROOT).replaceAll("[^a-z0-9._-]", "_");
            while (part.startsWith(".") && part.length() > 1 && !part.equals("..")) {
                part = part.substring(1);
            }
            if (p > 0) {
                out.append('/');
            }
            out.append(part);
        }
        return out.toString();
    }

    /** Local transform of a node from the given TRS (or its fixed matrix). */
    public static Matrix4f local(Node node, float[] t, float[] r, float[] s) {
        if (node.matrix != null) {
            return new Matrix4f(node.matrix);
        }
        return new Matrix4f().translation(t[0], t[1], t[2]).rotate(new Quaternionf(r[0], r[1], r[2], r[3]).normalize()).scale(s[0], s[1], s[2]);
    }
}
'''

FILES['src/main/java/com/heistmod/client/gltf/GltfModels.java'] = r'''package com.heistmod.client.gltf;

import com.heistmod.HeistMod;
import net.fabricmc.fabric.api.resource.SimpleSynchronousResourceReloadListener;
import net.minecraft.client.Minecraft;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.packs.resources.Resource;
import net.minecraft.server.packs.resources.ResourceManager;
import org.jetbrains.annotations.Nullable;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * Drop-in model registry. A model is a folder {@code assets/heistmod/models/gltf/<id>/} holding {@code model.glb},
 * {@code model.gltf} or {@code scene.gltf} (+ .bin + textures), and optionally {@code heist_model.json}. Models are
 * looked up by id at render time, so adding or replacing one never needs Java changes or re-registration.
 * Everything is cleared on F3+T so textures / meshes can be iterated live.
 */
public final class GltfModels implements SimpleSynchronousResourceReloadListener {
    public static final GltfModels INSTANCE = new GltfModels();
    private static final String[] FILES = {"model.glb", "model.gltf", "scene.glb", "scene.gltf"};

    public record Entry(@Nullable GltfModel model, ModelConfig config, Bounds bounds) {}

    private final Map<String, Entry> cache = new HashMap<>();
    private final List<ResourceLocation> textures = new ArrayList<>();

    private GltfModels() {}

    @Override
    public ResourceLocation getFabricId() {
        return HeistMod.id("gltf_models");
    }

    @Override
    public void onResourceManagerReload(ResourceManager manager) {
        for (ResourceLocation tex : textures) {
            Minecraft.getInstance().getTextureManager().release(tex);
        }
        textures.clear();
        cache.clear();
    }

    public static Entry get(String id) {
        return INSTANCE.cache.computeIfAbsent(id, INSTANCE::load);
    }

    private Entry load(String id) {
        ResourceManager manager = Minecraft.getInstance().getResourceManager();
        String dir = "models/gltf/" + id + "/";
        ModelConfig config = ModelConfig.defaults();
        Optional<Resource> sidecar = manager.getResource(HeistMod.id(dir + "heist_model.json"));
        if (sidecar.isPresent()) {
            try (InputStream in = sidecar.get().open()) {
                config = ModelConfig.parse(new String(in.readAllBytes(), StandardCharsets.UTF_8));
            } catch (IOException | RuntimeException e) {
                HeistMod.LOGGER.warn("Bad sidecar for glTF model {}", id, e);
            }
        }
        for (String file : FILES) {
            ResourceLocation location = HeistMod.id(dir + file);
            if (manager.getResource(location).isEmpty()) {
                continue;
            }
            try {
                long start = System.nanoTime();
                GltfModel model = GltfModel.load(manager, id, location);
                Bounds bounds = Bounds.of(model, config);
                HeistMod.LOGGER.info("[glTF] {} loaded: {} triangles, {} nodes, {} animations in {} ms", id, model.triangleCount,
                        model.nodes.size(), model.animations.size(), (System.nanoTime() - start) / 1_000_000L);
                return new Entry(model, config, bounds);
            } catch (Exception e) {
                HeistMod.LOGGER.error("[glTF] failed to load {}", location, e);
            }
        }
        HeistMod.LOGGER.warn("[glTF] no model found for '{}' (expected {}model.glb / model.gltf)", id, dir);
        return new Entry(null, config, Bounds.UNIT);
    }

    /** Registers (once) a trilinear-filtered texture for image {@code index} of {@code model}. */
    static ResourceLocation textureFor(GltfModel model, int index) {
        Object source = index < model.images.size() ? model.images.get(index) : null;
        ResourceLocation id;
        GltfTexture texture;
        if (source instanceof ResourceLocation rl) {
            id = rl;
            texture = new GltfTexture(rl);
        } else if (source instanceof byte[] bytes) {
            id = HeistMod.id("gltf_embedded/" + model.id + "/" + index);
            texture = new GltfTexture(bytes);
        } else {
            return new ResourceLocation("minecraft", "textures/misc/white.png");
        }
        if (!INSTANCE.textures.contains(id)) {
            INSTANCE.textures.add(id);
            Minecraft.getInstance().getTextureManager().register(id, texture);
        }
        return id;
    }
}
'''

FILES['src/main/java/com/heistmod/client/gltf/GltfPose.java'] = r'''package com.heistmod.client.gltf;

import org.jetbrains.annotations.Nullable;
import org.joml.Matrix4f;
import org.joml.Quaternionf;

/** World matrices of every node for one animation time (or the rest pose). */
public final class GltfPose {
    public final Matrix4f[] world;

    private GltfPose(Matrix4f[] world) {
        this.world = world;
    }

    public static GltfPose rest(GltfModel model) {
        return sample(model, null, 0.0F);
    }

    /** Samples {@code animation} at {@code time} seconds (looping). */
    public static GltfPose sample(GltfModel model, @Nullable GltfModel.Animation animation, float time) {
        int n = model.nodes.size();
        float[][] t = new float[n][];
        float[][] r = new float[n][];
        float[][] s = new float[n][];
        for (int i = 0; i < n; i++) {
            GltfModel.Node node = model.nodes.get(i);
            t[i] = node.t.clone();
            r[i] = node.r.clone();
            s[i] = node.s.clone();
        }
        if (animation != null && animation.duration > 0.0F) {
            float at = time % animation.duration;
            for (GltfModel.Channel ch : animation.channels) {
                if (ch.node < 0 || ch.node >= n) {
                    continue;
                }
                float[] target = ch.path == 0 ? t[ch.node] : ch.path == 1 ? r[ch.node] : s[ch.node];
                evaluate(ch, at, target);
            }
        }
        Matrix4f[] world = new Matrix4f[n];
        for (int root : model.roots) {
            build(model, root, new Matrix4f(), t, r, s, world);
        }
        for (int i = 0; i < n; i++) {
            if (world[i] == null) {
                build(model, i, new Matrix4f(), t, r, s, world);
            }
        }
        return new GltfPose(world);
    }

    private static void build(GltfModel model, int index, Matrix4f parent, float[][] t, float[][] r, float[][] s, Matrix4f[] world) {
        if (index < 0 || index >= world.length || world[index] != null) {
            return;
        }
        GltfModel.Node node = model.nodes.get(index);
        Matrix4f m = new Matrix4f(parent).mul(GltfModel.local(node, t[index], r[index], s[index]));
        world[index] = m;
        for (int c : node.children) {
            build(model, c, m, t, r, s, world);
        }
    }

    private static void evaluate(GltfModel.Channel ch, float time, float[] out) {
        int comps = out.length;
        float[] times = ch.times;
        int keys = times.length;
        if (keys == 0) {
            return;
        }
        boolean cubic = ch.interpolation == 2;
        int stride = cubic ? comps * 3 : comps;
        int valueOffset = cubic ? comps : 0;
        if (time <= times[0] || keys == 1) {
            System.arraycopy(ch.values, valueOffset, out, 0, comps);
            return;
        }
        if (time >= times[keys - 1]) {
            System.arraycopy(ch.values, (keys - 1) * stride + valueOffset, out, 0, comps);
            return;
        }
        int k = 0;
        while (k < keys - 2 && times[k + 1] < time) {
            k++;
        }
        float f = (time - times[k]) / Math.max(1.0E-6F, times[k + 1] - times[k]);
        int a = k * stride + valueOffset;
        int b = (k + 1) * stride + valueOffset;
        if (ch.interpolation == 1) {
            System.arraycopy(ch.values, a, out, 0, comps);
        } else if (comps == 4) {
            Quaternionf qa = new Quaternionf(ch.values[a], ch.values[a + 1], ch.values[a + 2], ch.values[a + 3]);
            Quaternionf qb = new Quaternionf(ch.values[b], ch.values[b + 1], ch.values[b + 2], ch.values[b + 3]);
            qa.slerp(qb, f);
            out[0] = qa.x; out[1] = qa.y; out[2] = qa.z; out[3] = qa.w;
        } else {
            for (int i = 0; i < comps; i++) {
                out[i] = ch.values[a + i] + (ch.values[b + i] - ch.values[a + i]) * f;
            }
        }
    }

    /** jointWorld * inverseBind for every joint of {@code skin}. */
    public Matrix4f[] jointMatrices(GltfModel model, int skin) {
        GltfModel.Skin s = model.skins.get(skin);
        Matrix4f[] out = new Matrix4f[s.joints.length];
        for (int j = 0; j < out.length; j++) {
            Matrix4f w = s.joints[j] < world.length && world[s.joints[j]] != null ? world[s.joints[j]] : new Matrix4f();
            out[j] = new Matrix4f(w).mul(s.inverseBind[j]);
        }
        return out;
    }
}
'''

FILES['src/main/java/com/heistmod/client/gltf/GltfRenderer.java'] = r'''package com.heistmod.client.gltf;

import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.blaze3d.vertex.VertexConsumer;
import net.minecraft.client.renderer.MultiBufferSource;
import net.minecraft.client.renderer.RenderType;
import net.minecraft.client.renderer.texture.OverlayTexture;
import net.minecraft.resources.ResourceLocation;
import org.jetbrains.annotations.Nullable;
import org.joml.Matrix3f;
import org.joml.Matrix4f;
import org.joml.Vector3f;

/**
 * Immediate-mode glTF renderer. Every triangle is submitted as-is (as a degenerate quad, the format entity render types
 * expect), through the normal {@link MultiBufferSource}, so lighting, overlay tint, render ordering and shader packs all
 * behave exactly like vanilla entity geometry.
 */
public final class GltfRenderer {
    private static final ResourceLocation WHITE = new ResourceLocation("minecraft", "textures/misc/white.png");

    private GltfRenderer() {}

    /** Renders the model normalised (centred, longest edge = config size) at the current pose origin. */
    public static void render(GltfModels.Entry entry, @Nullable String animation, float timeSeconds, PoseStack pose,
                              MultiBufferSource buffers, int light, int overlay, float alpha) {
        GltfModel model = entry.model();
        if (model == null) {
            return;
        }
        GltfModel.Animation anim = animation == null ? null : model.animation(animation);
        if (anim == null && animation != null && !model.animations.isEmpty() && "*".equals(animation)) {
            anim = model.animations.get(0);
        }
        GltfPose gltfPose = anim == null ? cachedRest(entry) : GltfPose.sample(model, anim, timeSeconds);
        PoseStack.Pose last = pose.last();
        Matrix4f base = new Matrix4f(last.pose()).mul(entry.bounds().normalize());
        Matrix3f normalBase = new Matrix3f(last.normal()).mul(new Matrix3f(entry.bounds().normalize()));
        for (int n = 0; n < model.nodes.size(); n++) {
            GltfModel.Node node = model.nodes.get(n);
            if (node.mesh < 0 || node.mesh >= model.meshes.size()) {
                continue;
            }
            boolean skinned = node.skin >= 0 && node.skin < model.skins.size();
            Matrix4f[] joints = skinned ? gltfPose.jointMatrices(model, node.skin) : null;
            Matrix4f m = skinned ? new Matrix4f(base) : new Matrix4f(base).mul(gltfPose.world[n]);
            Matrix3f nm = skinned ? new Matrix3f(normalBase) : new Matrix3f(normalBase).mul(new Matrix3f(gltfPose.world[n]));
            for (GltfModel.Primitive prim : model.meshes.get(node.mesh)) {
                GltfModel.Material mat = prim.material >= 0 && prim.material < model.materials.size() ? model.materials.get(prim.material) : null;
                ResourceLocation tex = mat != null && mat.texture != null ? mat.texture : WHITE;
                boolean blend = (mat != null && mat.blend) || alpha < 0.999F;
                RenderType type = blend ? RenderType.entityTranslucent(tex) : RenderType.entityCutoutNoCull(tex);
                float[] color = mat != null ? mat.baseColor : new float[]{1, 1, 1, 1};
                emit(buffers.getBuffer(type), prim, joints, m, nm, color[0], color[1], color[2], color[3] * alpha, light, overlay);
            }
        }
    }

    private static final java.util.WeakHashMap<GltfModels.Entry, GltfPose> REST = new java.util.WeakHashMap<>();

    private static GltfPose cachedRest(GltfModels.Entry entry) {
        return REST.computeIfAbsent(entry, e -> GltfPose.rest(e.model()));
    }

    private static void emit(VertexConsumer vc, GltfModel.Primitive prim, @Nullable Matrix4f[] joints, Matrix4f m, Matrix3f nm,
                             float r, float g, float b, float a, int light, int overlay) {
        int count = prim.vertexCount;
        if (prim.scratchPos == null || prim.scratchPos.length < count * 3) {
            prim.scratchPos = new float[count * 3];
            prim.scratchNrm = new float[count * 3];
        }
        float[] px = prim.scratchPos;
        float[] nx = prim.scratchNrm;
        Vector3f v = new Vector3f();
        Vector3f nv = new Vector3f();
        Matrix4f skinMat = new Matrix4f();
        for (int i = 0; i < count; i++) {
            v.set(prim.positions[i * 3], prim.positions[i * 3 + 1], prim.positions[i * 3 + 2]);
            nv.set(prim.normals[i * 3], prim.normals[i * 3 + 1], prim.normals[i * 3 + 2]);
            if (joints != null && prim.joints != null && prim.weights != null) {
                blend(prim, i, joints, skinMat);
                skinMat.transformPosition(v);
                skinMat.transformDirection(nv);
            }
            m.transformPosition(v);
            nm.transform(nv);
            nv.normalize();
            px[i * 3] = v.x;
            px[i * 3 + 1] = v.y;
            px[i * 3 + 2] = v.z;
            nx[i * 3] = nv.x;
            nx[i * 3 + 1] = nv.y;
            nx[i * 3 + 2] = nv.z;
        }
        int[] idx = prim.indices;
        float[] uv = prim.uvs;
        for (int t = 0; t + 2 < idx.length; t += 3) {
            for (int k = 0; k < 4; k++) {
                int i = idx[t + Math.min(k, 2)];
                if (i < 0 || i >= count) {
                    i = 0;
                }
                vc.vertex(px[i * 3], px[i * 3 + 1], px[i * 3 + 2], r, g, b, a, uv[i * 2], uv[i * 2 + 1],
                        overlay, light, nx[i * 3], nx[i * 3 + 1], nx[i * 3 + 2]);
            }
        }
    }

    private static final float[] JOINT = new float[16];
    private static final float[] ACC = new float[16];

    /** Linear blend skinning matrix of one vertex (weights renormalised so badly exported files still look right). */
    private static void blend(GltfModel.Primitive prim, int vertex, Matrix4f[] joints, Matrix4f out) {
        java.util.Arrays.fill(ACC, 0.0F);
        float total = 0.0F;
        for (int k = 0; k < 4; k++) {
            float w = prim.weights[vertex * 4 + k];
            int j = prim.joints[vertex * 4 + k];
            if (w <= 0.0F || j < 0 || j >= joints.length) {
                continue;
            }
            joints[j].get(JOINT);
            for (int i = 0; i < 16; i++) {
                ACC[i] += JOINT[i] * w;
            }
            total += w;
        }
        if (total <= 1.0E-6F) {
            out.identity();
            return;
        }
        if (Math.abs(total - 1.0F) > 1.0E-3F) {
            for (int i = 0; i < 16; i++) {
                ACC[i] /= total;
            }
        }
        out.set(ACC);
    }

    /** Position-only skinning used when measuring bounds. */
    static void skin(GltfModel.Primitive prim, int vertex, Matrix4f[] joints, Vector3f v) {
        Matrix4f m = new Matrix4f();
        blend(prim, vertex, joints, m);
        m.transformPosition(v);
    }

    public static int fullBright() {
        return 0xF000F0;
    }

    public static int noOverlay() {
        return OverlayTexture.NO_OVERLAY;
    }
}
'''

FILES['src/main/java/com/heistmod/client/gltf/GltfTexture.java'] = r'''package com.heistmod.client.gltf;

import com.mojang.blaze3d.platform.NativeImage;
import com.mojang.blaze3d.platform.TextureUtil;
import com.mojang.blaze3d.systems.RenderSystem;
import net.minecraft.client.renderer.texture.AbstractTexture;
import net.minecraft.client.renderer.texture.MipmapGenerator;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.packs.resources.ResourceManager;
import org.jetbrains.annotations.Nullable;
import org.lwjgl.opengl.GL11;
import org.lwjgl.opengl.GL12;

import java.io.IOException;
import java.io.InputStream;

/**
 * Albedo texture of a glTF material, uploaded with a full mip chain and trilinear filtering so 2K-8K PBR textures stay
 * crisp and shimmer-free at any distance (vanilla entity textures use nearest filtering without mipmaps).
 * Normal / specular maps placed next to the albedo as {@code name_n.png} / {@code name_s.png} (LabPBR) are picked up by
 * shader packs; the vanilla pipeline only samples the albedo.
 */
public class GltfTexture extends AbstractTexture {
    private static final int MAX_LEVELS = 8;

    @Nullable
    private final ResourceLocation source;
    @Nullable
    private final byte[] embedded;

    public GltfTexture(ResourceLocation source) {
        this.source = source;
        this.embedded = null;
    }

    public GltfTexture(byte[] embedded) {
        this.source = null;
        this.embedded = embedded;
    }

    @Override
    public void load(ResourceManager manager) throws IOException {
        NativeImage image;
        if (embedded != null) {
            image = NativeImage.read(embedded);
        } else {
            try (InputStream in = manager.getResourceOrThrow(source).open()) {
                image = NativeImage.read(in);
            }
        }
        if (!RenderSystem.isOnRenderThreadOrInit()) {
            NativeImage finalImage = image;
            RenderSystem.recordRenderCall(() -> upload(finalImage));
        } else {
            upload(image);
        }
    }

    private void upload(NativeImage image) {
        int w = image.getWidth();
        int h = image.getHeight();
        int levels = 0;
        while (levels < MAX_LEVELS && (w >> (levels + 1)) >= 1 && (h >> (levels + 1)) >= 1) {
            levels++;
        }
        NativeImage[] mips = MipmapGenerator.generateMipLevels(new NativeImage[]{image}, levels);
        TextureUtil.prepareImage(getId(), levels, w, h);
        for (int level = 0; level < mips.length; level++) {
            NativeImage mip = mips[level];
            mip.upload(level, 0, 0, 0, 0, mip.getWidth(), mip.getHeight(), true, false, levels > 0, true);
        }
        bind();
        GL11.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_MIN_FILTER, levels > 0 ? GL11.GL_LINEAR_MIPMAP_LINEAR : GL11.GL_LINEAR);
        GL11.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_MAG_FILTER, GL11.GL_LINEAR);
        GL11.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_WRAP_S, GL11.GL_REPEAT);
        GL11.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_WRAP_T, GL11.GL_REPEAT);
        GL11.glTexParameteri(GL11.GL_TEXTURE_2D, GL12.GL_TEXTURE_MAX_LEVEL, levels);
    }
}
'''

FILES['src/main/java/com/heistmod/client/gltf/ModelConfig.java'] = r'''package com.heistmod.client.gltf;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.math.Axis;

import java.util.HashMap;
import java.util.Map;

/**
 * Optional sidecar {@code heist_model.json} next to a model. Lets dropped-in models be positioned without touching Java:
 * <pre>
 * { "size": 1.0,                       // longest edge after normalisation (blocks)
 *   "rotation": [0, 90, 0],            // degrees, applied to the raw model before it is measured
 *   "offset": [0, 0, 0],
 *   "contexts": { "gui": {"rotation": [30, 225, 0], "translation": [0, 0, 0], "scale": 1.0}, ...,
 *                 "firstperson_righthand", "thirdperson_righthand", "ground", "fixed", "head", "block", "wear" },
 *   "animations": { "idle": "Idle", "wave": "Wave", "scared": "Scared" } }
 * </pre>
 */
public final class ModelConfig {
    public record Transform(float[] rotation, float[] translation, float scale) {
        public static final Transform IDENTITY = new Transform(new float[3], new float[3], 1.0F);

        public void apply(PoseStack pose) {
            pose.translate(translation[0], translation[1], translation[2]);
            pose.mulPose(Axis.ZP.rotationDegrees(rotation[2]));
            pose.mulPose(Axis.YP.rotationDegrees(rotation[1]));
            pose.mulPose(Axis.XP.rotationDegrees(rotation[0]));
            pose.scale(scale, scale, scale);
        }
    }

    public float size = 1.0F;
    public float[] rotation = new float[3];
    public float[] offset = new float[3];
    public final Map<String, Transform> contexts = new HashMap<>();
    public final Map<String, String> animations = new HashMap<>();

    public static ModelConfig defaults() {
        ModelConfig c = new ModelConfig();
        c.contexts.put("gui", new Transform(new float[]{25, -135, 0}, new float[3], 0.85F));
        c.contexts.put("ground", new Transform(new float[3], new float[]{0, -0.15F, 0}, 0.5F));
        c.contexts.put("fixed", new Transform(new float[]{0, 180, 0}, new float[3], 0.8F));
        c.contexts.put("firstperson_righthand", new Transform(new float[]{0, -90, 15}, new float[]{0.1F, 0.1F, 0}, 0.7F));
        c.contexts.put("firstperson_lefthand", new Transform(new float[]{0, 90, -15}, new float[]{-0.1F, 0.1F, 0}, 0.7F));
        c.contexts.put("thirdperson_righthand", new Transform(new float[]{70, 0, 0}, new float[]{0, 0.1F, 0.05F}, 0.55F));
        c.contexts.put("thirdperson_lefthand", new Transform(new float[]{70, 0, 0}, new float[]{0, 0.1F, 0.05F}, 0.55F));
        c.contexts.put("head", new Transform(new float[3], new float[]{0, 0.4F, 0}, 0.8F));
        return c;
    }

    public Transform context(String name) {
        Transform t = contexts.get(name);
        if (t == null && name.endsWith("lefthand")) {
            t = contexts.get(name.replace("lefthand", "righthand"));
        }
        return t == null ? Transform.IDENTITY : t;
    }

    public String animation(String role, String fallback) {
        return animations.getOrDefault(role, fallback);
    }

    public static ModelConfig parse(String text) {
        ModelConfig c = defaults();
        JsonObject o = JsonParser.parseString(text).getAsJsonObject();
        if (o.has("size")) {
            c.size = o.get("size").getAsFloat();
        }
        if (o.has("rotation")) {
            c.rotation = vec(o.getAsJsonArray("rotation"));
        }
        if (o.has("offset")) {
            c.offset = vec(o.getAsJsonArray("offset"));
        }
        if (o.has("contexts")) {
            for (Map.Entry<String, JsonElement> e : o.getAsJsonObject("contexts").entrySet()) {
                JsonObject t = e.getValue().getAsJsonObject();
                c.contexts.put(e.getKey(), new Transform(
                        t.has("rotation") ? vec(t.getAsJsonArray("rotation")) : new float[3],
                        t.has("translation") ? vec(t.getAsJsonArray("translation")) : new float[3],
                        t.has("scale") ? t.get("scale").getAsFloat() : 1.0F));
            }
        }
        if (o.has("animations")) {
            for (Map.Entry<String, JsonElement> e : o.getAsJsonObject("animations").entrySet()) {
                c.animations.put(e.getKey(), e.getValue().getAsString());
            }
        }
        return c;
    }

    private static float[] vec(JsonArray a) {
        return new float[]{a.get(0).getAsFloat(), a.get(1).getAsFloat(), a.get(2).getAsFloat()};
    }
}
'''

FILES['src/main/java/com/heistmod/client/hud/HeistHud.java'] = r'''package com.heistmod.client.hud;

import com.heistmod.client.ClientHeistState;
import com.heistmod.mission.Mission;
import com.mojang.blaze3d.systems.RenderSystem;
import net.minecraft.ChatFormatting;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.Font;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.Mth;

import java.util.Random;

/** All HUD overlays: bubblegum splat, police-light alarm flash, the Chaos counter and the mission tracker. */
public final class HeistHud {
    private HeistHud() {}

    public static void render(GuiGraphics g, float partial) {
        Minecraft mc = Minecraft.getInstance();
        if (mc.player == null || mc.options.hideGui) {
            return;
        }
        int w = g.guiWidth();
        int h = g.guiHeight();
        float now = ClientHeistState.ticks + partial;
        alarm(g, w, h, now);
        tracker(g, mc.font, now);
        chaos(g, mc.font, w, now);
        splat(g, w, h, now);
    }

    // ------------------------------------------------------------------ Tier 1 side effect: bubblegum splat
    private static void splat(GuiGraphics g, int w, int h, float now) {
        float elapsed = now - ClientHeistState.splatStart;
        int duration = ClientHeistState.splatDuration;
        if (duration <= 0 || elapsed < 0 || elapsed > duration + 14) {
            return;
        }
        float impact = Mth.clamp(elapsed / 3.0F, 0, 1);                 // splats in with a squash
        float dissolve = Mth.clamp((elapsed - duration) / 14.0F, 0, 1); // then melts away
        float alpha = 1.0F - dissolve * dissolve;
        float scale = 1.25F - 0.25F * (1.0F - (1.0F - impact) * (1.0F - impact)) + dissolve * 0.05F;
        float sag = elapsed * 0.35F + dissolve * h * 0.25F;

        RenderSystem.enableBlend();
        RenderSystem.defaultBlendFunc();
        g.setColor(1.0F, 1.0F, 1.0F, alpha);
        ResourceLocation tex = SplatTexture.splat(ClientHeistState.splatSeed);
        int sw = (int) (w * scale);
        int sh = (int) (h * scale);
        int sx = (w - sw) / 2;
        int sy = (h - sh) / 2 + (int) sag;
        g.blit(tex, sx, sy, sw, sh, 0.0F, 0.0F, SplatTexture.W, SplatTexture.H, SplatTexture.W, SplatTexture.H);

        // viscous drips crawling down from the splat's underside
        Random rnd = new Random(ClientHeistState.splatSeed);
        ResourceLocation drip = SplatTexture.drip();
        for (int i = 0; i < 7; i++) {
            float dx = w * (0.25F + rnd.nextFloat() * 0.5F);
            float dy = h * (0.45F + rnd.nextFloat() * 0.15F) + sag;
            float speed = 2.0F + rnd.nextFloat() * 4.5F;
            float len = Math.min(h * (0.25F + rnd.nextFloat() * 0.35F), Math.max(0, elapsed - 3) * speed);
            int dw = (int) (w * (0.012F + rnd.nextFloat() * 0.012F));
            if (len > 2) {
                g.blit(drip, (int) dx - dw / 2, (int) dy, dw, (int) len, 0.0F, 0.0F, 48, 384, 48, 384);
            }
        }
        g.setColor(1.0F, 1.0F, 1.0F, 1.0F);
        RenderSystem.disableBlend();
    }

    // ------------------------------------------------------------------ red / blue police lights
    private static void alarm(GuiGraphics g, int w, int h, float now) {
        if (ClientHeistState.alarmUntil <= now) {
            return;
        }
        boolean red = ((int) (now / 6)) % 2 == 0;
        float pulse = 0.5F + 0.5F * (float) Math.sin(now * 0.5F);
        int a = (int) (40 + 60 * pulse);
        int color = (a << 24) | (red ? 0xFF1A1A : 0x1A4BFF);
        int band = h / 6;
        g.fillGradient(0, 0, w, band, color, color & 0x00FFFFFF);
        g.fillGradient(0, h - band, w, h, color & 0x00FFFFFF, color);
    }

    // ------------------------------------------------------------------ Tier 5: Chaos: X / 10,000,000
    private static void chaos(GuiGraphics g, Font font, int w, float now) {
        long value = ClientHeistState.chaos;
        boolean recent = now - ClientHeistState.chaosChangedAt < 600;
        if (value <= 0 || !(ClientHeistState.siphonActive || recent)) {
            return;
        }
        Component text = Component.translatable("hud.heistmod.chaos", String.format("%,d", value), "10,000,000").withStyle(ChatFormatting.BOLD);
        int tw = font.width(text);
        int x = (w - tw) / 2;
        int y = 8;
        int jitter = ClientHeistState.siphonActive ? (int) (Math.sin(now * 3.1) * 1.5) : 0;
        g.fill(x - 8, y - 4, x + tw + 8, y + 22, 0xB0100018);
        g.drawString(font, text, x + jitter + 1, y + 1, 0xFF7A00FF, false);
        g.drawString(font, text, x - jitter, y, value >= 10_000_000L ? 0xFFFFD447 : 0xFFFF5FD2, false);
        int barW = tw + 10;
        int bx = x - 5;
        float pct = Math.min(1.0F, value / 10_000_000.0F);
        g.fill(bx, y + 12, bx + barW, y + 18, 0xFF2A1238);
        g.fillGradient(bx, y + 12, bx + (int) (barW * pct), y + 18, 0xFFB000FF, 0xFFFF3FA4);
    }

    // ------------------------------------------------------------------ mission tracker
    private static void tracker(GuiGraphics g, Font font, float now) {
        Mission m = Mission.byTier(ClientHeistState.activeMission);
        if (m == null || Minecraft.getInstance().screen != null) {
            return;
        }
        boolean got = (ClientHeistState.itemMask & m.bit()) != 0;
        boolean done = (ClientHeistState.completedMask & m.bit()) != 0;
        Component title = Component.translatable(m.langKey("title"));
        Component objective = done ? Component.translatable("hud.heistmod.objective.done")
                : got && m.hasQuestItem() ? Component.translatable("hud.heistmod.objective.sell")
                : Component.translatable(m.langKey("objective"));
        Component header = Component.translatable("hud.heistmod.mission", m.tier);
        int width = Math.max(font.width(title), font.width(objective)) + 12;
        g.fill(4, 4, 4 + width, 38, 0x90081018);
        g.fill(4, 4, 6, 38, 0xFFFF5FB4);
        g.drawString(font, header, 10, 7, 0xFF3FE0FF, false);
        g.drawString(font, title, 10, 17, 0xFFFFFFFF, false);
        g.drawString(font, objective, 10, 27, 0xFFB8C4D6, false);
    }
}
'''

FILES['src/main/java/com/heistmod/client/hud/SplatTexture.java'] = r'''package com.heistmod.client.hud;

import com.heistmod.HeistMod;
import com.heistmod.client.gltf.GltfTexture;
import com.mojang.blaze3d.platform.NativeImage;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.texture.DynamicTexture;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.Mth;

import java.util.HashMap;
import java.util.Map;
import java.util.Random;

/**
 * Procedural, resolution-independent bubblegum: metaball blobs + spatter + stringy streaks, shaded from the field
 * gradient (diffuse + sharp wet specular + rim darkening) and a few trapped air bubbles. Generated once per variant.
 * Drop a PNG at {@code assets/heistmod/textures/gui/chingam_splat.png} (any size, up to 8K) to replace it.
 */
public final class SplatTexture {
    public static final int W = 1280;
    public static final int H = 720;
    private static final ResourceLocation OVERRIDE = HeistMod.id("textures/gui/chingam_splat.png");
    private static final Map<Integer, ResourceLocation> CACHE = new HashMap<>();
    private static ResourceLocation drip;
    private static Boolean overridePresent;

    private SplatTexture() {}

    public static ResourceLocation splat(int seed) {
        if (overridePresent == null) {
            overridePresent = Minecraft.getInstance().getResourceManager().getResource(OVERRIDE).isPresent();
            if (overridePresent) {
                Minecraft.getInstance().getTextureManager().register(OVERRIDE, new GltfTexture(OVERRIDE));
            }
        }
        if (overridePresent) {
            return OVERRIDE;
        }
        int variant = Math.floorMod(seed, 4);
        return CACHE.computeIfAbsent(variant, v -> upload("chingam_splat_" + v, generate(v)));
    }

    public static ResourceLocation drip() {
        if (drip == null) {
            drip = upload("chingam_drip", generateDrip());
        }
        return drip;
    }

    public static void reset() {
        CACHE.clear();
        drip = null;
        overridePresent = null;
    }

    private static ResourceLocation upload(String name, NativeImage image) {
        DynamicTexture texture = new DynamicTexture(image);
        ResourceLocation id = Minecraft.getInstance().getTextureManager().register(HeistMod.MODID + "_" + name, texture);
        texture.setFilter(true, false);
        return id;
    }

    // ------------------------------------------------------------------ generation
    private static NativeImage generate(int variant) {
        Random rnd = new Random(0x5EEDL * 31 + variant);
        float[] field = new float[W * H];
        float cx = W * (0.42F + rnd.nextFloat() * 0.16F);
        float cy = H * (0.38F + rnd.nextFloat() * 0.14F);
        blob(field, cx, cy, H * 0.20F);
        for (int i = 0; i < 14; i++) {                       // lumpy body
            double a = rnd.nextDouble() * Math.PI * 2;
            double d = H * (0.12 + rnd.nextDouble() * 0.16);
            blob(field, (float) (cx + Math.cos(a) * d * 1.5), (float) (cy + Math.sin(a) * d), H * (0.05F + rnd.nextFloat() * 0.08F));
        }
        for (int s = 0; s < 7; s++) {                        // stringy streaks flung outward
            double a = rnd.nextDouble() * Math.PI * 2;
            float len = H * (0.25F + rnd.nextFloat() * 0.35F);
            for (int k = 0; k < 16; k++) {
                float f = k / 16.0F;
                blob(field, (float) (cx + Math.cos(a) * len * (0.3 + f) * 1.6), (float) (cy + Math.sin(a) * len * (0.3 + f)), H * 0.022F * (1.2F - f));
            }
        }
        for (int i = 0; i < 70; i++) {                       // spatter
            float x = rnd.nextFloat() * W;
            float y = rnd.nextFloat() * H;
            blob(field, x, y, H * (0.004F + rnd.nextFloat() * 0.016F));
        }
        NativeImage img = new NativeImage(W, H, true);
        float lx = -0.45F, ly = -0.65F, lz = 0.62F;
        float hl = (float) Math.sqrt(lx * lx + ly * ly + (lz + 1) * (lz + 1));
        float hx = lx / hl, hy = ly / hl, hz = (lz + 1) / hl;
        for (int y = 0; y < H; y++) {
            for (int x = 0; x < W; x++) {
                float f = field[y * W + x];
                if (f < 0.6F) {
                    img.setPixelRGBA(x, y, 0);
                    continue;
                }
                float fx = field[y * W + Math.min(W - 1, x + 1)] - field[y * W + Math.max(0, x - 1)];
                float fy = field[Math.min(H - 1, y + 1) * W + x] - field[Math.max(0, y - 1) * W + x];
                float nx = -fx * 1.6F, ny = -fy * 1.6F, nz = 1.0F;
                float nl = (float) Math.sqrt(nx * nx + ny * ny + nz * nz);
                nx /= nl; ny /= nl; nz /= nl;
                float diffuse = Math.max(0.0F, nx * lx + ny * ly + nz * lz);
                float spec = (float) Math.pow(Math.max(0.0F, nx * hx + ny * hy + nz * hz), 60.0F);
                float thick = Mth.clamp((f - 1.0F) / 4.0F, 0.0F, 1.0F);
                float edge = Mth.clamp((f - 0.6F) / 0.5F, 0.0F, 1.0F);
                float r = (0.98F - 0.08F * thick) * (0.55F + 0.55F * diffuse);
                float g = (0.42F - 0.14F * thick) * (0.55F + 0.55F * diffuse);
                float b = (0.72F - 0.06F * thick) * (0.55F + 0.55F * diffuse);
                float rim = 1.0F - 0.35F * (1.0F - edge);
                r = Mth.clamp(r * rim + spec * 0.95F, 0, 1);
                g = Mth.clamp(g * rim + spec * 0.95F, 0, 1);
                b = Mth.clamp(b * rim + spec * 0.95F, 0, 1);
                float alpha = Mth.clamp(edge * 0.97F, 0, 1);
                img.setPixelRGBA(x, y, abgr(alpha, r, g, b));
            }
        }
        for (int i = 0; i < 5; i++) {                         // trapped air bubbles
            bubble(img, field, cx + (rnd.nextFloat() - 0.5F) * H * 0.4F, cy + (rnd.nextFloat() - 0.5F) * H * 0.3F, H * (0.015F + rnd.nextFloat() * 0.03F));
        }
        return img;
    }

    private static void blob(float[] field, float bx, float by, float r) {
        int reach = (int) (r * 3.2F);
        float r2 = r * r;
        for (int y = Math.max(0, (int) by - reach); y < Math.min(H, (int) by + reach); y++) {
            for (int x = Math.max(0, (int) bx - reach); x < Math.min(W, (int) bx + reach); x++) {
                float dx = x - bx, dy = y - by;
                field[y * W + x] += r2 / (dx * dx + dy * dy + 1.0F);
            }
        }
    }

    private static void bubble(NativeImage img, float[] field, float bx, float by, float r) {
        for (int y = (int) (by - r - 2); y <= by + r + 2; y++) {
            for (int x = (int) (bx - r - 2); x <= bx + r + 2; x++) {
                if (x < 0 || y < 0 || x >= W || y >= H || field[y * W + x] < 1.0F) {
                    continue;
                }
                float d = (float) Math.sqrt((x - bx) * (x - bx) + (y - by) * (y - by)) / r;
                if (d > 1.05F) {
                    continue;
                }
                int c = img.getPixelRGBA(x, y);
                float a = ((c >>> 24) & 0xFF) / 255.0F;
                float rr = (c & 0xFF) / 255.0F, gg = ((c >> 8) & 0xFF) / 255.0F, bb = ((c >> 16) & 0xFF) / 255.0F;
                float ring = Mth.clamp(1.0F - Math.abs(d - 0.92F) * 10.0F, 0, 1);
                float glint = (x - bx) < -r * 0.2F && (y - by) < -r * 0.2F && d > 0.55F && d < 0.8F ? 0.9F : 0.0F;
                float inner = d < 0.9F ? 0.55F : 1.0F;
                img.setPixelRGBA(x, y, abgr(a * inner, Mth.clamp(rr + ring * 0.25F + glint, 0, 1), Mth.clamp(gg + ring * 0.2F + glint, 0, 1), Mth.clamp(bb + ring * 0.25F + glint, 0, 1)));
            }
        }
    }

    private static NativeImage generateDrip() {
        int w = 48, h = 384;
        NativeImage img = new NativeImage(w, h, true);
        for (int y = 0; y < h; y++) {
            float t = y / (float) h;
            float half = 9.0F * (float) Math.sqrt(1.0F - t * 0.85F) + (t > 0.86F ? 0 : 0);
            float bulbY = h - 22.0F;
            for (int x = 0; x < w; x++) {
                float dx = x - w / 2.0F;
                float inBody = half - Math.abs(dx);
                float db = (float) Math.sqrt(dx * dx + (y - bulbY) * (y - bulbY));
                float inBulb = 15.0F - db;
                float edge = Math.max(inBody, inBulb);
                if (edge <= 0) {
                    img.setPixelRGBA(x, y, 0);
                    continue;
                }
                float nx = inBulb > inBody ? dx / 15.0F : dx / Math.max(1.0F, half);
                float shade = 0.65F + 0.35F * (1.0F - Math.abs(nx));
                float spec = nx < -0.35F && nx > -0.65F ? 0.7F : 0.0F;
                float a = Mth.clamp(edge / 2.0F, 0, 1) * 0.97F;
                img.setPixelRGBA(x, y, abgr(a, Mth.clamp(0.98F * shade + spec, 0, 1), Mth.clamp(0.40F * shade + spec, 0, 1), Mth.clamp(0.70F * shade + spec, 0, 1)));
            }
        }
        return img;
    }

    private static int abgr(float a, float r, float g, float b) {
        return ((int) (a * 255) & 0xFF) << 24 | ((int) (b * 255) & 0xFF) << 16 | ((int) (g * 255) & 0xFF) << 8 | ((int) (r * 255) & 0xFF);
    }
}
'''

FILES['src/main/java/com/heistmod/client/render/BoxersLayer.java'] = r'''package com.heistmod.client.render;

import com.heistmod.HeistMod;
import com.heistmod.client.ClientHeistState;
import com.mojang.blaze3d.vertex.PoseStack;
import net.fabricmc.fabric.api.client.rendering.v1.LivingEntityFeatureRendererRegistrationCallback;
import net.minecraft.client.model.EntityModel;
import net.minecraft.client.model.HumanoidArmorModel;
import net.minecraft.client.model.HumanoidModel;
import net.minecraft.client.model.geom.ModelLayers;
import net.minecraft.client.renderer.MultiBufferSource;
import net.minecraft.client.renderer.RenderType;
import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.LivingEntityRenderer;
import net.minecraft.client.renderer.entity.RenderLayerParent;
import net.minecraft.client.renderer.entity.layers.RenderLayer;
import net.minecraft.client.renderer.texture.OverlayTexture;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.LivingEntity;

/** A mob robbed by the Jeb Katra Gloves is left standing in heart-print boxers (any humanoid-shaped mob). */
public class BoxersLayer<T extends LivingEntity, M extends HumanoidModel<T>> extends RenderLayer<T, M> {
    private static final ResourceLocation TEXTURE = HeistMod.id("textures/entity/boxers.png");
    private final HumanoidArmorModel<T> shorts;

    public BoxersLayer(RenderLayerParent<T, M> parent, EntityRendererProvider.Context ctx) {
        super(parent);
        this.shorts = new HumanoidArmorModel<>(ctx.bakeLayer(ModelLayers.PLAYER_INNER_ARMOR));
    }

    @SuppressWarnings({"unchecked", "rawtypes"})
    public static void attach(EntityType<? extends LivingEntity> type, LivingEntityRenderer<?, ?> renderer,
                              LivingEntityFeatureRendererRegistrationCallback.RegistrationHelper helper, EntityRendererProvider.Context ctx) {
        EntityModel<?> model = renderer.getModel();
        if (model instanceof HumanoidModel) {
            helper.register(new BoxersLayer((RenderLayerParent) renderer, ctx));
        }
    }

    @Override
    public void render(PoseStack pose, MultiBufferSource buffers, int light, T entity, float limbSwing, float limbSwingAmount,
                       float partialTick, float ageInTicks, float netHeadYaw, float headPitch) {
        if (!ClientHeistState.STRIPPED.contains(entity.getId())) {
            return;
        }
        getParentModel().copyPropertiesTo(shorts);
        shorts.setAllVisible(false);
        shorts.body.visible = true;
        shorts.rightLeg.visible = true;
        shorts.leftLeg.visible = true;
        shorts.renderToBuffer(pose, buffers.getBuffer(RenderType.armorCutoutNoCull(TEXTURE)), light, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
    }
}
'''

FILES['src/main/java/com/heistmod/client/render/GltfItemRenderer.java'] = r'''package com.heistmod.client.render;

import com.heistmod.client.ClientHeistState;
import com.heistmod.client.gltf.GltfModels;
import com.heistmod.client.gltf.GltfRenderer;
import com.heistmod.client.gltf.ModelConfig;
import com.heistmod.registry.ModItems;
import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.math.Axis;
import net.fabricmc.fabric.api.client.rendering.v1.BuiltinItemRendererRegistry;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.MultiBufferSource;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemDisplayContext;
import net.minecraft.world.item.ItemStack;

/**
 * Draws an item from {@code models/gltf/<item id>/} in every display context (GUI, hands, ground, item frames, head).
 * The full mesh is used everywhere - there is no low-poly stand-in. Per-context placement comes from the sidecar.
 */
public class GltfItemRenderer implements BuiltinItemRendererRegistry.DynamicItemRenderer {
    @Override
    public void render(ItemStack stack, ItemDisplayContext mode, PoseStack pose, MultiBufferSource buffers, int light, int overlay) {
        Item item = stack.getItem();
        String id = BuiltInRegistries.ITEM.getKey(item).getPath();
        GltfModels.Entry entry = GltfModels.get(id);
        Minecraft mc = Minecraft.getInstance();
        float partial = mc.getFrameTime();
        pose.pushPose();
        pose.translate(0.5F, 0.5F, 0.5F);
        ModelConfig.Transform transform = entry.config().context(contextName(mode));
        transform.apply(pose);
        if (item == ModItems.CHINGAM_GRAPPLER.get() && mc.player != null && mode != ItemDisplayContext.GUI) {
            recoil(pose, mc.player.getCooldowns().getCooldownPercent(item, partial));
        }
        String anim = entry.config().animation("idle", null);
        float time = (ClientHeistState.ticks + partial) / 20.0F;
        GltfRenderer.render(entry, anim, time, pose, buffers, light, overlay, 1.0F);
        pose.popPose();
    }

    /** Snappy revolver kick driven by the item cooldown (no extra sync needed). */
    private static void recoil(PoseStack pose, float cooldown) {
        if (cooldown <= 0.0F) {
            return;
        }
        float kick = Math.max(0.0F, (cooldown - 0.55F) / 0.45F);
        kick = kick * kick * (3.0F - 2.0F * kick);
        pose.translate(0.0F, 0.04F * kick, 0.18F * kick);
        pose.mulPose(Axis.XP.rotationDegrees(-22.0F * kick));
    }

    public static String contextName(ItemDisplayContext mode) {
        return switch (mode) {
            case GUI -> "gui";
            case GROUND -> "ground";
            case FIXED -> "fixed";
            case HEAD -> "head";
            case FIRST_PERSON_RIGHT_HAND -> "firstperson_righthand";
            case FIRST_PERSON_LEFT_HAND -> "firstperson_lefthand";
            case THIRD_PERSON_RIGHT_HAND -> "thirdperson_righthand";
            case THIRD_PERSON_LEFT_HAND -> "thirdperson_lefthand";
            default -> "none";
        };
    }
}
'''

FILES['src/main/java/com/heistmod/client/render/GltfWearableRenderer.java'] = r'''package com.heistmod.client.render;

import com.heistmod.client.gltf.GltfModels;
import com.heistmod.client.gltf.GltfRenderer;
import com.heistmod.item.GltfWearable;
import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.math.Axis;
import net.fabricmc.fabric.api.client.rendering.v1.ArmorRenderer;
import net.minecraft.client.Minecraft;
import net.minecraft.client.model.HumanoidModel;
import net.minecraft.client.renderer.MultiBufferSource;
import net.minecraft.client.renderer.texture.OverlayTexture;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.monster.Enemy;
import net.minecraft.world.item.ItemStack;

/**
 * Worn glTF models (Fabric ArmorRenderer): the Bhootiya Chaddar becomes the animated Cute Ghost wrapped around the
 * wearer, the Havaldar cap sits on the head. The "wear" sidecar transform positions the model relative to the body
 * part (model space, y pointing down, 1 unit = 1 block).
 */
public class GltfWearableRenderer implements ArmorRenderer {
    @Override
    public void render(PoseStack pose, MultiBufferSource buffers, ItemStack stack, LivingEntity entity, EquipmentSlot slot, int light,
                       HumanoidModel<LivingEntity> model) {
        if (!(stack.getItem() instanceof GltfWearable wearable) || slot != wearable.gltfSlot()) {
            return;
        }
        GltfModels.Entry entry = GltfModels.get(wearable.gltfModelId());
        float partial = Minecraft.getInstance().getFrameTime();
        float time = (entity.tickCount + partial) / 20.0F;
        pose.pushPose();
        if (slot == EquipmentSlot.HEAD) {
            model.head.translateAndRotate(pose);
        } else {
            model.body.translateAndRotate(pose);
        }
        var wear = entry.config().context("wear");
        pose.translate(wear.translation()[0], wear.translation()[1], wear.translation()[2]);
        pose.scale(1.0F, -1.0F, -1.0F); // model space is y-down; flip to upright
        String animation = null;
        if (slot == EquipmentSlot.CHEST) {
            animation = ghostAnimation(entry, entity);
            // gentle hover + lean into movement so the sheet feels alive
            pose.translate(0.0F, (float) Math.sin(time * 2.4F) * 0.04F, 0.0F);
            float speed = (float) entity.getDeltaMovement().horizontalDistance();
            pose.mulPose(Axis.XP.rotationDegrees(Math.min(18.0F, speed * 60.0F)));
        }
        pose.mulPose(Axis.ZP.rotationDegrees(wear.rotation()[2]));
        pose.mulPose(Axis.YP.rotationDegrees(wear.rotation()[1]));
        pose.mulPose(Axis.XP.rotationDegrees(wear.rotation()[0]));
        pose.scale(wear.scale(), wear.scale(), wear.scale());
        GltfRenderer.render(entry, animation, time, pose, buffers, light, OverlayTexture.NO_OVERLAY, slot == EquipmentSlot.CHEST ? 0.92F : 1.0F);
        pose.popPose();
    }

    /** Scared when a hostile mob is close, Wave during the 4-second "Huuuuu", Idle otherwise. */
    private static String ghostAnimation(GltfModels.Entry entry, LivingEntity entity) {
        var cfg = entry.config();
        boolean danger = !entity.level().getEntitiesOfClass(LivingEntity.class, entity.getBoundingBox().inflate(10.0D),
                e -> e instanceof Enemy && e.isAlive()).isEmpty();
        if (danger) {
            return cfg.animation("scared", "Scared");
        }
        if (entity.tickCount % 80 < 33) {
            return cfg.animation("wave", "Wave");
        }
        return cfg.animation("idle", "Idle");
    }
}
'''

FILES['src/main/java/com/heistmod/client/render/HeistHumanoidRenderer.java'] = r'''package com.heistmod.client.render;

import com.heistmod.HeistMod;
import com.mojang.blaze3d.vertex.PoseStack;
import net.minecraft.client.model.HumanoidArmorModel;
import net.minecraft.client.model.PlayerModel;
import net.minecraft.client.model.geom.ModelLayers;
import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.HumanoidMobRenderer;
import net.minecraft.client.renderer.entity.layers.HumanoidArmorLayer;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.Mob;

/**
 * Player-shaped NPC renderer (Agent Zero, the Black Market Dealer, Havaldar Thandulal). Skins are 64x64 player-layout
 * textures at {@code textures/entity/<name>.png}; the armour layer is what draws worn glTF items such as the police cap.
 */
public class HeistHumanoidRenderer<T extends Mob> extends HumanoidMobRenderer<T, PlayerModel<T>> {
    private final ResourceLocation texture;
    private final float scale;

    public HeistHumanoidRenderer(EntityRendererProvider.Context ctx, String name, float scale) {
        super(ctx, new PlayerModel<>(ctx.bakeLayer(ModelLayers.PLAYER), false), 0.5F * scale);
        this.texture = HeistMod.id("textures/entity/" + name + ".png");
        this.scale = scale;
        addLayer(new HumanoidArmorLayer<>(this, new HumanoidArmorModel<>(ctx.bakeLayer(ModelLayers.PLAYER_INNER_ARMOR)),
                new HumanoidArmorModel<>(ctx.bakeLayer(ModelLayers.PLAYER_OUTER_ARMOR)), ctx.getModelManager()));
    }

    @Override
    public ResourceLocation getTextureLocation(T entity) {
        return texture;
    }

    @Override
    protected void scale(T entity, PoseStack pose, float partialTick) {
        pose.scale(scale, scale, scale);
    }
}
'''

FILES['src/main/java/com/heistmod/client/render/LaserEmitterRenderer.java'] = r'''package com.heistmod.client.render;

import com.heistmod.block.LaserEmitterBlock;
import com.heistmod.blockentity.LaserEmitterBlockEntity;
import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.blaze3d.vertex.VertexConsumer;
import com.mojang.math.Axis;
import net.minecraft.client.renderer.MultiBufferSource;
import net.minecraft.client.renderer.RenderType;
import net.minecraft.client.renderer.blockentity.BlockEntityRenderer;
import net.minecraft.client.renderer.blockentity.BlockEntityRendererProvider;
import net.minecraft.core.Direction;
import org.joml.Matrix4f;

/** Draws the laser beam: a hot core plus a soft glow sleeve, pulsing orange while the alarm is raised. */
public class LaserEmitterRenderer implements BlockEntityRenderer<LaserEmitterBlockEntity> {
    public LaserEmitterRenderer(BlockEntityRendererProvider.Context ctx) {
    }

    @Override
    public void render(LaserEmitterBlockEntity be, float partial, PoseStack pose, MultiBufferSource buffers, int light, int overlay) {
        int length = be.getBeamLength();
        if (length <= 0 || be.getLevel() == null) {
            return;
        }
        Direction dir = be.getBlockState().getValue(LaserEmitterBlock.FACING);
        float t = be.getLevel().getGameTime() + partial;
        float pulse = 0.75F + 0.25F * (float) Math.sin(t * (be.isAlert() ? 1.2F : 0.25F));
        float r = 1.0F;
        float g = be.isAlert() ? 0.45F * pulse : 0.08F;
        float b = be.isAlert() ? 0.05F : 0.12F;
        pose.pushPose();
        pose.translate(0.5D, 0.5D, 0.5D);
        switch (dir) {
            case DOWN -> pose.mulPose(Axis.XP.rotationDegrees(180.0F));
            case NORTH -> pose.mulPose(Axis.XP.rotationDegrees(-90.0F));
            case SOUTH -> pose.mulPose(Axis.XP.rotationDegrees(90.0F));
            case WEST -> pose.mulPose(Axis.ZP.rotationDegrees(90.0F));
            case EAST -> pose.mulPose(Axis.ZP.rotationDegrees(-90.0F));
            default -> { }
        }
        VertexConsumer vc = buffers.getBuffer(RenderType.lightning());
        Matrix4f m = pose.last().pose();
        float len = length + 0.5F;
        box(vc, m, 0.025F, 0.3F, len, r, g, b, 0.95F * pulse);
        box(vc, m, 0.07F, 0.3F, len, r, g * 0.6F, b, 0.28F * pulse);
        pose.popPose();
    }

    /** Four side faces of a square tube along +Y from y0 to y1 (the beam is never seen end-on long enough to need caps). */
    private static void box(VertexConsumer vc, Matrix4f m, float w, float y0, float y1, float r, float g, float b, float a) {
        float[][] c = {{-w, -w}, {w, -w}, {w, w}, {-w, w}};
        for (int i = 0; i < 4; i++) {
            float[] p = c[i];
            float[] q = c[(i + 1) % 4];
            vc.vertex(m, p[0], y0, p[1]).color(r, g, b, a).endVertex();
            vc.vertex(m, q[0], y0, q[1]).color(r, g, b, a).endVertex();
            vc.vertex(m, q[0], y1, q[1]).color(r, g, b, a).endVertex();
            vc.vertex(m, p[0], y1, p[1]).color(r, g, b, a).endVertex();
        }
    }

    @Override
    public boolean shouldRenderOffScreen(LaserEmitterBlockEntity be) {
        return true;
    }

    @Override
    public int getViewDistance() {
        return 96;
    }
}
'''

