FILES['src/main/java/com/heistmod/effect/PoliceSirenEffect.java'] = r'''package com.heistmod.effect;

import com.heistmod.registry.ModSounds;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.effect.MobEffect;
import net.minecraft.world.effect.MobEffectCategory;
import net.minecraft.world.entity.LivingEntity;

/** A robbed mob blares a police siren from its own position every 4 seconds while this effect lasts. */
public class PoliceSirenEffect extends MobEffect {
    public PoliceSirenEffect() {
        super(MobEffectCategory.HARMFUL, 0x2F6BFF);
    }

    @Override
    public boolean isDurationEffectTick(int duration, int amplifier) {
        return duration % 80 == 0;
    }

    @Override
    public void applyEffectTick(LivingEntity entity, int amplifier) {
        if (!entity.level().isClientSide) {
            entity.level().playSound(null, entity.getX(), entity.getY(), entity.getZ(),
                    ModSounds.POLICE_SIREN.get(), SoundSource.HOSTILE, 4.0F, 1.0F);
        }
    }
}
'''

FILES['src/main/java/com/heistmod/entity/AgentZeroEntity.java'] = r'''package com.heistmod.entity;

import com.heistmod.dialogue.DialoguePage;
import com.heistmod.mission.HeistProgress;
import com.heistmod.mission.Mission;
import com.heistmod.mission.MissionManager;
import com.heistmod.registry.ModSounds;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.level.Level;

/**
 * Agent Zero - the handler. Interactive dialogue: briefs the active mission, hands out its gadget and gives hints.
 * Dialogue text lives in the language file under {@code dialogue.heistmod.agent_zero.*}.
 */
public class AgentZeroEntity extends HeistNpc {
    private static final String NAME = "npc.heistmod.agent_zero";

    public AgentZeroEntity(EntityType<? extends AgentZeroEntity> type, Level level) {
        super(type, level);
    }

    private static Component name() {
        return Component.translatable(NAME);
    }

    private static Component t(String key, Object... args) {
        return Component.translatable("dialogue.heistmod.agent_zero." + key, args);
    }

    private static Component opt(String key) {
        return Component.translatable("dialogue.heistmod.option." + key);
    }

    @Override
    public DialoguePage begin(ServerPlayer player) {
        HeistProgress progress = HeistProgress.of(player);
        Mission active = progress.active();
        Component text;
        if (progress.allComplete()) {
            text = t("greet.done");
        } else if (progress.completedMask() == 0 && progress.gadgetMask() == 0) {
            text = t("greet.new");
        } else if (active != null) {
            text = t("greet.active", Component.translatable(active.langKey("title")));
        } else {
            text = t("greet.idle");
        }
        return root(text);
    }

    private DialoguePage root(Component text) {
        DialoguePage page = new DialoguePage(name(), text).voice(ModSounds.AGENT_LINES.get(0).get());
        page.option(opt("briefing"), this::briefing);
        page.option(opt("gadget"), this::gadget);
        page.option(opt("hint"), this::hint);
        page.option(opt("board"), p -> new DialoguePage(name(), t("board")).option(opt("back"), q -> root(t("back"))));
        page.option(opt("bye"), p -> null);
        return page;
    }

    private DialoguePage briefing(ServerPlayer player) {
        Mission mission = HeistProgress.of(player).active();
        if (mission == null) {
            return root(t("no_mission"));
        }
        Component text = Component.translatable(mission.langKey("briefing"));
        DialoguePage page = new DialoguePage(name(), text).voice(ModSounds.AGENT_LINES.get(1).get());
        page.option(opt("gadget"), this::gadget);
        page.option(opt("back"), p -> root(t("back")));
        return page;
    }

    private DialoguePage hint(ServerPlayer player) {
        Mission mission = HeistProgress.of(player).active();
        if (mission == null) {
            return root(t("no_mission"));
        }
        DialoguePage page = new DialoguePage(name(), Component.translatable(mission.langKey("hint"))).voice(ModSounds.AGENT_LINES.get(3).get());
        page.option(opt("back"), p -> root(t("back")));
        return page;
    }

    private DialoguePage gadget(ServerPlayer player) {
        Mission mission = HeistProgress.of(player).active();
        if (mission == null) {
            return root(t("no_mission"));
        }
        boolean given = MissionManager.giveGadget(player, mission);
        Component gadgetName = mission.gadget().getDescription();
        DialoguePage page;
        if (given) {
            page = new DialoguePage(name(), t("gadget.given", gadgetName)).voice(ModSounds.AGENT_LINES.get(2).get());
        } else {
            page = new DialoguePage(name(), t("gadget.have", gadgetName));
        }
        page.option(opt("briefing"), this::briefing);
        page.option(opt("back"), p -> root(t("back")));
        return page;
    }
}
'''

FILES['src/main/java/com/heistmod/entity/BlackMarketDealerEntity.java'] = r'''package com.heistmod.entity;

import com.heistmod.dialogue.DialoguePage;
import com.heistmod.mission.MissionManager;
import com.heistmod.registry.ModSounds;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.level.Level;

/** The Black Market Dealer: buys stolen quest items and pays out Heist Diamonds and progression Tokens. */
public class BlackMarketDealerEntity extends HeistNpc {
    public BlackMarketDealerEntity(EntityType<? extends BlackMarketDealerEntity> type, Level level) {
        super(type, level);
    }

    private static Component name() {
        return Component.translatable("npc.heistmod.dealer");
    }

    private static Component t(String key, Object... args) {
        return Component.translatable("dialogue.heistmod.dealer." + key, args);
    }

    private static Component opt(String key) {
        return Component.translatable("dialogue.heistmod.option." + key);
    }

    @Override
    public DialoguePage begin(ServerPlayer player) {
        return root(t("greet"));
    }

    private DialoguePage root(Component text) {
        DialoguePage page = new DialoguePage(name(), text).voice(ModSounds.DEALER_LINES.get(0).get());
        page.option(opt("sell"), this::sell);
        page.option(opt("rates"), p -> new DialoguePage(name(), t("rates")).option(opt("back"), q -> root(t("back"))));
        page.option(opt("bye"), p -> null);
        return page;
    }

    private DialoguePage sell(ServerPlayer player) {
        MissionManager.SaleResult result = MissionManager.sellQuestItems(player);
        DialoguePage page;
        if (result.nothing()) {
            page = new DialoguePage(name(), t("nothing")).voice(ModSounds.DEALER_LINES.get(2).get());
        } else {
            page = new DialoguePage(name(), t("sold", result.itemsSold(), result.diamonds(), result.tokens())).voice(ModSounds.DEALER_LINES.get(1).get());
        }
        page.option(opt("sell"), this::sell);
        page.option(opt("back"), p -> root(t("back")));
        return page;
    }
}
'''

FILES['src/main/java/com/heistmod/entity/HavaldarDirector.java'] = r'''package com.heistmod.entity;

import com.heistmod.HeistConfig;
import com.heistmod.mission.KeyMoment;
import com.heistmod.registry.ModEntities;
import com.heistmod.registry.ModSounds;
import net.minecraft.core.BlockPos;
import net.minecraft.network.chat.Component;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.entity.MobSpawnType;
import net.minecraft.world.level.block.state.BlockState;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.UUID;

/** Decides when Havaldar Thandulal shows up: a short heads-up whistle, then he arrives a few seconds later. */
public final class HavaldarDirector {
    private record Pending(UUID player, long spawnAt, KeyMoment moment) {}

    private static final List<Pending> PENDING = new ArrayList<>();
    private static final Map<UUID, Long> NEXT_ALLOWED = new HashMap<>();

    private HavaldarDirector() {}

    public static void keyMoment(ServerPlayer player, KeyMoment moment) {
        if (!HeistConfig.HAVALDAR_ENABLED.get()) {
            return;
        }
        ServerLevel level = player.serverLevel();
        long now = level.getGameTime();
        if (NEXT_ALLOWED.getOrDefault(player.getUUID(), 0L) > now || alreadyHunting(level, player)) {
            return;
        }
        NEXT_ALLOWED.put(player.getUUID(), now + HeistConfig.HAVALDAR_COOLDOWN_TICKS.get());
        PENDING.add(new Pending(player.getUUID(), now + 100L + level.random.nextInt(80), moment));
        level.playSound(null, player.blockPosition(), ModSounds.HAVALDAR_WHISTLE.get(), SoundSource.NEUTRAL, 3.0F, 1.0F);
        player.displayClientMessage(Component.translatable("message.heistmod.havaldar.whistle"), true);
    }

    private static boolean alreadyHunting(ServerLevel level, ServerPlayer player) {
        for (HavaldarThandulalEntity cop : level.getEntitiesOfClass(HavaldarThandulalEntity.class, player.getBoundingBox().inflate(96.0D))) {
            if (cop.isAlive() && player == cop.wantedPlayer()) {
                return true;
            }
        }
        return false;
    }

    public static void tick(MinecraftServer server) {
        if (PENDING.isEmpty()) {
            return;
        }
        Iterator<Pending> it = PENDING.iterator();
        while (it.hasNext()) {
            Pending pending = it.next();
            ServerPlayer player = server.getPlayerList().getPlayer(pending.player());
            if (player == null) {
                it.remove();
                continue;
            }
            if (player.serverLevel().getGameTime() >= pending.spawnAt()) {
                it.remove();
                spawn(player);
            }
        }
    }

    public static void forget(UUID id) {
        PENDING.removeIf(p -> p.player().equals(id));
        NEXT_ALLOWED.remove(id);
    }

    /** Public so the /heist command can summon him on demand. */
    public static HavaldarThandulalEntity spawn(ServerPlayer player) {
        ServerLevel level = player.serverLevel();
        BlockPos pos = findSpawnPos(level, player);
        HavaldarThandulalEntity cop = ModEntities.HAVALDAR_THANDULAL.get().create(level);
        if (cop == null) {
            return null;
        }
        cop.moveTo(pos.getX() + 0.5, pos.getY(), pos.getZ() + 0.5, level.random.nextFloat() * 360.0F, 0.0F);
        cop.setWanted(player.getUUID());
        cop.finalizeSpawn(level, level.getCurrentDifficultyAt(pos), MobSpawnType.EVENT, null, null);
        level.addFreshEntity(cop);
        cop.setTarget(player);
        cop.announceArrival(level);
        return cop;
    }

    private static BlockPos findSpawnPos(ServerLevel level, ServerPlayer player) {
        BlockPos origin = player.blockPosition();
        for (int attempt = 0; attempt < 24; attempt++) {
            double angle = level.random.nextDouble() * Math.PI * 2.0D;
            double radius = 10.0D + level.random.nextDouble() * 10.0D;
            int x = origin.getX() + (int) Math.round(Math.cos(angle) * radius);
            int z = origin.getZ() + (int) Math.round(Math.sin(angle) * radius);
            for (int dy = 6; dy >= -8; dy--) {
                BlockPos feet = new BlockPos(x, origin.getY() + dy, z);
                BlockState below = level.getBlockState(feet.below());
                if (below.blocksMotion() && level.getBlockState(feet).getCollisionShape(level, feet).isEmpty()
                        && level.getBlockState(feet.above()).getCollisionShape(level, feet.above()).isEmpty()
                        && level.getFluidState(feet).isEmpty()) {
                    return feet;
                }
            }
        }
        return origin.offset(2, 0, 2);
    }
}
'''

FILES['src/main/java/com/heistmod/entity/HavaldarLines.java'] = r'''package com.heistmod.entity;

import com.heistmod.registry.ModSounds;
import net.minecraft.network.chat.Component;
import net.minecraft.sounds.SoundEvent;

/** Havaldar Thandulal's voice lines: sound event index + chat text (romanised Hindi, English in brackets). */
public final class HavaldarLines {
    public static final int COUNT = 8;

    private HavaldarLines() {}

    public static SoundEvent sound(int index) {
        return ModSounds.HAVALDAR_CHASE.get(Math.floorMod(index, COUNT)).get();
    }

    public static Component text(int index) {
        return Component.translatable("dialogue.heistmod.havaldar.chase_" + (Math.floorMod(index, COUNT) + 1));
    }
}
'''

FILES['src/main/java/com/heistmod/entity/HavaldarThandulalEntity.java'] = r'''package com.heistmod.entity;

import com.heistmod.HeistConfig;
import com.heistmod.registry.ModItems;
import com.heistmod.registry.ModSounds;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.sounds.SoundSource;
import net.minecraft.util.RandomSource;
import net.minecraft.world.DifficultyInstance;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.effect.MobEffects;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.MobSpawnType;
import net.minecraft.world.entity.PathfinderMob;
import net.minecraft.world.entity.SpawnGroupData;
import net.minecraft.world.entity.ai.attributes.AttributeSupplier;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.ai.goal.FloatGoal;
import net.minecraft.world.entity.ai.goal.LookAtPlayerGoal;
import net.minecraft.world.entity.ai.goal.MeleeAttackGoal;
import net.minecraft.world.entity.ai.goal.MoveTowardsTargetGoal;
import net.minecraft.world.entity.ai.goal.WaterAvoidingRandomStrollGoal;
import net.minecraft.world.entity.ai.goal.target.HurtByTargetGoal;
import net.minecraft.world.entity.ai.goal.target.TargetGoal;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.ServerLevelAccessor;
import net.minecraft.nbt.CompoundTag;

import org.jetbrains.annotations.Nullable;
import java.util.UUID;

/**
 * Havaldar Thandulal - the comedic rival cop. Spawns at key mission moments (see {@link HavaldarDirector}), blows
 * his whistle, charges at the thief with a wooden lathi (fast, high knockback) shouting Hindi chase lines, and finally
 * gives up for a cup of chai.
 */
public class HavaldarThandulalEntity extends PathfinderMob {
    @Nullable
    private UUID wanted;
    private int lifeTicks = HeistConfig.HAVALDAR_LIFETIME_TICKS.get();
    private int shoutCooldown = 60;
    private int lostTicks;
    private int lastLine = -1;

    public HavaldarThandulalEntity(EntityType<? extends HavaldarThandulalEntity> type, Level level) {
        super(type, level);
        setPersistenceRequired();
        this.xpReward = 25;
    }

    public static AttributeSupplier.Builder createAttributes() {
        return PathfinderMob.createMobAttributes()
                .add(Attributes.MAX_HEALTH, 60.0D)
                .add(Attributes.MOVEMENT_SPEED, 0.37D)
                .add(Attributes.ATTACK_DAMAGE, 4.0D)
                .add(Attributes.ATTACK_KNOCKBACK, 2.2D)
                .add(Attributes.KNOCKBACK_RESISTANCE, 0.35D)
                .add(Attributes.FOLLOW_RANGE, 56.0D);
    }

    // ------------------------------------------------------------------ AI
    @Override
    protected void registerGoals() {
        goalSelector.addGoal(0, new FloatGoal(this));
        goalSelector.addGoal(2, new MeleeAttackGoal(this, 1.25D, false));
        goalSelector.addGoal(3, new MoveTowardsTargetGoal(this, 1.15D, 48.0F));
        goalSelector.addGoal(6, new WaterAvoidingRandomStrollGoal(this, 0.9D));
        goalSelector.addGoal(7, new LookAtPlayerGoal(this, Player.class, 10.0F));
        targetSelector.addGoal(1, new HurtByTargetGoal(this));
        targetSelector.addGoal(2, new WantedPlayerGoal(this));
    }

    /** Targets the player he was sent after, wherever they are within his follow range. */
    private static final class WantedPlayerGoal extends TargetGoal {
        private final HavaldarThandulalEntity cop;

        WantedPlayerGoal(HavaldarThandulalEntity cop) {
            super(cop, false);
            this.cop = cop;
        }

        @Override
        public boolean canUse() {
            Player p = cop.wantedPlayer();
            return p != null && p.isAlive() && !p.isSpectator() && cop.distanceToSqr(p) < 60.0D * 60.0D;
        }

        @Override
        public void start() {
            cop.setTarget(cop.wantedPlayer());
            super.start();
        }
    }

    @Nullable
    Player wantedPlayer() {
        return wanted == null ? null : level().getPlayerByUUID(wanted);
    }

    public void setWanted(@Nullable UUID playerId) {
        this.wanted = playerId;
    }

    @Nullable
    @Override
    public SpawnGroupData finalizeSpawn(ServerLevelAccessor level, DifficultyInstance difficulty, MobSpawnType reason,
                                        @Nullable SpawnGroupData spawnData, @Nullable CompoundTag dataTag) {
        SpawnGroupData data = super.finalizeSpawn(level, difficulty, reason, spawnData, dataTag);
        populateDefaultEquipmentSlots(level.getRandom(), difficulty);
        return data;
    }

    @Override
    protected void populateDefaultEquipmentSlots(RandomSource random, DifficultyInstance difficulty) {
        setItemSlot(EquipmentSlot.MAINHAND, new ItemStack(ModItems.HAVALDAR_LATHI.get()));
        setItemSlot(EquipmentSlot.HEAD, new ItemStack(ModItems.HAVALDAR_CAP.get()));
        setDropChance(EquipmentSlot.MAINHAND, 0.0F);
        setDropChance(EquipmentSlot.HEAD, 0.0F);
    }

    // ------------------------------------------------------------------ behaviour
    @Override
    protected void customServerAiStep() {
        super.customServerAiStep();
        if (!(level() instanceof ServerLevel serverLevel)) {
            return;
        }
        if (--lifeTicks <= 0) {
            retreat(serverLevel);
            return;
        }
        Player target = wantedPlayer();
        if (target == null || !target.isAlive()) {
            if (++lostTicks > 200) {
                retreat(serverLevel);
                return;
            }
        } else {
            lostTicks = 0;
        }
        if (getTarget() != null && --shoutCooldown <= 0) {
            shout(serverLevel);
            shoutCooldown = 90 + random.nextInt(70);
        }
    }

    public void announceArrival(ServerLevel level) {
        level.playSound(null, getX(), getY(), getZ(), ModSounds.HAVALDAR_ARRIVE.get(), SoundSource.HOSTILE, 4.0F, 1.0F);
        level.sendParticles(ParticleTypes.POOF, getX(), getY() + 1.0, getZ(), 18, 0.4, 0.8, 0.4, 0.02);
        broadcast(level, Component.translatable("dialogue.heistmod.havaldar.arrive"));
    }

    private void shout(ServerLevel level) {
        int index = random.nextInt(HavaldarLines.COUNT);
        if (index == lastLine) {
            index = (index + 1) % HavaldarLines.COUNT;
        }
        lastLine = index;
        SoundEvent sound = HavaldarLines.sound(index);
        level.playSound(null, getX(), getY(), getZ(), sound, SoundSource.HOSTILE, 3.5F, 0.95F + random.nextFloat() * 0.1F);
        broadcast(level, HavaldarLines.text(index));
    }

    private void broadcast(ServerLevel level, Component line) {
        Component msg = Component.translatable("chat.heistmod.havaldar", line);
        for (ServerPlayer p : level.players()) {
            if (p.distanceToSqr(this) < 56.0D * 56.0D) {
                p.sendSystemMessage(msg);
            }
        }
    }

    private void retreat(ServerLevel level) {
        level.playSound(null, getX(), getY(), getZ(), ModSounds.HAVALDAR_RETREAT.get(), SoundSource.HOSTILE, 3.0F, 1.0F);
        broadcast(level, Component.translatable("dialogue.heistmod.havaldar.retreat"));
        level.sendParticles(ParticleTypes.CLOUD, getX(), getY() + 1.0, getZ(), 30, 0.5, 0.9, 0.5, 0.05);
        discard();
    }

    @Override
    public boolean doHurtTarget(Entity target) {
        boolean hit = super.doHurtTarget(target);
        if (hit) {
            level().playSound(null, getX(), getY(), getZ(), ModSounds.HAVALDAR_ATTACK.get(), SoundSource.HOSTILE, 1.5F, 1.0F);
            if (target instanceof LivingEntity living) {
                living.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, 30, 1));
            }
        }
        return hit;
    }

    @Override
    public boolean removeWhenFarAway(double distance) {
        return false;
    }

    @Override
    protected SoundEvent getHurtSound(DamageSource source) {
        return ModSounds.HAVALDAR_HURT.get();
    }

    @Override
    protected SoundEvent getDeathSound() {
        return ModSounds.HAVALDAR_DEATH.get();
    }

    // ------------------------------------------------------------------ persistence
    @Override
    public void addAdditionalSaveData(CompoundTag tag) {
        super.addAdditionalSaveData(tag);
        if (wanted != null) {
            tag.putUUID("Wanted", wanted);
        }
        tag.putInt("Life", lifeTicks);
    }

    @Override
    public void readAdditionalSaveData(CompoundTag tag) {
        super.readAdditionalSaveData(tag);
        wanted = tag.hasUUID("Wanted") ? tag.getUUID("Wanted") : null;
        if (tag.contains("Life")) {
            lifeTicks = tag.getInt("Life");
        }
    }
}
'''

FILES['src/main/java/com/heistmod/entity/HeistNpc.java'] = r'''package com.heistmod.entity;

import com.heistmod.dialogue.DialogueManager;
import com.heistmod.dialogue.IDialogueNpc;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.PathfinderMob;
import net.minecraft.world.entity.ai.attributes.AttributeSupplier;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.ai.goal.FloatGoal;
import net.minecraft.world.entity.ai.goal.LookAtPlayerGoal;
import net.minecraft.world.entity.ai.goal.RandomLookAroundGoal;
import net.minecraft.world.entity.ai.goal.WaterAvoidingRandomStrollGoal;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;

import org.jetbrains.annotations.Nullable;
import java.util.UUID;

/** Shared base for the friendly bunker NPCs: invulnerable, persistent, stops to talk and shows the dialogue screen. */
public abstract class HeistNpc extends PathfinderMob implements IDialogueNpc {
    @Nullable
    private UUID talkingTo;
    private int talkTicks;

    protected HeistNpc(EntityType<? extends PathfinderMob> type, Level level) {
        super(type, level);
        setPersistenceRequired();
        setInvulnerable(true);
    }

    public static AttributeSupplier.Builder createNpcAttributes() {
        return PathfinderMob.createMobAttributes()
                .add(Attributes.MAX_HEALTH, 40.0D)
                .add(Attributes.MOVEMENT_SPEED, 0.25D)
                .add(Attributes.FOLLOW_RANGE, 16.0D);
    }

    @Override
    protected void registerGoals() {
        goalSelector.addGoal(0, new FloatGoal(this));
        goalSelector.addGoal(5, new WaterAvoidingRandomStrollGoal(this, 0.3D, 0.003F));
        goalSelector.addGoal(6, new LookAtPlayerGoal(this, Player.class, 8.0F));
        goalSelector.addGoal(7, new RandomLookAroundGoal(this));
    }

    @Override
    public boolean removeWhenFarAway(double distance) {
        return false;
    }

    @Override
    public boolean canBeLeashed(Player player) {
        return false;
    }

    @Override
    public void aiStep() {
        super.aiStep();
        if (talkTicks > 0) {
            talkTicks--;
            getNavigation().stop();
            if (talkingTo != null) {
                Player p = level().getPlayerByUUID(talkingTo);
                if (p != null) {
                    getLookControl().setLookAt(p, 30.0F, 30.0F);
                }
            }
        }
    }

    @Override
    protected InteractionResult mobInteract(Player player, InteractionHand hand) {
        if (!level().isClientSide && player instanceof ServerPlayer serverPlayer) {
            talkingTo = serverPlayer.getUUID();
            talkTicks = 200;
            DialogueManager.open(serverPlayer, this);
        }
        return InteractionResult.sidedSuccess(level().isClientSide);
    }

    /** Set by NPCs that must not be robbed with the Jeb Katra Gloves. */
    public boolean isPickpocketProof() {
        return true;
    }
}
'''

FILES['src/main/java/com/heistmod/entity/PiglinKingEntity.java'] = r'''package com.heistmod.entity;

import com.heistmod.registry.ModItems;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.DifficultyInstance;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.MobSpawnType;
import net.minecraft.world.entity.SpawnGroupData;
import net.minecraft.world.entity.ai.attributes.AttributeSupplier;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.monster.piglin.PiglinBrute;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.ServerLevelAccessor;

import org.jetbrains.annotations.Nullable;

/**
 * The Piglin King: a bigger, gold-armoured Piglin Brute who carries the Golden Tooth (Tier 2 target).
 * He never zombifies, never despawns, and can be robbed by {@link com.heistmod.item.JebKatraGlovesItem}.
 */
public class PiglinKingEntity extends PiglinBrute implements QuestCarrier {
    private boolean hasTooth = true;

    public PiglinKingEntity(EntityType<? extends PiglinBrute> type, Level level) {
        super(type, level);
        setImmuneToZombification(true);
        setPersistenceRequired();
        this.xpReward = 60;
    }

    public static AttributeSupplier.Builder createKingAttributes() {
        return PiglinBrute.createAttributes()
                .add(Attributes.MAX_HEALTH, 100.0D)
                .add(Attributes.ATTACK_DAMAGE, 9.0D)
                .add(Attributes.ARMOR, 6.0D)
                .add(Attributes.KNOCKBACK_RESISTANCE, 0.7D)
                .add(Attributes.MOVEMENT_SPEED, 0.33D);
    }

    @Nullable
    @Override
    public SpawnGroupData finalizeSpawn(ServerLevelAccessor level, DifficultyInstance difficulty, MobSpawnType reason,
                                        @Nullable SpawnGroupData spawnData, @Nullable CompoundTag dataTag) {
        SpawnGroupData data = super.finalizeSpawn(level, difficulty, reason, spawnData, dataTag);
        setItemSlot(EquipmentSlot.HEAD, new ItemStack(Items.GOLDEN_HELMET));
        setItemSlot(EquipmentSlot.CHEST, new ItemStack(Items.GOLDEN_CHESTPLATE));
        setItemSlot(EquipmentSlot.LEGS, new ItemStack(Items.GOLDEN_LEGGINGS));
        setItemSlot(EquipmentSlot.FEET, new ItemStack(Items.GOLDEN_BOOTS));
        setItemSlot(EquipmentSlot.MAINHAND, new ItemStack(Items.GOLDEN_AXE));
        return data;
    }

    @Override
    protected boolean shouldDespawnInPeaceful() {
        return false;
    }

    // ------------------------------------------------------------------ quest loot
    @Override
    public boolean hasQuestItem() {
        return hasTooth;
    }

    @Override
    public ItemStack takeQuestItem() {
        if (!hasTooth) {
            return ItemStack.EMPTY;
        }
        hasTooth = false;
        return new ItemStack(ModItems.PIGLIN_KINGS_GOLDEN_TOOTH.get());
    }

    @Override
    public void addAdditionalSaveData(CompoundTag tag) {
        super.addAdditionalSaveData(tag);
        tag.putBoolean("HasTooth", hasTooth);
    }

    @Override
    public void readAdditionalSaveData(CompoundTag tag) {
        super.readAdditionalSaveData(tag);
        hasTooth = !tag.contains("HasTooth") || tag.getBoolean("HasTooth");
    }

    /** If the King is killed with the tooth still in his mouth, it drops for the taking. */
    @Override
    protected void dropCustomDeathLoot(net.minecraft.world.damagesource.DamageSource source, int looting, boolean recentlyHit) {
        super.dropCustomDeathLoot(source, looting, recentlyHit);
        if (hasTooth) {
            spawnAtLocation(takeQuestItem());
        }
    }
}
'''

FILES['src/main/java/com/heistmod/entity/QuestCarrier.java'] = r'''package com.heistmod.entity;

import net.minecraft.world.item.ItemStack;

/** An entity that holds a quest item which the Jeb Katra Gloves can lift (e.g. the Piglin King's golden tooth). */
public interface QuestCarrier {
    boolean hasQuestItem();

    /** Removes and returns the quest item (EMPTY if it was already taken). */
    ItemStack takeQuestItem();
}
'''

FILES['src/main/java/com/heistmod/event/GadgetEvents.java'] = r'''package com.heistmod.event;

import com.heistmod.HeistConfig;
import com.heistmod.entity.HavaldarDirector;
import com.heistmod.gadget.GloveHeist;
import com.heistmod.mission.KeyMoment;
import com.heistmod.registry.ModItems;
import com.heistmod.registry.ModSounds;
import net.minecraft.core.particles.DustParticleOptions;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.network.chat.Component;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.effect.MobEffects;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.Mob;
import net.minecraft.world.entity.ai.memory.MemoryModuleType;
import net.minecraft.world.entity.monster.warden.Warden;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import org.joml.Vector3f;

/** Event hooks for the gadgets that are not plain item use: gloves, the ghost sheet's stealth + shatter. */
public final class GadgetEvents {
    private GadgetEvents() {}

    public static boolean wearsSheet(LivingEntity entity) {
        return entity instanceof Player player && player.getItemBySlot(EquipmentSlot.CHEST).is(ModItems.BHOOTIYA_CHADDAR.get());
    }

    // ------------------------------------------------------------------ Tier 2 : Jeb Katra Gloves
    /** Fabric {@code UseEntityCallback}: Sneak + Right-Click a mob with the gloves. */
    public static InteractionResult onUseEntity(Player player, Level level, InteractionHand hand, Entity entity) {
        if (player.isSpectator() || !player.isShiftKeyDown() || !(entity instanceof LivingEntity target) || target instanceof Player) {
            return InteractionResult.PASS;
        }
        ItemStack held = player.getItemInHand(hand);
        if (!held.is(ModItems.JEB_KATRA_GLOVES.get())) {
            return InteractionResult.PASS;
        }
        if (!level.isClientSide && player instanceof ServerPlayer serverPlayer && !player.getCooldowns().isOnCooldown(held.getItem())) {
            GloveHeist.perform(serverPlayer, target, held, hand);
        }
        return InteractionResult.SUCCESS;
    }

    // ------------------------------------------------------------------ Tier 3 : Bhootiya Chaddar - stealth
    // Target acquisition and visibility are handled by MobMixin / LivingEntityMixin (Fabric has no events for them).

    /** Safety net: mobs that already had the player locked on (or use brains / anger tables) forget them. */
    public static void tick(MinecraftServer server) {
        for (ServerPlayer player : server.getPlayerList().getPlayers()) {
            if (player.tickCount % 10 != 0 || !wearsSheet(player)) {
                continue;
            }
            for (Mob mob : player.serverLevel().getEntitiesOfClass(Mob.class, player.getBoundingBox().inflate(64.0D))) {
                if (mob.getTarget() == player) {
                    mob.setTarget(null);
                }
                if (mob.getBrain().hasMemoryValue(MemoryModuleType.ATTACK_TARGET)
                        && mob.getBrain().getMemory(MemoryModuleType.ATTACK_TARGET).orElse(null) == player) {
                    mob.getBrain().eraseMemory(MemoryModuleType.ATTACK_TARGET);
                }
                if (mob instanceof Warden warden) {
                    warden.clearAnger(player);
                }
            }
        }
    }

    // ------------------------------------------------------------------ Tier 3 : shatter on half a heart of damage
    /** Fabric {@code ServerLivingEntityEvents.ALLOW_DAMAGE}; always lets the damage through. */
    public static boolean onDamage(LivingEntity entity, DamageSource source, float amount) {
        if (entity instanceof ServerPlayer player && wearsSheet(player) && amount >= HeistConfig.CHADDAR_SHATTER_DAMAGE.get().floatValue()) {
            shatter(player);
        }
        return true;
    }

    public static void shatter(ServerPlayer player) {
        ServerLevel level = player.serverLevel();
        player.setItemSlot(EquipmentSlot.CHEST, ItemStack.EMPTY);
        clearSheetEffects(player);
        double x = player.getX();
        double y = player.getY() + 1.0D;
        double z = player.getZ();
        level.playSound(null, x, y, z, ModSounds.CHADDAR_SHATTER.get(), SoundSource.PLAYERS, 2.0F, 1.0F);
        level.sendParticles(new DustParticleOptions(new Vector3f(1.0F, 1.0F, 1.0F), 2.0F), x, y, z, 90, 0.5, 0.8, 0.5, 0.15);
        level.sendParticles(ParticleTypes.CLOUD, x, y, z, 50, 0.5, 0.8, 0.5, 0.08);
        level.sendParticles(ParticleTypes.POOF, x, y, z, 30, 0.5, 0.8, 0.5, 0.1);
        level.sendParticles(ParticleTypes.SOUL, x, y, z, 20, 0.4, 0.8, 0.4, 0.05);
        player.displayClientMessage(Component.translatable("message.heistmod.chaddar.shattered"), false);
        HavaldarDirector.keyMoment(player, KeyMoment.SHEET_SHATTERED);
    }

    private static void clearSheetEffects(LivingEntity entity) {
        removeShort(entity, MobEffects.INVISIBILITY);
        removeShort(entity, MobEffects.MOVEMENT_SLOWDOWN);
    }

    private static void removeShort(LivingEntity entity, net.minecraft.world.effect.MobEffect effect) {
        MobEffectInstance instance = entity.getEffect(effect);
        if (instance != null && instance.getDuration() <= 45) {
            entity.removeEffect(effect);
        }
    }

    /** Fabric {@code ServerEntityEvents.EQUIPMENT_CHANGE}: taking the sheet off ends its effects at once. */
    public static void onEquipmentChange(LivingEntity entity, EquipmentSlot slot, ItemStack from, ItemStack to) {
        if (slot == EquipmentSlot.CHEST && from.is(ModItems.BHOOTIYA_CHADDAR.get()) && !to.is(ModItems.BHOOTIYA_CHADDAR.get())) {
            clearSheetEffects(entity);
        }
    }
}
'''

FILES['src/main/java/com/heistmod/event/HeistEvents.java'] = r'''package com.heistmod.event;

import com.heistmod.command.HeistCommand;
import com.heistmod.entity.HavaldarDirector;
import com.heistmod.gadget.GloveHeist;
import com.heistmod.gadget.ReelManager;
import com.heistmod.gadget.RocketFlights;
import com.heistmod.siphon.ChaosSiphonManager;
import com.heistmod.world.AlarmManager;
import com.heistmod.world.SchematicPlacer;
import net.fabricmc.fabric.api.command.v2.CommandRegistrationCallback;
import net.fabricmc.fabric.api.entity.event.v1.ServerEntityWorldChangeEvents;
import net.fabricmc.fabric.api.entity.event.v1.ServerLivingEntityEvents;
import net.fabricmc.fabric.api.entity.event.v1.ServerPlayerEvents;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerEntityEvents;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
import net.fabricmc.fabric.api.event.player.UseEntityCallback;
import net.fabricmc.fabric.api.networking.v1.EntityTrackingEvents;
import net.fabricmc.fabric.api.networking.v1.ServerPlayConnectionEvents;

/** Single place where the mod hooks into Fabric API events. Each handler lives next to the feature it serves. */
public final class HeistEvents {
    private HeistEvents() {}

    public static void register() {
        // --- one server tick drives every time-sliced system (reels, flights, hunts, siphon batches, city builds, alarms)
        ServerTickEvents.END_SERVER_TICK.register(server -> {
            ReelManager.tick(server);
            RocketFlights.tick(server);
            GloveHeist.tick(server);
            GadgetEvents.tick(server);
            HavaldarDirector.tick(server);
            AlarmManager.tick(server);
            SchematicPlacer.tick(server);
            ChaosSiphonManager.tick(server);
        });

        // --- gadgets
        UseEntityCallback.EVENT.register((player, level, hand, entity, hitResult) -> GadgetEvents.onUseEntity(player, level, hand, entity));
        ServerLivingEntityEvents.ALLOW_DAMAGE.register(GadgetEvents::onDamage);
        ServerEntityEvents.EQUIPMENT_CHANGE.register(GadgetEvents::onEquipmentChange);

        // --- player state sync
        ServerPlayConnectionEvents.JOIN.register((handler, sender, server) -> PlayerDataEvents.sendAll(handler.player));
        ServerPlayConnectionEvents.DISCONNECT.register((handler, server) -> PlayerDataEvents.onLogout(handler.player));
        ServerPlayerEvents.AFTER_RESPAWN.register((oldPlayer, newPlayer, alive) -> PlayerDataEvents.sendAll(newPlayer));
        ServerEntityWorldChangeEvents.AFTER_PLAYER_CHANGE_WORLD.register((player, origin, destination) -> PlayerDataEvents.sendAll(player));
        EntityTrackingEvents.START_TRACKING.register(PlayerDataEvents::onStartTracking);
        ServerLifecycleEvents.SERVER_STOPPED.register(server -> PlayerDataEvents.onServerStopped());

        // --- /heist
        CommandRegistrationCallback.EVENT.register((dispatcher, registryAccess, environment) -> HeistCommand.register(dispatcher));
    }
}
'''

FILES['src/main/java/com/heistmod/event/PlayerDataEvents.java'] = r'''package com.heistmod.event;

import com.heistmod.dialogue.DialogueManager;
import com.heistmod.entity.HavaldarDirector;
import com.heistmod.gadget.GloveHeist;
import com.heistmod.gadget.ReelManager;
import com.heistmod.gadget.RocketFlights;
import com.heistmod.mission.HeistProgress;
import com.heistmod.mission.MissionManager;
import com.heistmod.network.ChaosSyncPacket;
import com.heistmod.network.HeistNetwork;
import com.heistmod.network.StripSyncPacket;
import com.heistmod.siphon.ChaosSiphonManager;
import com.heistmod.world.AlarmManager;
import com.heistmod.world.SchematicPlacer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.Entity;

/** Keeps every client in sync with the campaign state and cleans static state between worlds. */
public final class PlayerDataEvents {
    private PlayerDataEvents() {}

    /** Login, respawn and dimension change. */
    public static void sendAll(ServerPlayer player) {
        MissionManager.sync(player);
        HeistNetwork.sendTo(player, new ChaosSyncPacket(HeistProgress.of(player).chaos(), false));
    }

    public static void onLogout(ServerPlayer player) {
        DialogueManager.forget(player);
        HavaldarDirector.forget(player.getUUID());
    }

    public static void onStartTracking(Entity tracked, ServerPlayer player) {
        if (tracked.getTags().contains(GloveHeist.STRIPPED_TAG)) {
            HeistNetwork.sendTo(player, new StripSyncPacket(tracked.getId(), true));
        }
    }

    public static void onServerStopped() {
        ReelManager.clear();
        RocketFlights.clear();
        GloveHeist.clear();
        ChaosSiphonManager.clear();
        AlarmManager.clear();
        SchematicPlacer.clear();
    }
}
'''

FILES['src/main/java/com/heistmod/gadget/ChingamGadget.java'] = r'''package com.heistmod.gadget;

import com.heistmod.HeistConfig;
import com.heistmod.network.HeistNetwork;
import com.heistmod.network.SplatPacket;
import com.heistmod.registry.ModSounds;
import net.minecraft.core.particles.DustParticleOptions;
import net.minecraft.core.particles.ParticleOptions;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.effect.MobEffects;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.phys.Vec3;
import org.joml.Vector3f;

/** Server logic of the Chingam Grappler shot: 30% misfire (bubblegum splat) or a 35 block quest-item reel. */
public final class ChingamGadget {
    private static final ParticleOptions CYAN = new DustParticleOptions(new Vector3f(0.25F, 0.95F, 1.0F), 1.1F);
    private static final ParticleOptions PINK = new DustParticleOptions(new Vector3f(1.0F, 0.42F, 0.74F), 1.6F);

    private ChingamGadget() {}

    public static Vec3 muzzle(ServerPlayer player) {
        Vec3 look = player.getViewVector(1.0F);
        Vec3 right = look.cross(new Vec3(0.0D, 1.0D, 0.0D)).normalize();
        return player.getEyePosition().add(look.scale(0.95D)).add(right.scale(0.24D)).add(0.0D, -0.22D, 0.0D);
    }

    public static void fire(ServerPlayer player) {
        ServerLevel level = player.serverLevel();
        level.playSound(null, player.getX(), player.getY(), player.getZ(), ModSounds.CHINGAM_FIRE.get(), SoundSource.PLAYERS, 1.1F, 1.0F);
        Vec3 muzzle = muzzle(player);

        if (level.random.nextDouble() < HeistConfig.GRAPPLER_MISFIRE_CHANCE.get()) {
            misfire(player, level, muzzle);
            return;
        }

        double range = HeistConfig.GRAPPLER_RANGE.get();
        QuestRaycast.Hit hit = QuestRaycast.find(level, player, range);
        if (hit == null) {
            beam(level, muzzle, QuestRaycast.rayEnd(player, range), 0.9D);
            player.displayClientMessage(Component.translatable("message.heistmod.grappler.nothing", (int) range), true);
            return;
        }
        beam(level, muzzle, hit.position(), 0.45D);
        ItemStack stack = hit.take();
        if (stack.isEmpty()) {
            return;
        }
        level.playSound(null, hit.position().x, hit.position().y, hit.position().z, ModSounds.CHINGAM_REEL.get(), SoundSource.PLAYERS, 1.6F, 1.0F);
        ReelManager.start(level, player, stack, hit.position());
        player.displayClientMessage(Component.translatable("message.heistmod.grappler.reel", stack.getHoverName()), true);
    }

    /** The gum recoils: pink splat, Blindness + Slowness I and a very loud, very sticky squish for 2.5 seconds. */
    public static void misfire(ServerPlayer player, ServerLevel level, Vec3 muzzle) {
        int duration = HeistConfig.SPLAT_DURATION_TICKS.get();
        level.playSound(null, player.getX(), player.getY(), player.getZ(), ModSounds.CHINGAM_SQUISH.get(), SoundSource.PLAYERS, 4.0F, 0.95F + level.random.nextFloat() * 0.1F);
        player.addEffect(new MobEffectInstance(MobEffects.BLINDNESS, duration, 0, false, false, true));
        player.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, duration, 0, false, false, true));
        HeistNetwork.sendTo(player, new SplatPacket(duration, level.random.nextInt()));
        Vec3 face = player.getEyePosition().add(player.getViewVector(1.0F).scale(0.6D));
        level.sendParticles(PINK, face.x, face.y, face.z, 40, 0.35, 0.3, 0.35, 0.02);
        level.sendParticles(ParticleTypes.ITEM_SLIME, face.x, face.y, face.z, 24, 0.35, 0.3, 0.35, 0.05);
        level.sendParticles(PINK, muzzle.x, muzzle.y, muzzle.z, 20, 0.15, 0.15, 0.15, 0.08);
        player.displayClientMessage(Component.translatable("message.heistmod.grappler.misfire"), true);
    }

    /** Cyan energy tether drawn with dust particles (capped so a 35 block shot never floods the network). */
    public static void beam(ServerLevel level, Vec3 from, Vec3 to, double spacing) {
        Vec3 delta = to.subtract(from);
        double length = delta.length();
        if (length < 0.2D) {
            return;
        }
        int steps = (int) Math.min(80, Math.max(2, length / spacing));
        Vec3 step = delta.scale(1.0D / steps);
        for (int i = 0; i <= steps; i++) {
            Vec3 p = from.add(step.scale(i));
            level.sendParticles(CYAN, p.x, p.y, p.z, 1, 0.0, 0.0, 0.0, 0.0);
        }
        level.sendParticles(ParticleTypes.END_ROD, from.x, from.y, from.z, 4, 0.05, 0.05, 0.05, 0.02);
    }
}
'''

FILES['src/main/java/com/heistmod/gadget/GloveHeist.java'] = r'''package com.heistmod.gadget;

import com.heistmod.HeistConfig;
import com.heistmod.entity.HavaldarDirector;
import com.heistmod.entity.HeistNpc;
import com.heistmod.entity.QuestCarrier;
import com.heistmod.mission.KeyMoment;
import com.heistmod.mission.MissionManager;
import com.heistmod.network.AlarmFlashPacket;
import com.heistmod.network.HeistNetwork;
import com.heistmod.network.StripSyncPacket;
import com.heistmod.registry.ModEffects;
import com.heistmod.registry.ModSounds;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.network.chat.Component;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.effect.MobEffects;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.Mob;
import net.minecraft.world.entity.ai.memory.MemoryModuleType;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.phys.Vec3;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.WeakHashMap;

/**
 * Tier 2 logic: Sneak + Right-Click behind any mob or NPC. Strips their armour, steals the target item, blares a police
 * siren, grants Speed II + Strength I and sends them hunting the thief.
 */
public final class GloveHeist {
    public static final String STRIPPED_TAG = "heist_stripped";
    private static final EquipmentSlot[] ARMOR = {EquipmentSlot.HEAD, EquipmentSlot.CHEST, EquipmentSlot.LEGS, EquipmentSlot.FEET};

    private record Hunt(Mob mob, UUID player, long until) {}

    private static final List<Hunt> HUNTS = new ArrayList<>();
    private static final Map<LivingEntity, Long> ROBBED_AT = new WeakHashMap<>();

    private GloveHeist() {}

    /** True if {@code thief} stands behind {@code target} (within ~110 degrees of the opposite of its body facing). */
    public static boolean isBehind(Player thief, LivingEntity target) {
        Vec3 facing = Vec3.directionFromRotation(0.0F, target.yBodyRot).multiply(1.0D, 0.0D, 1.0D);
        Vec3 toThief = thief.position().subtract(target.position()).multiply(1.0D, 0.0D, 1.0D);
        if (toThief.lengthSqr() < 1.0E-4D || facing.lengthSqr() < 1.0E-4D) {
            return true;
        }
        return facing.normalize().dot(toThief.normalize()) < -0.30D;
    }

    public static void perform(ServerPlayer thief, LivingEntity target, ItemStack gloves, InteractionHand hand) {
        if (target instanceof HeistNpc npc && npc.isPickpocketProof()) {
            thief.displayClientMessage(Component.translatable("message.heistmod.gloves.nice_try"), true);
            return;
        }
        Long robbedAt = ROBBED_AT.get(target);
        if (robbedAt != null && thief.level().getGameTime() < robbedAt + 600L) {
            thief.displayClientMessage(Component.translatable("message.heistmod.gloves.already"), true);
            return;
        }
        if (!isBehind(thief, target)) {
            thief.displayClientMessage(Component.translatable("message.heistmod.gloves.not_behind"), true);
            return;
        }

        ServerLevel level = thief.serverLevel();
        boolean stoleQuest = false;

        // 1) the target item
        if (target instanceof QuestCarrier carrier && carrier.hasQuestItem()) {
            ItemStack loot = carrier.takeQuestItem();
            if (!loot.isEmpty()) {
                MissionManager.giveOrDrop(thief, loot.copy());
                MissionManager.onQuestItemObtained(thief, loot);
                stoleQuest = true;
            }
        } else {
            float r = level.random.nextFloat();
            ItemStack loot = r < 0.45F ? new ItemStack(Items.GOLD_NUGGET, 1 + level.random.nextInt(4))
                    : r < 0.75F ? new ItemStack(Items.IRON_NUGGET, 2 + level.random.nextInt(5))
                    : r < 0.90F ? new ItemStack(Items.EMERALD) : ItemStack.EMPTY;
            if (!loot.isEmpty()) {
                MissionManager.giveOrDrop(thief, loot);
            }
        }

        // 2) strip all worn armour down to bare skin / boxers
        boolean stripped = false;
        for (EquipmentSlot slot : ARMOR) {
            ItemStack worn = target.getItemBySlot(slot);
            if (!worn.isEmpty()) {
                target.spawnAtLocation(worn.copy());
                target.setItemSlot(slot, ItemStack.EMPTY);
                stripped = true;
            }
        }
        target.addTag(STRIPPED_TAG); // vanilla scoreboard tag: saved with the entity, readable by commands
        ROBBED_AT.put(target, level.getGameTime());
        HeistNetwork.sendToTrackingAndSelf(target, new StripSyncPacket(target.getId(), true));

        // 3) loud police siren + chase buffs
        int hunt = HeistConfig.GLOVES_HUNT_TICKS.get();
        level.playSound(null, target.getX(), target.getY(), target.getZ(), ModSounds.GLOVES_STEAL.get(), SoundSource.PLAYERS, 1.2F, 1.0F);
        level.playSound(null, target.getX(), target.getY(), target.getZ(), ModSounds.POLICE_SIREN.get(), SoundSource.HOSTILE, 4.0F, 1.0F);
        target.addEffect(new MobEffectInstance(ModEffects.POLICE_SIREN.get(), 320, 0, false, false, false));
        target.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED, hunt, 1, false, true, true));
        target.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, hunt, 0, false, true, true));
        HeistNetwork.sendNear(level, target.position(), 48.0D, new AlarmFlashPacket(160));

        // 4) hunt the thief
        if (target instanceof Mob mob) {
            mob.setTarget(thief);
            mob.getBrain().setMemory(MemoryModuleType.ATTACK_TARGET, thief);
            HUNTS.add(new Hunt(mob, thief.getUUID(), level.getGameTime() + hunt));
        }

        level.sendParticles(ParticleTypes.POOF, target.getX(), target.getY() + 1.0, target.getZ(), 14, 0.3, 0.6, 0.3, 0.02);
        gloves.hurtAndBreak(1, thief, p -> p.broadcastBreakEvent(hand));
        thief.getCooldowns().addCooldown(gloves.getItem(), 20);
        thief.displayClientMessage(Component.translatable(stoleQuest ? "message.heistmod.gloves.quest"
                : stripped ? "message.heistmod.gloves.stripped" : "message.heistmod.gloves.pickpocket"), true);
        HavaldarDirector.keyMoment(thief, KeyMoment.MOB_ROBBED);
    }

    /** Keeps robbed mobs locked on to their thief while the hunt lasts. */
    public static void tick(MinecraftServer server) {
        if (HUNTS.isEmpty() || server.getTickCount() % 10 != 0) {
            return;
        }
        Iterator<Hunt> it = HUNTS.iterator();
        while (it.hasNext()) {
            Hunt hunt = it.next();
            Mob mob = hunt.mob();
            if (mob.isRemoved() || !mob.isAlive() || mob.level().getGameTime() > hunt.until()) {
                it.remove();
                continue;
            }
            Player thief = mob.level().getPlayerByUUID(hunt.player());
            if (thief == null || !thief.isAlive() || thief.isSpectator()) {
                it.remove();
                continue;
            }
            if (mob.getTarget() != thief && !com.heistmod.event.GadgetEvents.wearsSheet(thief)) {
                mob.setTarget(thief);
            }
        }
    }

    public static void clear() {
        HUNTS.clear();
        ROBBED_AT.clear();
    }
}
'''

FILES['src/main/java/com/heistmod/gadget/QuestRaycast.java'] = r'''package com.heistmod.gadget;

import com.heistmod.blockentity.TrophyPedestalBlockEntity;
import com.heistmod.registry.ModTags;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.ClipContext;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.HitResult;
import net.minecraft.world.phys.Vec3;

import org.jetbrains.annotations.Nullable;
import java.util.List;
import java.util.Optional;
import java.util.function.Supplier;

/**
 * The Chingam Grappler's targeting: a long raycast that sees through glass (visual shapes) and finds either a quest item
 * hovering over a {@link TrophyPedestalBlockEntity} or a dropped quest {@link ItemEntity}.
 */
public final class QuestRaycast {
    public record Hit(Vec3 position, Supplier<ItemStack> taker, double distance) {
        public ItemStack take() {
            return taker.get();
        }
    }

    private QuestRaycast() {}

    /** End point of the ray (used for the miss tracer). */
    public static Vec3 rayEnd(Player player, double range) {
        return player.getEyePosition().add(player.getViewVector(1.0F).scale(range));
    }

    @Nullable
    public static Hit find(ServerLevel level, Player player, double range) {
        Vec3 start = player.getEyePosition();
        Vec3 look = player.getViewVector(1.0F);
        Vec3 end = start.add(look.scale(range));

        BlockHitResult block = level.clip(new ClipContext(start, end, ClipContext.Block.VISUAL, ClipContext.Fluid.NONE, player));
        double maxDist = block.getType() == HitResult.Type.MISS ? range : block.getLocation().distanceTo(start);

        Hit best = null;

        // 1) quest items on pedestals (the item floats ~1 block above the block, so test against its display point)
        for (TrophyPedestalBlockEntity pedestal : TrophyPedestalBlockEntity.loaded()) {
            if (pedestal.getLevel() != level || !pedestal.hasItem()) {
                continue;
            }
            Vec3 center = pedestal.displayCenter();
            double t = center.subtract(start).dot(look);
            if (t < 0.5D || t > maxDist + 1.0D) {
                continue;
            }
            Vec3 closest = start.add(look.scale(t));
            if (closest.distanceToSqr(center) <= 0.85D * 0.85D && (best == null || t < best.distance())) {
                best = new Hit(center, pedestal::take, t);
            }
        }

        // 2) dropped quest items
        AABB search = new AABB(start, end).inflate(1.5D);
        List<ItemEntity> items = level.getEntitiesOfClass(ItemEntity.class, search, e -> e.isAlive() && e.getItem().is(ModTags.QUEST_ITEMS));
        for (ItemEntity entity : items) {
            Optional<Vec3> clip = entity.getBoundingBox().inflate(0.35D).clip(start, end);
            if (clip.isPresent()) {
                double d = clip.get().distanceTo(start);
                if (d <= maxDist + 0.5D && (best == null || d < best.distance())) {
                    best = new Hit(entity.position().add(0, 0.2, 0), () -> {
                        ItemStack stack = entity.getItem().copy();
                        entity.discard();
                        return stack;
                    }, d);
                }
            }
        }
        return best;
    }
}
'''

FILES['src/main/java/com/heistmod/gadget/ReelManager.java'] = r'''package com.heistmod.gadget;

import com.heistmod.mission.MissionManager;
import com.heistmod.registry.ModItems;
import com.heistmod.registry.ModSounds;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.phys.Vec3;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.UUID;

/** Visual + logical "snap and reel": a carrier item entity flies from the target to the shooter, then is delivered. */
public final class ReelManager {
    private static final class Reel {
        final UUID player;
        final ItemStack stack;
        final ItemEntity carrier;
        int ticks;

        Reel(UUID player, ItemStack stack, ItemEntity carrier) {
            this.player = player;
            this.stack = stack;
            this.carrier = carrier;
        }
    }

    private static final List<Reel> REELS = new ArrayList<>();

    private ReelManager() {}

    public static void start(ServerLevel level, ServerPlayer player, ItemStack stack, Vec3 from) {
        ItemEntity carrier = new ItemEntity(level, from.x, from.y, from.z, stack.copy());
        carrier.setNoGravity(true);
        carrier.noPhysics = true;
        carrier.setInvulnerable(true);
        carrier.setPickUpDelay(32767);
        carrier.setUnlimitedLifetime();
        carrier.setGlowingTag(true);
        level.addFreshEntity(carrier);
        REELS.add(new Reel(player.getUUID(), stack, carrier));
    }

    public static void tick(MinecraftServer server) {
        if (REELS.isEmpty()) {
            return;
        }
        Iterator<Reel> it = REELS.iterator();
        while (it.hasNext()) {
            Reel reel = it.next();
            ServerPlayer player = server.getPlayerList().getPlayer(reel.player);
            if (reel.carrier.isRemoved()) {
                it.remove();
                continue;
            }
            if (player == null || !player.isAlive() || player.level() != reel.carrier.level()) {
                // Shooter vanished: just let the item drop where it is.
                reel.carrier.noPhysics = false;
                reel.carrier.setNoGravity(false);
                reel.carrier.setPickUpDelay(10);
                it.remove();
                continue;
            }
            ServerLevel level = player.serverLevel();
            Vec3 target = player.getEyePosition().add(0.0D, -0.35D, 0.0D);
            Vec3 pos = reel.carrier.position();
            Vec3 delta = target.subtract(pos);
            double dist = delta.length();
            reel.ticks++;
            if (dist < 1.4D || reel.ticks > 160) {
                deliver(level, player, reel);
                it.remove();
                continue;
            }
            Vec3 step = delta.scale(Math.min(3.2D, dist) / dist);
            reel.carrier.setDeltaMovement(step);
            reel.carrier.setPos(pos.add(step));
            reel.carrier.hasImpulse = true;
            level.sendParticles(ParticleTypes.END_ROD, pos.x, pos.y + 0.2, pos.z, 2, 0.05, 0.05, 0.05, 0.0);
            level.sendParticles(ParticleTypes.ELECTRIC_SPARK, pos.x, pos.y + 0.2, pos.z, 2, 0.12, 0.12, 0.12, 0.0);
        }
    }

    private static void deliver(ServerLevel level, ServerPlayer player, Reel reel) {
        reel.carrier.discard();
        ItemStack stack = reel.stack.copy();
        MissionManager.giveOrDrop(player, stack);
        level.playSound(null, player.getX(), player.getY(), player.getZ(), ModSounds.CHINGAM_GRAB.get(), SoundSource.PLAYERS, 1.2F, 1.0F);
        level.sendParticles(ParticleTypes.FIREWORK, player.getX(), player.getEyeY() - 0.3, player.getZ(), 14, 0.3, 0.3, 0.3, 0.05);
        if (reel.stack.is(ModItems.WARDENS_SQUEAKY_TOY.get())) {
            level.playSound(null, player.getX(), player.getY(), player.getZ(), ModSounds.TOY_SQUEAK.get(), SoundSource.PLAYERS, 1.6F, 1.0F);
        }
        MissionManager.onQuestItemObtained(player, reel.stack);
    }

    public static void clear() {
        REELS.clear();
    }
}
'''

FILES['src/main/java/com/heistmod/gadget/RocketFlights.java'] = r'''package com.heistmod.gadget;

import com.heistmod.HeistConfig;
import com.heistmod.entity.HavaldarDirector;
import com.heistmod.mission.HeistProgress;
import com.heistmod.mission.KeyMoment;
import com.heistmod.mission.Mission;
import com.heistmod.mission.MissionManager;
import com.heistmod.network.HeistNetwork;
import com.heistmod.network.RocketBurnPacket;
import com.heistmod.registry.ModSounds;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.network.chat.Component;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.phys.Vec3;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

/**
 * Tier 4 flight state machine. The launch applies +4.0 Y velocity instantly; the client then keeps that burn going for
 * exactly as many ticks as needed so the apex lands at the configured altitude (vanilla air drag would otherwise cap a
 * +4.0 launch at ~61 blocks). Afterwards the server watches for the landing: a survived landing completes Mission 4.
 */
public final class RocketFlights {
    private static final class Flight {
        final double startY;
        final int thrustTicks;
        double maxY;
        int ticks;

        Flight(double startY, int thrustTicks) {
            this.startY = startY;
            this.thrustTicks = thrustTicks;
            this.maxY = startY;
        }
    }

    private static final Map<UUID, Flight> FLIGHTS = new HashMap<>();

    private RocketFlights() {}

    public static boolean isFlying(Player player) {
        return FLIGHTS.containsKey(player.getUUID());
    }

    public static void clear() {
        FLIGHTS.clear();
    }

    /** Altitude gain of a launch that burns {@code thrust} ticks at {@code v0} and then coasts under vanilla air physics. */
    public static double apex(double v0, int thrust) {
        double y = thrust * v0;
        double v = v0;
        while (v > 0.0D) {
            y += v;
            v = (v - 0.08D) * 0.98D;
        }
        return y;
    }

    public static int thrustTicksFor(double v0, double altitude) {
        for (int t = 0; t <= 600; t++) {
            if (apex(v0, t) >= altitude) {
                return t;
            }
        }
        return 600;
    }

    public static void launch(ServerPlayer player) {
        ServerLevel level = player.serverLevel();
        double v0 = HeistConfig.ROCKET_LAUNCH_VELOCITY.get();
        int thrust = thrustTicksFor(v0, HeistConfig.ROCKET_ALTITUDE.get());
        FLIGHTS.put(player.getUUID(), new Flight(player.getY(), thrust));

        Vec3 dm = player.getDeltaMovement();
        player.setDeltaMovement(dm.x, v0, dm.z);
        player.hurtMarked = true;
        player.fallDistance = 0.0F;
        HeistNetwork.sendTo(player, new RocketBurnPacket(thrust, v0));

        // "Boots / legs on fire for 4 seconds" - forces the water bucket MLG on landing.
        player.setSecondsOnFire(HeistConfig.ROCKET_FIRE_SECONDS.get());
        ItemStack boots = player.getItemBySlot(EquipmentSlot.FEET);
        if (!boots.isEmpty() && boots.isDamageableItem()) {
            boots.hurtAndBreak(8, player, p -> p.broadcastBreakEvent(EquipmentSlot.FEET));
        }

        double x = player.getX();
        double y = player.getY();
        double z = player.getZ();
        level.playSound(null, x, y, z, ModSounds.ROCKET_IGNITE.get(), SoundSource.PLAYERS, 2.0F, 1.0F);
        level.playSound(null, x, y, z, ModSounds.ROCKET_LAUNCH.get(), SoundSource.PLAYERS, 5.0F, 1.0F);
        level.playSound(null, x, y, z, ModSounds.ROCKET_BOOM.get(), SoundSource.PLAYERS, 3.0F, 1.0F);
        level.sendParticles(ParticleTypes.EXPLOSION_EMITTER, x, y, z, 1, 0.0, 0.0, 0.0, 0.0);
        level.sendParticles(ParticleTypes.FIREWORK, x, y, z, 60, 0.4, 0.1, 0.4, 0.25);
        level.sendParticles(ParticleTypes.LARGE_SMOKE, x, y, z, 40, 0.5, 0.2, 0.5, 0.08);
        player.displayClientMessage(Component.translatable("message.heistmod.rocket.mlg"), true);
        HavaldarDirector.keyMoment(player, KeyMoment.ROCKET_LAUNCHED);
    }

    public static void tick(MinecraftServer server) {
        if (FLIGHTS.isEmpty()) {
            return;
        }
        for (ServerPlayer player : new java.util.ArrayList<>(server.getPlayerList().getPlayers())) {
            tickPlayer(player);
        }
        FLIGHTS.keySet().removeIf(id -> server.getPlayerList().getPlayer(id) == null);
    }

    private static void tickPlayer(ServerPlayer player) {
        Flight flight = FLIGHTS.get(player.getUUID());
        if (flight == null) {
            return;
        }
        flight.ticks++;
        flight.maxY = Math.max(flight.maxY, player.getY());
        ServerLevel level = player.serverLevel();

        // Spark & smoke trail while burning and for a couple of seconds after.
        if (flight.ticks <= flight.thrustTicks + 40) {
            double x = player.getX();
            double y = player.getY() + 0.1D;
            double z = player.getZ();
            boolean burning = flight.ticks <= flight.thrustTicks;
            level.sendParticles(ParticleTypes.FIREWORK, x, y, z, burning ? 14 : 5, 0.25, 0.05, 0.25, 0.14);
            level.sendParticles(ParticleTypes.LARGE_SMOKE, x, y, z, burning ? 6 : 3, 0.25, 0.1, 0.25, 0.03);
            if (burning) {
                level.sendParticles(ParticleTypes.FLAME, x, y, z, 8, 0.2, 0.05, 0.2, 0.06);
                if (flight.ticks % 4 == 0) {
                    level.sendParticles(ParticleTypes.EXPLOSION, x, y, z, 1, 0.1, 0.0, 0.1, 0.0);
                }
            }
        }

        if (!player.isAlive()) {
            FLIGHTS.remove(player.getUUID());
            return;
        }
        if (flight.ticks > 12 && (player.onGround() || player.isInWater() || player.isInLava() || player.isPassenger() || player.getAbilities().flying)) {
            FLIGHTS.remove(player.getUUID());
            land(player, flight);
        } else if (flight.ticks > 20 * 120) {
            FLIGHTS.remove(player.getUUID());
        }
    }

    private static void land(ServerPlayer player, Flight flight) {
        double gain = flight.maxY - flight.startY;
        if (gain < HeistConfig.ROCKET_ALTITUDE.get() * 0.5D) {
            return;
        }
        player.serverLevel().sendParticles(ParticleTypes.CLOUD, player.getX(), player.getY(), player.getZ(), 30, 0.6, 0.1, 0.6, 0.05);
        player.displayClientMessage(Component.translatable("message.heistmod.rocket.landed", (int) gain), true);
        HeistProgress progress = HeistProgress.of(player);
        if (!progress.isCompleted(Mission.ROCKET) && progress.isUnlocked(Mission.ROCKET)) {
            MissionManager.pay(player, Mission.ROCKET.rewardDiamonds, Mission.ROCKET.rewardTokens);
            MissionManager.complete(player, Mission.ROCKET);
        }
    }
}
'''

