FILES['src/main/java/com/heistmod/item/SqueakyToyItem.java'] = r'''package com.heistmod.item;

import com.heistmod.registry.ModSounds;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResultHolder;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;

/** The Warden's Squeaky Toy. Squeeze it for a (very) loud squeak - the Warden would not approve. */
public class SqueakyToyItem extends QuestItem {
    public SqueakyToyItem(Properties properties) {
        super(properties);
    }

    @Override
    public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
        ItemStack stack = player.getItemInHand(hand);
        if (player.getCooldowns().isOnCooldown(this)) {
            return InteractionResultHolder.pass(stack);
        }
        player.getCooldowns().addCooldown(this, 20);
        level.playSound(null, player.getX(), player.getY(), player.getZ(), ModSounds.TOY_SQUEAK.get(), SoundSource.PLAYERS, 1.2F, 0.9F + level.random.nextFloat() * 0.3F);
        return InteractionResultHolder.sidedSuccess(stack, level.isClientSide());
    }
}
'''

FILES['src/main/java/com/heistmod/menu/MissionBoardMenu.java'] = r'''package com.heistmod.menu;

import com.heistmod.mission.HeistProgress;
import com.heistmod.mission.Mission;
import com.heistmod.mission.MissionManager;
import com.heistmod.registry.ModBlocks;
import com.heistmod.registry.ModMenus;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.inventory.ContainerLevelAccess;
import net.minecraft.world.item.ItemStack;

/**
 * Slot-less menu for the mission board. Button ids: {@code 1..5} accept / track that mission,
 * {@link #BUTTON_STOP_TRACKING} clears the tracked mission. Mission state itself is synced through
 * {@link com.heistmod.network.SyncProgressPacket}.
 */
public class MissionBoardMenu extends AbstractContainerMenu {
    public static final int BUTTON_STOP_TRACKING = 0;

    private final ContainerLevelAccess access;

    /** Client-side factory (see {@link ModMenus}). */
    public MissionBoardMenu(int id, Inventory inventory) {
        this(id, inventory, ContainerLevelAccess.NULL);
    }

    public MissionBoardMenu(int id, Inventory inventory, ContainerLevelAccess access) {
        super(ModMenus.MISSION_BOARD.get(), id);
        this.access = access;
    }

    @Override
    public boolean clickMenuButton(Player player, int buttonId) {
        if (!(player instanceof ServerPlayer serverPlayer)) {
            return false;
        }
        HeistProgress progress = HeistProgress.of(serverPlayer);
        if (buttonId == BUTTON_STOP_TRACKING) {
            progress.setActive(null);
            MissionManager.sync(serverPlayer);
            return true;
        }
        Mission mission = Mission.byTier(buttonId);
        if (mission == null || !progress.isUnlocked(mission)) {
            return false;
        }
        return MissionManager.activate(serverPlayer, mission);
    }

    @Override
    public ItemStack quickMoveStack(Player player, int index) {
        return ItemStack.EMPTY;
    }

    @Override
    public boolean stillValid(Player player) {
        return stillValid(access, player, ModBlocks.MISSION_BOARD.get());
    }
}
'''

FILES['src/main/java/com/heistmod/mission/HeistProgress.java'] = r'''package com.heistmod.mission;

import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.entity.player.Player;

import org.jetbrains.annotations.Nullable;

/**
 * Per-player campaign state. Server-side only: backed by {@link HeistSavedData} (keyed by player UUID, so it survives
 * death, respawn and dimension travel without any copy step). Bit masks use {@link Mission#bit()}.
 */
public final class HeistProgress {
    private final CompoundTag tag;
    private final HeistSavedData data;

    private HeistProgress(CompoundTag tag, HeistSavedData data) {
        this.tag = tag;
        this.data = data;
    }

    public static HeistProgress of(Player player) {
        MinecraftServer server = player.getServer();
        if (server == null) {
            throw new IllegalStateException("HeistProgress is server-side only (client state lives in ClientHeistState)");
        }
        HeistSavedData data = HeistSavedData.get(server);
        return new HeistProgress(data.player(player.getUUID()), data);
    }

    // ------------------------------------------------------------------ active mission
    @Nullable
    public Mission active() {
        return Mission.byTier(tag.getInt("active"));
    }

    public void setActive(@Nullable Mission m) {
        tag.putInt("active", m == null ? 0 : m.tier);
        data.setDirty();
    }

    // ------------------------------------------------------------------ masks
    public boolean isCompleted(Mission m) {
        return (tag.getInt("completed") & m.bit()) != 0;
    }

    public void setCompleted(Mission m) {
        tag.putInt("completed", tag.getInt("completed") | m.bit());
        data.setDirty();
    }

    public int completedMask() {
        return tag.getInt("completed");
    }

    public boolean isUnlocked(Mission m) {
        return m.tier == 1 || isCompleted(Mission.byTier(m.tier - 1));
    }

    public boolean gadgetIssued(Mission m) {
        return (tag.getInt("gadgets") & m.bit()) != 0;
    }

    public void setGadgetIssued(Mission m) {
        tag.putInt("gadgets", tag.getInt("gadgets") | m.bit());
        data.setDirty();
    }

    public int gadgetMask() {
        return tag.getInt("gadgets");
    }

    public boolean itemObtained(Mission m) {
        return (tag.getInt("items") & m.bit()) != 0;
    }

    public void setItemObtained(Mission m) {
        tag.putInt("items", tag.getInt("items") | m.bit());
        data.setDirty();
    }

    public int itemMask() {
        return tag.getInt("items");
    }

    // ------------------------------------------------------------------ economy / chaos
    public long chaos() {
        return tag.getLong("chaos");
    }

    public void setChaos(long value) {
        tag.putLong("chaos", Math.max(0L, Math.min(10_000_000L, value)));
        data.setDirty();
    }

    public int diamondsEarned() {
        return tag.getInt("diamonds");
    }

    public void addDiamondsEarned(int n) {
        tag.putInt("diamonds", tag.getInt("diamonds") + n);
        data.setDirty();
    }

    public int tokensEarned() {
        return tag.getInt("tokens");
    }

    public void addTokensEarned(int n) {
        tag.putInt("tokens", tag.getInt("tokens") + n);
        data.setDirty();
    }

    public boolean allComplete() {
        return completedMask() == (1 << Mission.VALUES.length) - 1;
    }

    public void reset() {
        for (String key : new java.util.ArrayList<>(tag.getAllKeys())) {
            tag.remove(key);
        }
        tag.putInt("active", 1);
        data.setDirty();
    }
}
'''

FILES['src/main/java/com/heistmod/mission/HeistSavedData.java'] = r'''package com.heistmod.mission;

import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.Tag;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.level.saveddata.SavedData;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

/** World save data ({@code data/heistmod.dat} of the overworld): one compound of campaign progress per player UUID. */
public class HeistSavedData extends SavedData {
    private static final String NAME = "heistmod";
    private final Map<UUID, CompoundTag> players = new HashMap<>();

    public static HeistSavedData get(MinecraftServer server) {
        return server.overworld().getDataStorage().computeIfAbsent(HeistSavedData::load, HeistSavedData::new, NAME);
    }

    public CompoundTag player(UUID id) {
        return players.computeIfAbsent(id, k -> {
            CompoundTag fresh = new CompoundTag();
            fresh.putInt("active", 1);
            setDirty();
            return fresh;
        });
    }

    public static HeistSavedData load(CompoundTag root) {
        HeistSavedData data = new HeistSavedData();
        CompoundTag list = root.getCompound("players");
        for (String key : list.getAllKeys()) {
            try {
                if (list.contains(key, Tag.TAG_COMPOUND)) {
                    data.players.put(UUID.fromString(key), list.getCompound(key));
                }
            } catch (IllegalArgumentException ignored) {
                // not a UUID - skip
            }
        }
        return data;
    }

    @Override
    public CompoundTag save(CompoundTag root) {
        CompoundTag list = new CompoundTag();
        players.forEach((id, tag) -> list.put(id.toString(), tag));
        root.put("players", list);
        return root;
    }
}
'''

