FILES['src/main/java/com/heistmod/network/DialoguePacket.java'] = r'''package com.heistmod.network;

import com.heistmod.HeistMod;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.network.chat.Component;

import java.util.ArrayList;
import java.util.List;

/** One page of an NPC conversation. {@code close == true} dismisses the dialogue screen. */
public record DialoguePacket(int entityId, boolean close, Component speaker, Component text, List<Component> options) implements HeistPacket {
    public static final ResourceLocation ID = HeistMod.id("dialogue");

    @Override
    public ResourceLocation id() {
        return ID;
    }

    public static DialoguePacket closing(int entityId) {
        return new DialoguePacket(entityId, true, Component.empty(), Component.empty(), List.of());
    }

    @Override
    public void encode(FriendlyByteBuf buf) {
        buf.writeVarInt(entityId);
        buf.writeBoolean(close);
        buf.writeComponent(speaker);
        buf.writeComponent(text);
        buf.writeVarInt(options.size());
        for (Component option : options) {
            buf.writeComponent(option);
        }
    }

    public static DialoguePacket decode(FriendlyByteBuf buf) {
        int entityId = buf.readVarInt();
        boolean close = buf.readBoolean();
        Component speaker = buf.readComponent();
        Component text = buf.readComponent();
        int n = buf.readVarInt();
        List<Component> options = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            options.add(buf.readComponent());
        }
        return new DialoguePacket(entityId, close, speaker, text, options);
    }
}
'''

FILES['src/main/java/com/heistmod/network/HeistNetwork.java'] = r'''package com.heistmod.network;

import com.heistmod.dialogue.DialogueManager;
import net.fabricmc.fabric.api.networking.v1.PacketByteBufs;
import net.fabricmc.fabric.api.networking.v1.PlayerLookup;
import net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.phys.Vec3;

/**
 * Server side of the mod's networking (Fabric Networking API v1). Every packet is a small record implementing
 * {@link HeistPacket}; the client-bound receivers are registered in {@code com.heistmod.client.ClientNetwork}.
 */
public final class HeistNetwork {
    private HeistNetwork() {}

    public static void registerServerReceivers() {
        ServerPlayNetworking.registerGlobalReceiver(DialogueChoicePacket.ID, (server, player, handler, buf, responseSender) -> {
            DialogueChoicePacket packet = DialogueChoicePacket.decode(buf);
            server.execute(() -> DialogueManager.choose(player, packet.entityId(), packet.option()));
        });
    }

    public static void sendTo(ServerPlayer player, HeistPacket message) {
        if (!ServerPlayNetworking.canSend(player, message.id())) {
            return; // vanilla client or mod missing on that client
        }
        FriendlyByteBuf buf = PacketByteBufs.create();
        message.encode(buf);
        ServerPlayNetworking.send(player, message.id(), buf);
    }

    public static void sendToTrackingAndSelf(Entity entity, HeistPacket message) {
        for (ServerPlayer player : PlayerLookup.tracking(entity)) {
            sendTo(player, message);
        }
        if (entity instanceof ServerPlayer self) {
            sendTo(self, message);
        }
    }

    public static void sendNear(ServerLevel level, Vec3 pos, double radius, HeistPacket message) {
        for (ServerPlayer player : PlayerLookup.around(level, pos, radius)) {
            sendTo(player, message);
        }
    }
}
'''

FILES['src/main/java/com/heistmod/network/HeistPacket.java'] = r'''package com.heistmod.network;

import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.resources.ResourceLocation;

/** A tiny self-describing packet: channel id + encoder. Decoders are static {@code decode(FriendlyByteBuf)} methods. */
public interface HeistPacket {
    ResourceLocation id();

    void encode(FriendlyByteBuf buf);
}
'''

FILES['src/main/java/com/heistmod/network/RocketBurnPacket.java'] = r'''package com.heistmod.network;

import com.heistmod.HeistMod;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.resources.ResourceLocation;

/**
 * Tells the local client to hold its own upward velocity at {@code velocity} blocks/tick for {@code ticks} ticks.
 * (Player movement is client-authoritative, so the burn is applied client-side to keep air steering intact.)
 */
public record RocketBurnPacket(int ticks, double velocity) implements HeistPacket {
    public static final ResourceLocation ID = HeistMod.id("rocket_burn");

    @Override
    public ResourceLocation id() {
        return ID;
    }

    @Override
    public void encode(FriendlyByteBuf buf) {
        buf.writeVarInt(ticks);
        buf.writeDouble(velocity);
    }

    public static RocketBurnPacket decode(FriendlyByteBuf buf) {
        return new RocketBurnPacket(buf.readVarInt(), buf.readDouble());
    }
}
'''

