FILES['src/main/java/com/heistmod/network/SyncProgressPacket.java'] = r'''package com.heistmod.network;

import com.heistmod.HeistMod;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.resources.ResourceLocation;

/** Full campaign snapshot for the local player (mission board GUI + HUD tracker). */
public record SyncProgressPacket(int active, int completed, int gadgets, int items, long chaos, int diamonds) implements HeistPacket {
    public static final ResourceLocation ID = HeistMod.id("sync_progress");

    @Override
    public ResourceLocation id() {
        return ID;
    }

    @Override
    public void encode(FriendlyByteBuf buf) {
        buf.writeVarInt(active);
        buf.writeVarInt(completed);
        buf.writeVarInt(gadgets);
        buf.writeVarInt(items);
        buf.writeLong(chaos);
        buf.writeVarInt(diamonds);
    }

    public static SyncProgressPacket decode(FriendlyByteBuf buf) {
        return new SyncProgressPacket(buf.readVarInt(), buf.readVarInt(), buf.readVarInt(), buf.readVarInt(), buf.readLong(), buf.readVarInt());
    }
}
'''

