FILES['src/main/java/com/heistmod/registry/ModSounds.java'] = r'''package com.heistmod.registry;

import com.heistmod.HeistMod;
import net.minecraft.core.Registry;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.sounds.SoundEvent;

import java.util.ArrayList;
import java.util.List;

/**
 * Every sound event. The events are mapped to {@code .ogg} files by {@code assets/heistmod/sounds.json}
 * (generated from the folder layout by build_mod.py, see --sync-assets). To replace a sound, drop a new .ogg with the same
 * path into {@code assets/heistmod/sounds/...}; extra variants (name_2.ogg ...) are picked up by --sync-assets.
 */
public final class ModSounds {
    // --- Tier 1
    public static final Reg<SoundEvent> CHINGAM_FIRE = reg("item.chingam.fire");
    public static final Reg<SoundEvent> CHINGAM_SQUISH = reg("item.chingam.squish");
    public static final Reg<SoundEvent> CHINGAM_REEL = reg("item.chingam.reel");
    public static final Reg<SoundEvent> CHINGAM_GRAB = reg("item.chingam.grab");
    public static final Reg<SoundEvent> TOY_SQUEAK = reg("item.toy.squeak");
    // --- Tier 2
    public static final Reg<SoundEvent> GLOVES_STEAL = reg("item.gloves.steal");
    public static final Reg<SoundEvent> POLICE_SIREN = reg("item.gloves.siren");
    // --- Tier 3
    public static final Reg<SoundEvent> CHADDAR_HUU = reg("item.chaddar.huu");
    public static final Reg<SoundEvent> CHADDAR_SHATTER = reg("item.chaddar.shatter");
    public static final Reg<SoundEvent> CHADDAR_EQUIP = reg("item.chaddar.equip");
    // --- Tier 4
    public static final Reg<SoundEvent> ROCKET_IGNITE = reg("item.rocket.ignite");
    public static final Reg<SoundEvent> ROCKET_LAUNCH = reg("item.rocket.launch");
    public static final Reg<SoundEvent> ROCKET_BOOM = reg("item.rocket.boom");
    // --- Tier 5
    public static final Reg<SoundEvent> THAILA_ARM = reg("block.thaila.arm");
    public static final Reg<SoundEvent> THAILA_OPEN = reg("block.thaila.open");
    public static final Reg<SoundEvent> THAILA_SIPHON = reg("block.thaila.siphon");
    public static final Reg<SoundEvent> THAILA_COMPLETE = reg("block.thaila.complete");
    // --- World
    public static final Reg<SoundEvent> LASER_HUM = reg("block.laser.hum");
    public static final Reg<SoundEvent> LASER_TRIP = reg("block.laser.trip");
    public static final Reg<SoundEvent> ALARM_SIREN = reg("block.alarm.siren");
    public static final Reg<SoundEvent> BOARD_OPEN = reg("block.board.open");
    public static final Reg<SoundEvent> PEDESTAL_RESTOCK = reg("block.pedestal.restock");
    public static final Reg<SoundEvent> MUSEUM_WHISPER = reg("ambient.museum.whisper");
    // --- UI
    public static final Reg<SoundEvent> MISSION_ACCEPT = reg("ui.mission.accept");
    public static final Reg<SoundEvent> MISSION_COMPLETE = reg("ui.mission.complete");
    public static final Reg<SoundEvent> PAY = reg("ui.pay");
    // --- NPC voices
    public static final Reg<SoundEvent> AGENT_TALK = reg("entity.agent_zero.talk");
    public static final List<Reg<SoundEvent>> AGENT_LINES = regN("entity.agent_zero.line_", 4);
    public static final Reg<SoundEvent> DEALER_TALK = reg("entity.dealer.talk");
    public static final Reg<SoundEvent> DEALER_DEAL = reg("entity.dealer.deal");
    public static final List<Reg<SoundEvent>> DEALER_LINES = regN("entity.dealer.line_", 3);
    public static final Reg<SoundEvent> HAVALDAR_WHISTLE = reg("entity.havaldar.whistle");
    public static final Reg<SoundEvent> HAVALDAR_ARRIVE = reg("entity.havaldar.arrive");
    public static final List<Reg<SoundEvent>> HAVALDAR_CHASE = regN("entity.havaldar.chase_", 8);
    public static final Reg<SoundEvent> HAVALDAR_ATTACK = reg("entity.havaldar.attack");
    public static final Reg<SoundEvent> HAVALDAR_HURT = reg("entity.havaldar.hurt");
    public static final Reg<SoundEvent> HAVALDAR_DEATH = reg("entity.havaldar.death");
    public static final Reg<SoundEvent> HAVALDAR_RETREAT = reg("entity.havaldar.retreat");

    private static Reg<SoundEvent> reg(String path) {
        ResourceLocation id = HeistMod.id(path);
        return new Reg<>(id, Registry.register(BuiltInRegistries.SOUND_EVENT, id, SoundEvent.createVariableRangeEvent(id)));
    }

    private static List<Reg<SoundEvent>> regN(String prefix, int count) {
        List<Reg<SoundEvent>> list = new ArrayList<>();
        for (int i = 1; i <= count; i++) {
            list.add(reg(prefix + i));
        }
        return List.copyOf(list);
    }

    /** Forces class initialisation (all registration happens in the static fields above). */
    public static void init() {}

    private ModSounds() {}
}
'''

