FILES['src/main/java/com/heistmod/registry/Reg.java'] = r'''package com.heistmod.registry;

import net.minecraft.resources.ResourceLocation;

import java.util.function.Supplier;

/** A registered object plus its id. {@link #get()} keeps call sites loader-agnostic (same shape as a registry object). */
public final class Reg<T> implements Supplier<T> {
    private final ResourceLocation id;
    private final T value;

    public Reg(ResourceLocation id, T value) {
        this.id = id;
        this.value = value;
    }

    @Override
    public T get() {
        return value;
    }

    public ResourceLocation id() {
        return id;
    }
}
'''

FILES['src/main/java/com/heistmod/siphon/ChaosSiphonManager.java'] = r'''package com.heistmod.siphon;

import com.heistmod.HeistConfig;
import com.heistmod.entity.HavaldarDirector;
import com.heistmod.entity.HeistNpc;
import com.heistmod.mission.HeistProgress;
import com.heistmod.mission.KeyMoment;
import com.heistmod.network.ChaosSyncPacket;
import com.heistmod.network.HeistNetwork;
import com.heistmod.registry.ModItems;
import com.heistmod.registry.ModSounds;
import net.minecraft.core.BlockPos;
import net.minecraft.core.SectionPos;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.network.chat.Component;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.effect.MobEffects;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.chunk.LevelChunk;
import net.minecraft.world.level.chunk.LevelChunkSection;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;

import org.jetbrains.annotations.Nullable;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.List;
import java.util.UUID;

/**
 * Tier 5 - the Chaos Siphon. Everything is time-sliced on the server thread (never off-thread: Minecraft's world is not
 * thread-safe): each tick erases at most {@code blocksPerTick} blocks and never spends more than {@code millisPerTick}
 * wall-clock milliseconds, so even a 64 block sphere of solid rock cannot hang the server. Columns are processed in
 * order of distance from the bag, so the void spreads outward from it like a black hole. Meanwhile every entity in range
 * is pulled toward the bag and the HUD counter climbs to exactly 10,000,000.
 */
public final class ChaosSiphonManager {
    public static final long MAX_CHAOS = 10_000_000L;

    private static final List<Job> JOBS = new ArrayList<>();

    private ChaosSiphonManager() {}

    // ------------------------------------------------------------------ job
    private static final class Job {
        final ServerLevel level;
        final BlockPos center;
        final UUID owner;
        final int radius;
        final int[][] columns; // x, z, yTop, yBottom
        final long total;
        final BlockPos.MutableBlockPos pos = new BlockPos.MutableBlockPos();

        int colIndex;
        int y = Integer.MIN_VALUE;
        long visited;
        long erased;
        long age;
        long lastChaos = -1;
        @Nullable
        LevelChunk cachedChunk;
        int cachedCx = Integer.MIN_VALUE;
        int cachedCz = Integer.MIN_VALUE;

        Job(ServerLevel level, BlockPos center, UUID owner, int radius) {
            this.level = level;
            this.center = center;
            this.owner = owner;
            this.radius = radius;
            this.columns = buildColumns(level, center, radius);
            long sum = 0;
            for (int[] c : columns) {
                sum += (long) c[2] - c[3] + 1;
            }
            this.total = Math.max(1L, sum);
        }

        @Nullable
        LevelChunk chunkAt(int x, int z) {
            int cx = x >> 4;
            int cz = z >> 4;
            if (cx != cachedCx || cz != cachedCz) {
                cachedCx = cx;
                cachedCz = cz;
                cachedChunk = level.getChunkSource().getChunkNow(cx, cz);
            }
            return cachedChunk;
        }

        /** @return true once the whole sphere has been processed. */
        boolean run(long deadlineNanos, int maxChanges) {
            int changes = 0;
            int iterations = 0;
            while (colIndex < columns.length) {
                int[] col = columns[colIndex];
                if (y == Integer.MIN_VALUE) {
                    y = col[2];
                }
                LevelChunk chunk = chunkAt(col[0], col[1]);
                if (chunk == null) {
                    visited += (long) y - col[3] + 1;
                    nextColumn();
                    continue;
                }
                while (y >= col[3]) {
                    int sectionIndex = chunk.getSectionIndex(y);
                    LevelChunkSection section = chunk.getSection(sectionIndex);
                    if (section.hasOnlyAir()) {
                        int sectionBottom = SectionPos.sectionToBlockCoord(chunk.getSectionYFromSectionIndex(sectionIndex));
                        int newY = Math.max(col[3] - 1, sectionBottom - 1);
                        visited += y - newY;
                        y = newY;
                        continue;
                    }
                    pos.set(col[0], y, col[1]);
                    BlockState state = chunk.getBlockState(pos);
                    visited++;
                    y--;
                    if (!state.isAir() && !state.is(Blocks.BEDROCK) && !(col[0] == center.getX() && y + 1 == center.getY() && col[1] == center.getZ())) {
                        level.removeBlockEntity(pos);
                        level.setBlock(pos, Blocks.AIR.defaultBlockState(), 2 | 16 | 32);
                        erased++;
                        changes++;
                        if (changes >= maxChanges) {
                            return false;
                        }
                    }
                    if ((++iterations & 127) == 0 && System.nanoTime() > deadlineNanos) {
                        return false;
                    }
                }
                nextColumn();
                if (System.nanoTime() > deadlineNanos) {
                    return colIndex >= columns.length;
                }
            }
            return true;
        }

        private void nextColumn() {
            colIndex++;
            y = Integer.MIN_VALUE;
        }

        long chaos() {
            return Math.min(MAX_CHAOS, (long) ((double) visited / (double) total * MAX_CHAOS));
        }
    }

    /** Columns of the sphere sorted by horizontal distance from the centre (so the erasure spreads outward). */
    private static int[][] buildColumns(ServerLevel level, BlockPos center, int radius) {
        int minY = level.getMinBuildHeight();
        int maxY = level.getMaxBuildHeight() - 1;
        long r2 = (long) radius * radius;
        List<int[]> list = new ArrayList<>();
        for (int dx = -radius; dx <= radius; dx++) {
            for (int dz = -radius; dz <= radius; dz++) {
                long h2 = r2 - (long) dx * dx - (long) dz * dz;
                if (h2 < 0) {
                    continue;
                }
                int dy = (int) Math.floor(Math.sqrt((double) h2));
                int top = Math.min(maxY, center.getY() + dy);
                int bottom = Math.max(minY, center.getY() - dy);
                if (top < bottom) {
                    continue;
                }
                list.add(new int[]{center.getX() + dx, center.getZ() + dz, top, bottom, dx * dx + dz * dz});
            }
        }
        list.sort((a, b) -> Integer.compare(a[4], b[4]));
        int[][] columns = new int[list.size()][];
        for (int i = 0; i < columns.length; i++) {
            columns[i] = Arrays.copyOf(list.get(i), 4);
        }
        return columns;
    }

    // ------------------------------------------------------------------ API
    public static boolean isRunningAt(Level level, BlockPos pos) {
        for (Job job : JOBS) {
            if (job.level == level && job.center.equals(pos)) {
                return true;
            }
        }
        return false;
    }

    public static void start(ServerLevel level, BlockPos center, ServerPlayer owner) {
        if (isRunningAt(level, center)) {
            return;
        }
        Job job = new Job(level, center.immutable(), owner.getUUID(), HeistConfig.SIPHON_RADIUS.get());
        JOBS.add(job);
        owner.sendSystemMessage(Component.translatable("message.heistmod.thaila.opened", job.total));
        level.sendParticles(ParticleTypes.EXPLOSION_EMITTER, center.getX() + 0.5, center.getY() + 1.0, center.getZ() + 0.5, 1, 0, 0, 0, 0);
        // The pull needs gravity-free targets: shield the owner from the drop that follows.
        owner.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 20 * 60, 1, false, false, true));
        HavaldarDirector.keyMoment(owner, KeyMoment.SIPHON_STARTED);
        HeistNetwork.sendNear(level, Vec3.atCenterOf(center), 192.0D, new ChaosSyncPacket(0L, true));
    }

    public static void clear() {
        JOBS.clear();
    }

    // ------------------------------------------------------------------ tick
    public static void tick(MinecraftServer server) {
        if (JOBS.isEmpty()) {
            return;
        }
        Iterator<Job> it = JOBS.iterator();
        while (it.hasNext()) {
            Job job = it.next();
            job.age++;
            pull(job);
            effects(job);
            long deadline = System.nanoTime() + HeistConfig.SIPHON_MILLIS_PER_TICK.get() * 1_000_000L;
            boolean done = job.run(deadline, HeistConfig.SIPHON_BLOCKS_PER_TICK.get());
            long chaos = done ? MAX_CHAOS : job.chaos();
            if (chaos != job.lastChaos && (job.age % 3 == 0 || done)) {
                job.lastChaos = chaos;
                HeistNetwork.sendNear(job.level, Vec3.atCenterOf(job.center), job.radius + 128.0D, new ChaosSyncPacket(chaos, !done));
            }
            if (done) {
                finish(job);
                it.remove();
            }
        }
    }

    private static void effects(Job job) {
        ServerLevel level = job.level;
        double cx = job.center.getX() + 0.5D;
        double cy = job.center.getY() + 0.8D;
        double cz = job.center.getZ() + 0.5D;
        if (job.age % 60 == 1) {
            level.playSound(null, cx, cy, cz, ModSounds.THAILA_SIPHON.get(), SoundSource.BLOCKS, 8.0F, 1.0F);
        }
        level.sendParticles(ParticleTypes.REVERSE_PORTAL, cx, cy, cz, 40, 4.0, 4.0, 4.0, 0.6);
        level.sendParticles(ParticleTypes.PORTAL, cx, cy, cz, 25, 2.0, 2.0, 2.0, 1.0);
        if (job.age % 4 == 0) {
            level.sendParticles(ParticleTypes.SQUID_INK, cx, cy, cz, 6, 0.4, 0.4, 0.4, 0.12);
        }
    }

    /** Inward gravitational pull on every entity in range (players get a gentle orbit instead of being crushed). */
    private static void pull(Job job) {
        ServerLevel level = job.level;
        Vec3 center = Vec3.atCenterOf(job.center).add(0.0D, 0.3D, 0.0D);
        double pullRadius = HeistConfig.SIPHON_PULL_RADIUS.get();
        AABB box = new AABB(job.center).inflate(pullRadius);
        for (Entity e : level.getEntities((Entity) null, box, ent -> !ent.isSpectator() && !(ent instanceof HeistNpc))) {
            Vec3 target = center;
            Vec3 delta = target.subtract(e.position().add(0.0D, e.getBbHeight() * 0.5D, 0.0D));
            double dist = delta.length();
            if (dist < 0.4D || dist > pullRadius) {
                continue;
            }
            boolean player = e instanceof ServerPlayer;
            if (e instanceof ItemEntity item && dist < 1.8D && !item.getItem().is(ModItems.ULTIMATE_FORBIDDEN_CORE.get())) {
                level.sendParticles(ParticleTypes.PORTAL, e.getX(), e.getY(), e.getZ(), 6, 0.1, 0.1, 0.1, 0.2);
                e.discard();
                continue;
            }
            if (e instanceof LivingEntity living && !player && dist < 2.2D && !living.isInvulnerable()) {
                living.hurt(level.damageSources().fellOutOfWorld(), 6.0F);
            }
            double strength = 0.04D + 0.55D * Math.pow(1.0D - dist / pullRadius, 2.0D);
            Vec3 pullVec = delta.scale(strength / dist);
            if (player && dist < 4.0D) {
                pullVec = pullVec.scale(-0.6D); // hover around the core instead of being squeezed into it
            }
            Vec3 motion = e.getDeltaMovement().scale(0.9D).add(pullVec);
            if (motion.length() > 1.5D) {
                motion = motion.normalize().scale(1.5D);
            }
            e.setDeltaMovement(motion);
            e.hasImpulse = true;
            e.fallDistance = 0.0F;
            if (player || e instanceof LivingEntity) {
                e.hurtMarked = true;
            }
        }
    }

    private static void finish(Job job) {
        ServerLevel level = job.level;
        BlockPos center = job.center;
        double cx = center.getX() + 0.5D;
        double cy = center.getY() + 0.8D;
        double cz = center.getZ() + 0.5D;

        level.removeBlockEntity(center);
        level.setBlock(center, Blocks.AIR.defaultBlockState(), 2 | 16 | 32);

        // The single Ultimate Forbidden Core: floating, glowing, indestructible.
        ItemEntity core = new ItemEntity(level, cx, cy + 0.6D, cz, new ItemStack(ModItems.ULTIMATE_FORBIDDEN_CORE.get()));
        core.setNoGravity(true);
        core.setInvulnerable(true);
        core.setUnlimitedLifetime();
        core.setGlowingTag(true);
        core.setDeltaMovement(Vec3.ZERO);
        level.addFreshEntity(core);

        level.playSound(null, cx, cy, cz, ModSounds.THAILA_COMPLETE.get(), SoundSource.BLOCKS, 10.0F, 1.0F);
        for (int i = 0; i < 4; i++) {
            level.sendParticles(ParticleTypes.EXPLOSION_EMITTER, cx + level.random.nextGaussian() * 3, cy + level.random.nextGaussian() * 3, cz + level.random.nextGaussian() * 3, 1, 0, 0, 0, 0);
        }
        level.sendParticles(ParticleTypes.END_ROD, cx, cy + 0.6D, cz, 200, 3.0, 3.0, 3.0, 0.3);
        level.sendParticles(ParticleTypes.FLASH, cx, cy + 0.6D, cz, 3, 0.5, 0.5, 0.5, 0.0);

        ServerPlayer owner = level.getServer().getPlayerList().getPlayer(job.owner);
        if (owner != null) {
            HeistProgress.of(owner).setChaos(MAX_CHAOS);
            HeistNetwork.sendTo(owner, new ChaosSyncPacket(MAX_CHAOS, false));
            owner.addEffect(new MobEffectInstance(MobEffects.SLOW_FALLING, 20 * 100, 0, false, false, true));
            owner.sendSystemMessage(Component.translatable("message.heistmod.thaila.done", job.erased));
        }
    }
}
'''

FILES['src/main/java/com/heistmod/world/AlarmManager.java'] = r'''package com.heistmod.world;

import com.heistmod.block.AlarmBeaconBlock;
import com.heistmod.blockentity.LaserEmitterBlockEntity;
import com.heistmod.entity.HavaldarDirector;
import com.heistmod.event.GadgetEvents;
import com.heistmod.mission.KeyMoment;
import com.heistmod.network.AlarmFlashPacket;
import com.heistmod.network.HeistNetwork;
import com.heistmod.registry.ModBlocks;
import com.heistmod.registry.ModSounds;
import net.minecraft.core.BlockPos;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.network.chat.Component;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.Mob;
import net.minecraft.world.entity.MobSpawnType;
import net.minecraft.world.entity.monster.Monster;
import net.minecraft.world.entity.monster.Vex;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;

import org.jetbrains.annotations.Nullable;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

/** Laser tripwire alarms: siren, flashing beacons, awakened museum ghosts, alerted guards - and Havaldar Thandulal. */
public final class AlarmManager {
    private static final int DURATION = 400;
    private static final int RANGE = 20;

    private static final class Alarm {
        final ServerLevel level;
        final BlockPos pos;
        final List<BlockPos> beacons = new ArrayList<>();
        int ticks;

        Alarm(ServerLevel level, BlockPos pos) {
            this.level = level;
            this.pos = pos;
        }
    }

    private static final List<Alarm> ALARMS = new ArrayList<>();

    private AlarmManager() {}

    /** The Bhootiya Chaddar turns its wearer into a ghost: light passes straight through. */
    public static boolean passesThroughLasers(Player player) {
        return GadgetEvents.wearsSheet(player);
    }

    public static void trip(ServerLevel level, BlockPos emitter, @Nullable ServerPlayer culprit) {
        level.playSound(null, emitter, ModSounds.LASER_TRIP.get(), SoundSource.BLOCKS, 2.0F, 1.0F);
        for (Alarm alarm : ALARMS) {
            if (alarm.level == level && alarm.pos.closerThan(emitter, RANGE * 2.0D)) {
                alarm.ticks = Math.min(alarm.ticks, 100); // already blaring here: just extend it
                return;
            }
        }
        Alarm alarm = new Alarm(level, emitter.immutable());
        BlockPos.MutableBlockPos p = new BlockPos.MutableBlockPos();
        long until = level.getGameTime() + DURATION;
        for (int dy = -6; dy <= 10; dy++) {
            for (int dx = -RANGE; dx <= RANGE; dx++) {
                for (int dz = -RANGE; dz <= RANGE; dz++) {
                    p.set(emitter.getX() + dx, emitter.getY() + dy, emitter.getZ() + dz);
                    BlockState state = level.getBlockState(p);
                    if (state.is(ModBlocks.ALARM_BEACON.get())) {
                        alarm.beacons.add(p.immutable());
                        level.setBlock(p, state.setValue(AlarmBeaconBlock.LIT, true), 3);
                    } else if (state.is(ModBlocks.LASER_EMITTER.get()) && level.getBlockEntity(p) instanceof LaserEmitterBlockEntity laser) {
                        laser.setAlert(true, until);
                    }
                }
            }
        }
        ALARMS.add(alarm);
        Vec3 center = Vec3.atCenterOf(emitter);
        HeistNetwork.sendNear(level, center, 64.0D, new AlarmFlashPacket(DURATION));
        for (ServerPlayer player : level.players()) {
            if (player.distanceToSqr(center) < 64.0D * 64.0D) {
                player.displayClientMessage(Component.translatable("message.heistmod.alarm"), false);
            }
        }
        if (culprit != null) {
            // guards within earshot come running
            for (Monster guard : level.getEntitiesOfClass(Monster.class, new AABB(emitter).inflate(40.0D), Mob::isAlive)) {
                guard.setTarget(culprit);
            }
            // ... and the museum's ghosts wake up for half a minute
            for (int i = 0; i < 2; i++) {
                Vex vex = EntityType.VEX.create(level);
                if (vex != null) {
                    vex.moveTo(culprit.getX() + level.random.nextGaussian() * 3.0D, culprit.getY() + 2.5D, culprit.getZ() + level.random.nextGaussian() * 3.0D, 0.0F, 0.0F);
                    vex.finalizeSpawn(level, level.getCurrentDifficultyAt(emitter), MobSpawnType.EVENT, null, null);
                    vex.setLimitedLife(600);
                    vex.setBoundOrigin(emitter);
                    level.addFreshEntity(vex);
                    vex.setTarget(culprit);
                    level.sendParticles(ParticleTypes.SOUL, vex.getX(), vex.getY(), vex.getZ(), 12, 0.3, 0.3, 0.3, 0.03);
                }
            }
            level.playSound(null, emitter, ModSounds.MUSEUM_WHISPER.get(), SoundSource.HOSTILE, 2.5F, 1.0F);
            HavaldarDirector.keyMoment(culprit, KeyMoment.ALARM_RAISED);
        }
    }

    public static void tick(MinecraftServer server) {
        if (ALARMS.isEmpty()) {
            return;
        }
        Iterator<Alarm> it = ALARMS.iterator();
        while (it.hasNext()) {
            Alarm alarm = it.next();
            if (alarm.ticks % 60 == 0) {
                alarm.level.playSound(null, alarm.pos, ModSounds.ALARM_SIREN.get(), SoundSource.BLOCKS, 5.0F, 1.0F);
            }
            if (++alarm.ticks >= DURATION) {
                for (BlockPos beacon : alarm.beacons) {
                    BlockState state = alarm.level.getBlockState(beacon);
                    if (state.is(ModBlocks.ALARM_BEACON.get())) {
                        alarm.level.setBlock(beacon, state.setValue(AlarmBeaconBlock.LIT, false), 3);
                    }
                }
                it.remove();
            }
        }
    }

    public static void clear() {
        ALARMS.clear();
    }
}
'''

FILES['src/main/java/com/heistmod/world/CityBlueprints.java'] = r'''package com.heistmod.world;

import com.heistmod.block.AlarmBeaconBlock;
import com.heistmod.block.LaserEmitterBlock;
import com.heistmod.block.MissionBoardBlock;
import com.heistmod.registry.ModBlocks;
import net.minecraft.core.Direction;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.LadderBlock;
import net.minecraft.world.level.block.LanternBlock;
import net.minecraft.world.level.block.SlabBlock;
import net.minecraft.world.level.block.StairBlock;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.Half;
import net.minecraft.world.level.block.state.properties.SlabType;

import java.util.ArrayList;
import java.util.List;

/**
 * Procedural blueprints of the Mega City. Coordinates are relative to the city origin: (0, 0, 0) is the street level at
 * the centre of the central plaza; +X east, +Z south. Layout (top view):
 * <pre>
 *   NW: Sector 2 Piglin High-Rise      NE: Sector 1 Bank Vault (vault underground)
 *              central plaza + Capitol launch tower (east of the plaza)
 *              Sector 4 Capitol floating island hovers above the plaza
 *   SW: Sector 3 Haunted Laser Museum  S : Secret Bunker HQ (underground, newsstand entrance)
 * </pre>
 * Every part is a separate {@link Schematic} so it can be exported / replaced with an NBT structure of the same name.
 */
public final class CityBlueprints {
    public static final int HALF = 72;
    public static final int TOWER_X = 33;
    public static final int TOWER_HEIGHT = 64;
    public static final int ISLAND_RADIUS = 30;
    /** Island top above the launch-tower roof; the rocket's 150 block apex clears it, so the player lands on it from above. */
    public static final int ISLAND_ABOVE_ROOF = 112;

    private static final BlockState AIR = Blocks.AIR.defaultBlockState();

    private CityBlueprints() {}

    public static List<Schematic> all(int islandY) {
        List<Schematic> list = new ArrayList<>();
        list.add(plaza());
        list.add(bunker());
        list.add(bank());
        list.add(penthouse());
        list.add(museum());
        list.add(capitol(islandY));
        return list;
    }

    public static Schematic byName(String name, int islandY) {
        for (Schematic s : all(islandY)) {
            if (s.name.equals(name)) {
                return s;
            }
        }
        throw new IllegalArgumentException("Unknown city part: " + name);
    }

    // ================================================================== helpers
    private static BlockState s(Block block) {
        return block.defaultBlockState();
    }

    private static BlockState stairs(Block block, Direction facing, boolean top) {
        return block.defaultBlockState().setValue(StairBlock.FACING, facing).setValue(StairBlock.HALF, top ? Half.TOP : Half.BOTTOM);
    }

    private static BlockState slab(Block block, boolean top) {
        return block.defaultBlockState().setValue(SlabBlock.TYPE, top ? SlabType.TOP : SlabType.BOTTOM);
    }

    private static BlockState ladder(Direction facing) {
        return Blocks.LADDER.defaultBlockState().setValue(LadderBlock.FACING, facing);
    }

    private static BlockState hanging(Block lantern) {
        return lantern.defaultBlockState().setValue(LanternBlock.HANGING, true);
    }

    private static BlockState laser(Direction facing) {
        return ModBlocks.LASER_EMITTER.get().defaultBlockState().setValue(LaserEmitterBlock.FACING, facing);
    }

    private static BlockState beacon() {
        return ModBlocks.ALARM_BEACON.get().defaultBlockState().setValue(AlarmBeaconBlock.LIT, false);
    }

    private static BlockState leaves() {
        return Blocks.CHERRY_LEAVES.defaultBlockState().setValue(net.minecraft.world.level.block.LeavesBlock.PERSISTENT, true);
    }

    private static BlockState neon(String color) {
        return ModBlocks.NEON.get(color).get().defaultBlockState();
    }

    private static CompoundTag pedestalNbt(String itemId) {
        CompoundTag item = new CompoundTag();
        item.putString("id", itemId);
        item.putByte("Count", (byte) 1);
        CompoundTag tag = new CompoundTag();
        tag.put("Item", item);
        tag.put("Restock", item.copy());
        tag.putInt("RestockTimer", -1);
        return tag;
    }

    private static void pedestal(Schematic.Builder b, int x, int y, int z, String itemId) {
        b.set(x, y, z, s(ModBlocks.TROPHY_PEDESTAL.get()));
        b.blockEntity(x, y, z, pedestalNbt(itemId));
    }

    /** Window band: replaces wall blocks of a rectangle outline at height y with glass every other column. */
    private static void windows(Schematic.Builder b, int x0, int z0, int x1, int z1, int y0, int y1, BlockState glass, int spacing) {
        for (int y = y0; y <= y1; y++) {
            for (int x = x0 + 1; x < x1; x++) {
                if ((x - x0) % spacing != 0) {
                    b.set(x, y, z0, glass);
                    b.set(x, y, z1, glass);
                }
            }
            for (int z = z0 + 1; z < z1; z++) {
                if ((z - z0) % spacing != 0) {
                    b.set(x0, y, z, glass);
                    b.set(x1, y, z, glass);
                }
            }
        }
    }

    // ================================================================== plaza, streets, launch tower
    private static Schematic plaza() {
        Schematic.Builder b = new Schematic.Builder("city_plaza");
        // clear the air above street level and lay foundations + streets
        b.fill(-HALF, 0, -HALF, HALF, 14, HALF, AIR);
        b.fill(-HALF, -3, -HALF, HALF, -2, HALF, s(Blocks.STONE));
        b.fill(-HALF, -1, -HALF, HALF, -1, HALF, s(Blocks.SMOOTH_STONE));
        // avenues (N-S and E-W) with lane markings
        for (int i = -HALF; i <= HALF; i++) {
            for (int w = -3; w <= 3; w++) {
                b.set(i, -1, w, s(Blocks.GRAY_CONCRETE));
                b.set(w, -1, i, s(Blocks.GRAY_CONCRETE));
            }
            if (Math.floorMod(i, 6) < 3) {
                b.set(i, -1, 0, s(Blocks.YELLOW_CONCRETE));
                b.set(0, -1, i, s(Blocks.YELLOW_CONCRETE));
            }
            // sidewalks
            for (int side : new int[]{-4, 4}) {
                b.set(i, -1, side, s(Blocks.POLISHED_ANDESITE));
                b.set(side, -1, i, s(Blocks.POLISHED_ANDESITE));
            }
        }
        // central plaza: fountain ring + benches + lamp posts
        b.disc(0, -1, 0, 14, s(Blocks.POLISHED_DIORITE));
        b.ring(0, -1, 0, 12, 14, s(Blocks.CHISELED_STONE_BRICKS));
        b.ring(0, 0, 0, 5, 6, s(Blocks.QUARTZ_BRICKS));
        b.disc(0, 0, 0, 4.9, s(Blocks.WATER));
        b.fill(0, 0, 0, 0, 3, 0, s(Blocks.QUARTZ_PILLAR));
        b.set(0, 4, 0, s(Blocks.SEA_LANTERN));
        for (int[] p : new int[][]{{9, 9}, {-9, 9}, {9, -9}, {-9, -9}}) {
            b.fill(p[0], 0, p[1], p[0], 3, p[1], s(Blocks.DARK_OAK_FENCE));
            b.set(p[0], 4, p[1], s(Blocks.LANTERN));
        }
        // street lamps along the avenues
        for (int i = -64; i <= 64; i += 12) {
            if (Math.abs(i) < 16) {
                continue;
            }
            for (int[] p : new int[][]{{i, 5}, {i, -5}, {5, i}, {-5, i}}) {
                b.fill(p[0], 0, p[1], p[0], 4, p[1], s(Blocks.POLISHED_BLACKSTONE_WALL));
                b.set(p[0], 5, p[1], s(Blocks.SEA_LANTERN));
            }
        }
        // Capitol launch tower (Tier 4 "City Rooftop Escape")
        int x0 = TOWER_X - 3, x1 = TOWER_X + 3;
        for (int y = 0; y <= TOWER_HEIGHT; y++) {
            for (int x = x0; x <= x1; x++) {
                for (int z = -3; z <= 3; z++) {
                    boolean wall = x == x0 || x == x1 || z == -3 || z == 3;
                    boolean corner = (x == x0 || x == x1) && (z == -3 || z == 3);
                    BlockState state = corner ? s(Blocks.POLISHED_DEEPSLATE)
                            : wall ? (y % 8 >= 3 && y % 8 <= 5 && !(z == 0 && y < 3) ? s(Blocks.LIGHT_BLUE_STAINED_GLASS) : s(Blocks.WHITE_CONCRETE))
                            : AIR;
                    b.set(x, y, z, state);
                }
            }
        }
        b.fill(TOWER_X, 0, -3, TOWER_X, 2, -3, AIR);              // door facing the plaza avenue (north side)
        b.fill(TOWER_X, 0, -3, TOWER_X, 0, -3, AIR);
        for (int y = 0; y < TOWER_HEIGHT; y++) {
            b.set(TOWER_X, y, 2, ladder(Direction.NORTH));        // ladder up the inside of the south wall
        }
        // roof: launch pad with hazard stripes and neon ring
        b.fill(x0 - 1, TOWER_HEIGHT, -4, x1 + 1, TOWER_HEIGHT, 4, s(Blocks.BLACK_CONCRETE));
        for (int x = x0 - 1; x <= x1 + 1; x++) {
            for (int z = -4; z <= 4; z++) {
                if (x == x0 - 1 || x == x1 + 1 || z == -4 || z == 4) {
                    b.set(x, TOWER_HEIGHT, z, Math.floorMod(x + z, 2) == 0 ? s(Blocks.YELLOW_CONCRETE) : s(Blocks.BLACK_CONCRETE));
                }
            }
        }
        b.set(TOWER_X, TOWER_HEIGHT, 2, AIR);                   // hatch
        b.set(TOWER_X, TOWER_HEIGHT + 1, 0, neon("gold"));
        b.set(TOWER_X, TOWER_HEIGHT, 0, s(Blocks.ORANGE_CONCRETE));
        b.marker("sign", TOWER_X, TOWER_HEIGHT + 1, -1, "launch_pad");
        // neon skyline signs on the plaza edge
        for (int x = -12; x <= 12; x += 6) {
            b.set(x, 0, -16, neon(x % 12 == 0 ? "cyan" : "pink"));
        }
        return b.build();
    }

    // ================================================================== Secret Bunker HQ (underground)
    private static Schematic bunker() {
        Schematic.Builder b = new Schematic.Builder("bunker_hq");
        int x0 = -16, x1 = 16, z0 = 30, z1 = 54, y0 = -15, y1 = -5;
        b.shell(x0, y0, z0, x1, y1, z1, s(Blocks.POLISHED_DEEPSLATE), AIR);
        b.fill(x0 + 1, y0, z0 + 1, x1 - 1, y0, z1 - 1, s(Blocks.POLISHED_BLACKSTONE_BRICKS));
        // checker floor in the briefing room
        for (int x = -6; x <= 6; x++) {
            for (int z = 36; z <= 46; z++) {
                b.set(x, y0, z, Math.floorMod(x + z, 2) == 0 ? s(Blocks.BLACK_CONCRETE) : s(Blocks.GRAY_CONCRETE));
            }
        }
        // ceiling lights
        for (int x = x0 + 3; x < x1; x += 5) {
            for (int z = z0 + 3; z < z1; z += 5) {
                b.set(x, y1, z, s(Blocks.SEA_LANTERN));
            }
        }
        // entrance: newsstand kiosk on the street with a stair shaft down
        b.fill(-2, 0, 24, 2, 3, 28, s(Blocks.DARK_OAK_PLANKS));
        b.fill(-1, 0, 25, 1, 2, 27, AIR);
        b.fill(-1, 0, 24, 1, 1, 24, AIR);
        b.fill(-2, 4, 24, 2, 4, 28, slab(Blocks.RED_NETHER_BRICK_SLAB, false));
        b.set(0, 3, 23, neon("red"));
        // a proper staircase: 1 block down per block south, from street (y -1) to bunker floor
        for (int i = 0; i < 14; i++) {
            int y = -1 - i;
            int z = 25 + i;
            for (int x = -1; x <= 1; x++) {
                b.fill(x, y + 1, z, x, y + 4, z, AIR);
                b.set(x, y, z, stairs(Blocks.POLISHED_DEEPSLATE_STAIRS, Direction.NORTH, false));
            }
            b.set(-2, y + 2, z, s(Blocks.POLISHED_DEEPSLATE));
            b.set(2, y + 2, z, i % 4 == 0 ? s(Blocks.SOUL_LANTERN) : s(Blocks.POLISHED_DEEPSLATE));
        }
        b.fill(-1, y0 + 1, z0, 1, y0 + 3, z0, AIR);              // doorway into the bunker
        b.set(-2, y0 + 3, z0, s(Blocks.REDSTONE_LAMP));
        // briefing wall: three mission boards + map screen
        for (int x = -2; x <= 2; x += 2) {
            b.set(x, y0 + 1, z1 - 1, ModBlocks.MISSION_BOARD.get().defaultBlockState().setValue(MissionBoardBlock.FACING, Direction.NORTH));
        }
        b.fill(-5, y0 + 2, z1 - 1, 5, y0 + 5, z1 - 1, s(Blocks.BLACK_STAINED_GLASS));
        b.fill(-4, y0 + 3, z1 - 1, 4, y0 + 4, z1 - 1, s(Blocks.LIGHT_BLUE_STAINED_GLASS));
        b.set(0, y0 + 6, z1 - 1, neon("cyan"));
        // Agent Zero's desk with monitors
        b.fill(-3, y0 + 1, 42, 3, y0 + 1, 42, slab(Blocks.POLISHED_BLACKSTONE_SLAB, true));
        b.set(-2, y0 + 2, 42, s(Blocks.BLACK_STAINED_GLASS));
        b.set(2, y0 + 2, 42, s(Blocks.BLACK_STAINED_GLASS));
        b.set(0, y0 + 2, 42, s(Blocks.LIGHT_BLUE_STAINED_GLASS));
        b.marker("agent_zero", 0, y0 + 1, 44);
        // black market corner (west): crates, neon, the dealer
        b.fill(x0 + 1, y0 + 1, 32, x0 + 6, y0 + 1, 32, s(Blocks.BARREL));
        b.fill(x0 + 1, y0 + 2, 32, x0 + 3, y0 + 2, 32, s(Blocks.BARREL));
        b.fill(x0 + 1, y0 + 1, 36, x0 + 6, y0 + 1, 36, slab(Blocks.DARK_OAK_SLAB, true));
        b.set(x0 + 1, y0 + 4, 34, neon("gold"));
        b.set(x0 + 1, y0 + 4, 35, neon("pink"));
        b.marker("dealer", x0 + 3, y0 + 1, 34);
        // armoury racks + gadget lab (east)
        for (int z = 32; z <= 50; z += 3) {
            b.set(x1 - 1, y0 + 1, z, s(Blocks.SMITHING_TABLE));
            b.set(x1 - 1, y0 + 2, z, s(Blocks.CHAIN));
            b.set(x1 - 2, y0 + 1, z + 1, s(Blocks.IRON_BLOCK));
        }
        // bunk beds (decor as wool + slabs) and a server room hum
        for (int z = 46; z <= 52; z += 3) {
            b.fill(x0 + 1, y0 + 1, z, x0 + 3, y0 + 1, z, s(Blocks.RED_WOOL));
            b.fill(x0 + 1, y0 + 3, z, x0 + 3, y0 + 3, z, s(Blocks.GRAY_WOOL));
        }
        b.fill(8, y0 + 1, 50, 13, y0 + 3, 52, s(Blocks.OBSERVER));
        b.fill(8, y0 + 1, 49, 13, y0 + 1, 49, s(Blocks.REDSTONE_LAMP));
        return b.build();
    }

    // ================================================================== Sector 1: Bank Vault (Warden + soundproof chambers)
    private static Schematic bank() {
        Schematic.Builder b = new Schematic.Builder("sector1_bank_vault");
        int x0 = 24, x1 = 64, z0 = -64, z1 = -24;
        // ---- street-level bank: marble hall with columns and a pediment
        b.shell(x0, 0, z0, x1, 12, z1, s(Blocks.QUARTZ_BLOCK), AIR);
        b.fill(x0, -1, z0, x1, -1, z1, s(Blocks.POLISHED_DIORITE));
        b.fill(x0 + 1, 6, z0 + 1, x1 - 1, 6, z1 - 1, s(Blocks.SMOOTH_QUARTZ)); // mezzanine
        b.fill(x0 + 6, 6, z1 - 12, x1 - 6, 6, z1 - 1, AIR);
        windows(b, x0, z0, x1, z1, 2, 4, s(Blocks.GLASS), 4);
        windows(b, x0, z0, x1, z1, 8, 10, s(Blocks.GLASS), 4);
        for (int x = x0 + 2; x <= x1 - 2; x += 4) {                     // portico columns on the plaza side
            b.fill(x, 0, z1 + 1, x, 11, z1 + 1, s(Blocks.QUARTZ_PILLAR));
        }
        b.fill(x0, 12, z1 + 1, x1, 12, z1 + 2, s(Blocks.CHISELED_QUARTZ_BLOCK));
        for (int i = 0; i <= 6; i++) {
            b.fill(x0 + 4 + i * 2, 13 + i, z1 + 1, x1 - 4 - i * 2, 13 + i, z1 + 1, s(Blocks.QUARTZ_BRICKS));
        }
        b.fill(42, 0, z1, 46, 4, z1, AIR);                             // grand entrance
        b.fill(40, 8, z1 + 1, 48, 9, z1 + 1, s(Blocks.GOLD_BLOCK));    // gold BANK lintel
        // tellers' counters, velvet rope, chandeliers
        b.fill(x0 + 4, 0, -46, x1 - 4, 1, -46, s(Blocks.POLISHED_ANDESITE));
        b.fill(x0 + 4, 2, -46, x1 - 4, 2, -46, s(Blocks.IRON_BARS));
        for (int x = x0 + 6; x <= x1 - 6; x += 8) {
            b.set(x, 11, -36, hanging(Blocks.LANTERN));
            b.set(x, 11, -54, hanging(Blocks.LANTERN));
        }
        b.fill(x0 + 2, 0, z0 + 2, x0 + 6, 2, z0 + 6, s(Blocks.GOLD_BLOCK));   // display gold
        b.set(x1 - 3, 7, z1 - 3, beacon());
        b.set(x0 + 3, 7, z1 - 3, beacon());
        // ---- staircase down to the safe-deposit gallery
        for (int i = 0; i < 12; i++) {
            int y = -1 - i;
            int x = x0 + 2 + i;
            b.fill(x, y + 1, -30, x, y + 4, -27, AIR);
            for (int z = -30; z <= -27; z++) {
                b.set(x, y, z, stairs(Blocks.QUARTZ_STAIRS, Direction.EAST, false));
            }
        }
        // ---- underground vault level (y -15 .. -5)
        int vy0 = -15, vy1 = -4;
        b.shell(x0 + 1, vy0, z0 + 1, x1 - 1, vy1, -26, s(ModBlocks.VAULT_STEEL.get()), AIR);
        b.fill(x0 + 2, -12, -30, x0 + 14, -12, -27, s(Blocks.POLISHED_DIORITE));
        b.fill(x0 + 2, -11, -30, x0 + 14, -6, -27, AIR);
        // gallery (west end) looking east through bulletproof glass into the vault chamber
        int gx0 = x0 + 2, gx1 = x0 + 6;
        b.fill(gx0, -12, -58, gx1, -12, -32, s(Blocks.POLISHED_DIORITE));
        b.fill(gx0 + 1, -11, -58, gx0 + 1, -11, -32, s(Blocks.RED_CARPET));
        b.fill(gx0, -11, -58, gx1, -6, -31, AIR);
        for (int z = -58; z <= -31; z += 4) {
            b.set(gx0, -7, z, s(Blocks.SEA_LANTERN));
        }
        // vault chamber: vault steel outside, soundproof panels inside (the Warden cannot hear through them)
        int cx0 = gx1 + 1, cx1 = x1 - 3, cz0 = -60, cz1 = -36;
        b.shell(cx0, -13, cz0, cx1, -5, cz1, s(ModBlocks.SOUNDPROOF_PANEL.get()), AIR);
        b.fill(cx0 + 1, -13, cz0 + 1, cx1 - 1, -13, cz1 - 1, s(Blocks.SCULK));
        b.fill(cx0, -11, cz0 + 4, cx0, -7, cz1 - 4, s(Blocks.GLASS));     // viewing window (rays pass glass)
        for (int x = cx0 + 4; x < cx1; x += 6) {
            b.set(x, -12, cz0 + 2, s(Blocks.SCULK_SENSOR));
            b.set(x, -12, cz1 - 2, s(Blocks.SCULK_SHRIEKER));
            b.set(x, -5, (cz0 + cz1) / 2, s(Blocks.SHROOMLIGHT));
        }
        // gold & diamond hoard
        for (int x = cx0 + 8; x < cx1 - 4; x += 3) {
            b.set(x, -12, cz0 + 1, s(Blocks.GOLD_BLOCK));
            b.set(x, -12, cz1 - 1, s(Blocks.GOLD_BLOCK));
            b.set(x + 1, -12, cz0 + 1, s(Blocks.RAW_GOLD_BLOCK));
        }
        // the Warden's Squeaky Toy on its pedestal at the far end (~32 blocks from the window)
        int px = cx1 - 3, pz = (cz0 + cz1) / 2;
        b.fill(px - 1, -12, pz - 1, px + 1, -12, pz + 1, s(Blocks.GOLD_BLOCK));
        pedestal(b, px, -11, pz, "heistmod:wardens_squeaky_toy");
        b.marker("warden", (cx0 + cx1) / 2, -12, pz);
        b.set(gx0, -8, -44, beacon());
        return b.build();
    }

    // ================================================================== Sector 2: Piglin High-Rise Penthouse
    private static Schematic penthouse() {
        Schematic.Builder b = new Schematic.Builder("sector2_piglin_penthouse");
        int x0 = -64, x1 = -40, z0 = -64, z1 = -40, top = 64;
        b.fill(x0 - 2, -1, z0 - 2, x1 + 2, -1, z1 + 2, s(Blocks.POLISHED_BLACKSTONE));
        for (int y = 0; y <= top; y++) {
            for (int x = x0; x <= x1; x++) {
                for (int z = z0; z <= z1; z++) {
                    boolean wall = x == x0 || x == x1 || z == z0 || z == z1;
                    boolean corner = (x == x0 || x == x1) && (z == z0 || z == z1);
                    boolean floor = y % 6 == 0;
                    BlockState st;
                    if (corner) {
                        st = y % 6 == 0 ? s(Blocks.GOLD_BLOCK) : s(Blocks.GILDED_BLACKSTONE);
                    } else if (wall) {
                        int along = (x == x0 || x == x1) ? z - z0 : x - x0;
                        st = floor ? s(Blocks.POLISHED_BLACKSTONE_BRICKS)
                                : (y % 6 >= 2 && y % 6 <= 4 && along % 3 != 0) ? s(Blocks.ORANGE_STAINED_GLASS)
                                : s(Blocks.BLACKSTONE);
                    } else {
                        st = floor ? s(y == 0 ? Blocks.POLISHED_BLACKSTONE : Blocks.CRIMSON_PLANKS) : AIR;
                    }
                    b.set(x, y, z, st);
                }
            }
        }
        b.fill(-53, 1, z1, -51, 3, z1, AIR);                       // lobby doors facing south
        // staircase: switch-back flights along the east wall of every storey
        for (int floor = 0; floor < top / 6; floor++) {
            int base = floor * 6;
            boolean north = floor % 2 == 0;
            for (int i = 0; i < 6; i++) {
                int z = north ? (z1 - 3 - i) : (z0 + 3 + i);
                for (int x = x1 - 3; x <= x1 - 1; x++) {
                    b.set(x, base + 1 + i, z, stairs(Blocks.POLISHED_BLACKSTONE_BRICK_STAIRS, north ? Direction.NORTH : Direction.SOUTH, false));
                    b.fill(x, base + 6, z, x, base + 6, z, AIR);
                    b.fill(x, base + 2 + i, z, x, base + 4 + i, z, AIR);
                }
            }
            // lighting + luxury decor
            b.set((x0 + x1) / 2, base + 5, (z0 + z1) / 2, hanging(Blocks.SOUL_LANTERN));
            b.set(x0 + 3, base + 1, z0 + 3, s(Blocks.GOLD_BLOCK));
            b.set(x0 + 3, base + 2, z0 + 3, s(Blocks.LANTERN));
            if (floor % 2 == 1 && floor < 9) {
                b.marker("brute", x0 + 6, base + 1, (z0 + z1) / 2);
            }
        }
        // ground lobby guards
        b.marker("brute", -55, 1, z1 - 3);
        b.marker("brute", -49, 1, z1 - 3);
        // penthouse throne room (top storey): crimson carpet, gold throne, the Piglin King
        int py = top - 6;
        b.fill(x0 + 1, py + 1, z0 + 1, x1 - 4, py + 5, z1 - 1, AIR);
        b.fill(-53, py, z0 + 2, -51, py, z1 - 2, s(Blocks.RED_WOOL));
        b.fill(-54, py + 1, z0 + 2, -50, py + 1, z0 + 3, s(Blocks.GOLD_BLOCK));
        b.fill(-54, py + 2, z0 + 2, -50, py + 4, z0 + 2, s(Blocks.GOLD_BLOCK));
        b.set(-52, py + 2, z0 + 3, stairs(Blocks.CRIMSON_STAIRS, Direction.NORTH, false));
        for (int x = x0 + 2; x <= x1 - 5; x += 4) {
            b.set(x, py + 1, z1 - 2, s(Blocks.GILDED_BLACKSTONE));
            b.set(x, py + 2, z1 - 2, s(Blocks.SOUL_LANTERN));
        }
        b.marker("piglin_king", -52, py + 1, z0 + 5);
        b.marker("brute", -56, py + 1, z0 + 8);
        b.marker("brute", -48, py + 1, z0 + 8);
        // rooftop helipad
        b.fill(x0, top + 1, z0, x1, top + 1, z1, AIR);
        for (int x = -55; x <= -49; x++) {
            b.set(x, top, -52, s(Blocks.WHITE_CONCRETE));
        }
        for (int z = -55; z <= -49; z++) {
            b.set(-55, top, z, s(Blocks.WHITE_CONCRETE));
            b.set(-49, top, z, s(Blocks.WHITE_CONCRETE));
        }
        b.set(x0, top + 1, z0, neon("gold"));
        b.set(x1, top + 1, z0, neon("gold"));
        b.set(x0, top + 1, z1, neon("gold"));
        b.set(x1, top + 1, z1, neon("gold"));
        return b.build();
    }

    // ================================================================== Sector 3: Haunted Laser Museum
    private static Schematic museum() {
        Schematic.Builder b = new Schematic.Builder("sector3_laser_museum");
        int x0 = -64, x1 = -26, z0 = 24, z1 = 64;
        b.fill(x0 - 2, -1, z0 - 2, x1 + 2, -1, z1 + 2, s(Blocks.MOSSY_STONE_BRICKS));
        for (int floor = 0; floor < 3; floor++) {
            int y0 = floor * 7;
            b.shell(x0, y0, z0, x1, y0 + 7, z1, s(Blocks.DEEPSLATE_BRICKS), AIR);
            windows(b, x0, z0, x1, z1, y0 + 2, y0 + 5, s(Blocks.PURPLE_STAINED_GLASS), 5);
            // gothic buttresses
            for (int x = x0; x <= x1; x += 6) {
                b.fill(x, y0, z0 - 1, x, y0 + 6, z0 - 1, s(Blocks.CRACKED_DEEPSLATE_BRICKS));
            }
            // cobwebs + candles + soul lanterns = haunted
            for (int x = x0 + 2; x < x1; x += 7) {
                b.set(x, y0 + 6, z0 + 1, s(Blocks.COBWEB));
                b.set(x + 3, y0 + 6, z1 - 1, s(Blocks.COBWEB));
                b.set(x, y0 + 6, (z0 + z1) / 2, hanging(Blocks.SOUL_LANTERN));
            }
            // floor-to-floor stairs in the north-west corner (alternate direction each storey)
            if (floor < 2) {
                for (int i = 0; i < 7; i++) {
                    for (int x = x0 + 1; x <= x0 + 2; x++) {
                        b.set(x, y0 + 1 + i, z0 + 2 + i, stairs(Blocks.DEEPSLATE_BRICK_STAIRS, Direction.SOUTH, false));
                        b.fill(x, y0 + 2 + i, z0 + 2 + i, x, y0 + 5 + i, z0 + 2 + i, AIR);
                    }
                }
                b.fill(x0 + 1, y0 + 7, z0 + 2, x0 + 2, y0 + 7, z0 + 9, AIR);
            }
        }
        b.fill(-47, 1, z1, -43, 4, z1, AIR);                         // entrance (south)
        b.fill(-48, 5, z1 + 1, -42, 5, z1 + 1, s(Blocks.CHISELED_DEEPSLATE));
        // ground floor: exhibits (display cases) + the first laser corridor
        for (int x = x0 + 6; x < x1 - 4; x += 8) {
            b.set(x, 1, 34, s(Blocks.GLASS));
            b.set(x, 0, 34, s(Blocks.POLISHED_DEEPSLATE));
            b.set(x, 1, 54, s(Blocks.AMETHYST_CLUSTER));
            b.set(x, 0, 54, s(Blocks.POLISHED_DEEPSLATE));
        }
        // laser tripwires: emitters on the west wall shooting east across the halls at mixed heights
        int[][] lasers = {{0, 30, 1}, {0, 38, 2}, {0, 44, 1}, {0, 50, 3}, {7, 32, 1}, {7, 36, 2}, {7, 40, 1}, {7, 44, 3}, {7, 48, 2}, {7, 52, 1}};
        for (int[] l : lasers) {
            b.set(x0 + 1, l[0] + l[2], l[1], laser(Direction.EAST));
        }
        // a criss-cross of vertical lasers in the floor-2 gallery
        for (int x = x0 + 8; x < x1 - 4; x += 5) {
            b.set(x, 8, 46, laser(Direction.UP));
        }
        for (int[] p : new int[][]{{x0 + 2, 5, z1 - 2}, {x1 - 2, 5, z0 + 2}, {x0 + 2, 12, z1 - 2}, {x1 - 2, 19, z1 - 2}}) {
            b.set(p[0], p[1], p[2], beacon());
        }
        // top floor: Herobrine exhibit - statue, glowing eyes, and the Forbidden Diary in a glass vitrine
        int hy = 14;
        int sx = -45, sz = 34;
        b.fill(sx - 1, hy + 1, sz, sx, hy + 3, sz, s(Blocks.LIGHT_BLUE_TERRACOTTA));    // legs/torso
        b.fill(sx - 1, hy + 4, sz, sx, hy + 5, sz, s(Blocks.CYAN_TERRACOTTA));
        b.set(sx - 2, hy + 4, sz, s(Blocks.CYAN_TERRACOTTA));
        b.set(sx + 1, hy + 4, sz, s(Blocks.CYAN_TERRACOTTA));
        b.fill(sx - 1, hy + 6, sz, sx, hy + 6, sz, s(Blocks.BROWN_TERRACOTTA));
        b.set(sx - 1, hy + 6, sz + 1, s(Blocks.END_ROD));
        b.set(sx, hy + 6, sz + 1, s(Blocks.END_ROD));
        b.fill(sx - 3, hy, sz - 2, sx + 2, hy, sz + 2, s(Blocks.CRYING_OBSIDIAN));
        pedestal(b, -45, hy + 1, 50, "heistmod:herobrines_forbidden_diary");
        b.fill(-47, hy + 1, 48, -43, hy + 4, 52, s(Blocks.GLASS));
        b.fill(-46, hy + 1, 49, -44, hy + 3, 51, AIR);
        b.set(-45, hy + 1, 50, s(ModBlocks.TROPHY_PEDESTAL.get()));
        b.fill(-46, hy + 4, 49, -44, hy + 4, 51, s(Blocks.GLASS));
        // laser cage around the vitrine
        b.set(-49, hy + 2, 50, laser(Direction.EAST));
        b.set(-45, hy + 1, 46, laser(Direction.SOUTH));
        b.set(-41, hy + 3, 50, laser(Direction.WEST));
        b.marker("ghost_ambience", -45, hy + 2, 44);
        return b.build();
    }

    // ================================================================== Sector 4: Central Capitol floating island
    private static Schematic capitol(int islandY) {
        Schematic.Builder b = new Schematic.Builder("sector4_capitol_island");
        int r = ISLAND_RADIUS;
        // inverted rocky cone (fast taper so the launch tower's rocket path clears the underside)
        for (int d = 0; d <= 26; d++) {
            double radius = r - 1.15D * d - (d > 6 ? (d - 6) * 0.25D : 0);
            if (radius < 1.0D) {
                break;
            }
            BlockState rock = d < 2 ? s(Blocks.DIRT) : d % 5 == 0 ? s(Blocks.ANDESITE) : s(Blocks.STONE);
            b.disc(0, islandY - d, 0, radius, rock);
            if (d > 3 && d % 4 == 0) {
                b.ring(0, islandY - d, 0, radius - 1.2D, radius, s(Blocks.MOSSY_COBBLESTONE));
            }
        }
        b.disc(0, islandY, 0, r, s(Blocks.GRASS_BLOCK));
        b.ring(0, islandY, 0, 15, 16.5, s(Blocks.SMOOTH_QUARTZ));
        b.fill(-1, islandY, -r, 1, islandY, -15, s(Blocks.SMOOTH_QUARTZ));   // promenade to the north rim
        b.fill(15, islandY, -1, r, islandY, 1, s(Blocks.SMOOTH_QUARTZ));      // landing promenade toward the tower
        // the Capitol rotunda: columns, drum, dome
        b.disc(0, islandY + 1, 0, 12, s(Blocks.QUARTZ_BRICKS));
        b.disc(0, islandY + 1, 0, 11, s(Blocks.POLISHED_DIORITE));
        for (int i = 0; i < 16; i++) {
            double a = i * Math.PI * 2 / 16;
            int x = (int) Math.round(Math.cos(a) * 11);
            int z = (int) Math.round(Math.sin(a) * 11);
            b.fill(x, islandY + 2, z, x, islandY + 10, z, s(Blocks.QUARTZ_PILLAR));
        }
        b.ring(0, islandY + 11, 0, 9, 12.5, s(Blocks.CHISELED_QUARTZ_BLOCK));
        for (int h = 0; h <= 9; h++) {
            double dr = Math.sqrt(Math.max(0, 100 - h * h * 1.2));
            b.ring(0, islandY + 12 + h, 0, Math.max(0, dr - 1.2), dr, h % 3 == 2 ? s(Blocks.WHITE_STAINED_GLASS) : s(Blocks.SMOOTH_QUARTZ));
        }
        b.fill(0, islandY + 22, 0, 0, islandY + 25, 0, s(Blocks.END_ROD));
        b.set(0, islandY + 26, 0, s(Blocks.GOLD_BLOCK));
        // Notch's Forbidden Capitol Core dais: obsidian rings, crying obsidian, floating end rods
        b.disc(0, islandY + 2, 0, 4, s(Blocks.OBSIDIAN));
        b.ring(0, islandY + 2, 0, 2.5, 4, s(Blocks.CRYING_OBSIDIAN));
        b.set(0, islandY + 2, 0, s(Blocks.BEACON));
        for (int[] p : new int[][]{{3, 0}, {-3, 0}, {0, 3}, {0, -3}}) {
            b.fill(p[0], islandY + 3, p[1], p[0], islandY + 5, p[1], s(Blocks.END_ROD));
        }
        b.marker("sign", 0, islandY + 3, 5, "capitol_dais");
        // a few trees and lamps around the lawn
        for (int i = 0; i < 6; i++) {
            double a = i * Math.PI / 3 + 0.4;
            int x = (int) Math.round(Math.cos(a) * 22);
            int z = (int) Math.round(Math.sin(a) * 22);
            b.fill(x, islandY + 1, z, x, islandY + 4, z, s(Blocks.CHERRY_LOG));
            b.fill(x - 1, islandY + 4, z - 1, x + 1, islandY + 6, z + 1, leaves());
            b.set(x, islandY + 7, z, leaves());
        }
        return b.build();
    }
}
'''

FILES['src/main/java/com/heistmod/world/CityBuilder.java'] = r'''package com.heistmod.world;

import com.heistmod.HeistMod;
import com.heistmod.entity.PiglinKingEntity;
import com.heistmod.registry.ModEntities;
import net.minecraft.core.BlockPos;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.NbtIo;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.packs.resources.Resource;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.Mob;
import net.minecraft.world.entity.MobSpawnType;
import net.minecraft.world.entity.PathfinderMob;
import net.minecraft.world.entity.monster.piglin.PiglinBrute;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.storage.LevelResource;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.function.Consumer;

/**
 * {@code /heist spawn_city}: builds the Mega City + Secret Bunker HQ around an origin. Each part is either the procedural
 * blueprint or, if a data pack ships {@code data/heistmod/structures/<part>.nbt}, that NBT structure instead. Placement
 * goes through {@link SchematicPlacer} (multi-tick batches); NPCs and guards spawn once every block is in place.
 */
public final class CityBuilder {
    private CityBuilder() {}

    public static int islandY(ServerLevel level, BlockPos origin) {
        int wanted = CityBlueprints.TOWER_HEIGHT + CityBlueprints.ISLAND_ABOVE_ROOF;
        int max = level.getMaxBuildHeight() - 34 - origin.getY();
        return Math.max(CityBlueprints.TOWER_HEIGHT + 30, Math.min(wanted, max));
    }

    public static List<Schematic> parts(ServerLevel level, BlockPos origin, Consumer<Component> log) {
        List<Schematic> parts = new ArrayList<>();
        for (Schematic procedural : CityBlueprints.all(islandY(level, origin))) {
            ResourceLocation file = HeistMod.id("structures/" + procedural.name + ".nbt");
            Optional<Resource> resource = level.getServer().getResourceManager().getResource(file);
            if (resource.isPresent()) {
                try (InputStream in = resource.get().open()) {
                    CompoundTag nbt = NbtIo.readCompressed(in);
                    parts.add(Schematic.fromNbt(procedural.name, nbt, level.holderLookup(Registries.BLOCK), procedural));
                    log.accept(Component.translatable("command.heistmod.city.nbt", procedural.name));
                    continue;
                } catch (IOException | RuntimeException e) {
                    HeistMod.LOGGER.warn("Bad structure {}, using the procedural blueprint", file, e);
                }
            }
            parts.add(procedural);
        }
        return parts;
    }

    public static int spawn(ServerLevel level, BlockPos origin, Consumer<Component> log) {
        List<Schematic> parts = parts(level, origin, log);
        int total = 0;
        for (int i = 0; i < parts.size(); i++) {
            Schematic part = parts.get(i);
            total += part.size();
            boolean last = i == parts.size() - 1;
            SchematicPlacer.enqueue(level, origin, part, () -> {
                log.accept(Component.translatable("command.heistmod.city.part_done", part.name));
                if (last) {
                    for (Schematic p : parts) {
                        spawnMarkers(level, origin, p);
                    }
                    log.accept(Component.translatable("command.heistmod.city.done"));
                }
            });
        }
        return total;
    }

    private static void spawnMarkers(ServerLevel level, BlockPos origin, Schematic schematic) {
        for (Schematic.Marker marker : schematic.markers) {
            BlockPos pos = origin.offset(marker.pos());
            switch (marker.type()) {
                case "agent_zero" -> spawnNpc(level, pos, ModEntities.AGENT_ZERO.get().create(level));
                case "dealer" -> spawnNpc(level, pos, ModEntities.BLACK_MARKET_DEALER.get().create(level));
                case "warden" -> spawnGuard(level, pos, EntityType.WARDEN.create(level));
                case "piglin_king" -> {
                    PiglinKingEntity king = ModEntities.PIGLIN_KING.get().create(level);
                    spawnGuard(level, pos, king);
                }
                case "brute" -> {
                    PiglinBrute brute = EntityType.PIGLIN_BRUTE.create(level);
                    if (brute != null) {
                        brute.setImmuneToZombification(true);
                        spawnGuard(level, pos, brute);
                        brute.setItemSlot(EquipmentSlot.HEAD, new ItemStack(Items.GOLDEN_HELMET));
                        brute.setItemSlot(EquipmentSlot.CHEST, new ItemStack(Items.GOLDEN_CHESTPLATE));
                    }
                }
                default -> {
                    // "sign" / "ghost_ambience": informational markers, nothing to spawn
                }
            }
        }
    }

    private static void spawnNpc(ServerLevel level, BlockPos pos, PathfinderMob npc) {
        if (npc == null) {
            return;
        }
        npc.moveTo(pos.getX() + 0.5D, pos.getY(), pos.getZ() + 0.5D, 180.0F, 0.0F);
        npc.restrictTo(pos, 5);
        npc.finalizeSpawn(level, level.getCurrentDifficultyAt(pos), MobSpawnType.STRUCTURE, null, null);
        level.addFreshEntity(npc);
    }

    private static void spawnGuard(ServerLevel level, BlockPos pos, Mob mob) {
        if (mob == null) {
            return;
        }
        mob.moveTo(pos.getX() + 0.5D, pos.getY(), pos.getZ() + 0.5D, level.random.nextFloat() * 360.0F, 0.0F);
        mob.finalizeSpawn(level, level.getCurrentDifficultyAt(pos), MobSpawnType.STRUCTURE, null, null);
        mob.setPersistenceRequired();
        if (mob instanceof PathfinderMob pathfinder) {
            pathfinder.restrictTo(pos, 10);
        }
        level.addFreshEntity(mob);
    }

    /** Writes every procedural part as a vanilla structure NBT to {@code <world>/generated/heistmod/structures/}. */
    public static Path export(ServerLevel level, BlockPos origin) throws IOException {
        Path dir = level.getServer().getWorldPath(LevelResource.GENERATED_DIR).resolve(HeistMod.MODID).resolve("structures");
        Files.createDirectories(dir);
        for (Schematic part : CityBlueprints.all(islandY(level, origin))) {
            NbtIo.writeCompressed(part.toNbt(), dir.resolve(part.name + ".nbt").toFile());
        }
        return dir;
    }
}
'''

FILES['src/main/java/com/heistmod/world/Schematic.java'] = r'''package com.heistmod.world;

import it.unimi.dsi.fastutil.longs.Long2ObjectOpenHashMap;
import net.minecraft.SharedConstants;
import net.minecraft.core.BlockPos;
import net.minecraft.core.HolderGetter;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.IntTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.NbtUtils;
import net.minecraft.nbt.Tag;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockState;

import org.jetbrains.annotations.Nullable;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;

/**
 * An immutable block volume: positions (relative to the city origin) sorted bottom-up, their block states, optional
 * block entity NBT and a list of markers (things to spawn / configure once the blocks are in the world).
 * Reads and writes the vanilla structure-template NBT format, so parts can be exported, edited with structure blocks and
 * dropped back in as {@code data/heistmod/structures/<name>.nbt}.
 */
public final class Schematic {
    public record Marker(String type, BlockPos pos, String data) {}

    public final String name;
    public final long[] keys;
    public final BlockState[] states;
    public final Long2ObjectOpenHashMap<CompoundTag> blockEntities;
    public final List<Marker> markers;

    Schematic(String name, long[] keys, BlockState[] states, Long2ObjectOpenHashMap<CompoundTag> blockEntities, List<Marker> markers) {
        this.name = name;
        this.keys = keys;
        this.states = states;
        this.blockEntities = blockEntities;
        this.markers = markers;
    }

    // ------------------------------------------------------------------ key packing (y in the high bits => sorts bottom-up)
    private static final int BIAS = 1 << 19;

    public static long key(int x, int y, int z) {
        return ((long) (y + 2048) << 40) | ((long) (x + BIAS) << 20) | (long) (z + BIAS);
    }

    public static int keyX(long key) {
        return (int) ((key >> 20) & 0xFFFFF) - BIAS;
    }

    public static int keyY(long key) {
        return (int) (key >> 40) - 2048;
    }

    public static int keyZ(long key) {
        return (int) (key & 0xFFFFF) - BIAS;
    }

    public int size() {
        return keys.length;
    }

    public int[] bounds() {
        int minX = Integer.MAX_VALUE, minY = Integer.MAX_VALUE, minZ = Integer.MAX_VALUE;
        int maxX = Integer.MIN_VALUE, maxY = Integer.MIN_VALUE, maxZ = Integer.MIN_VALUE;
        for (long k : keys) {
            int x = keyX(k), y = keyY(k), z = keyZ(k);
            minX = Math.min(minX, x); minY = Math.min(minY, y); minZ = Math.min(minZ, z);
            maxX = Math.max(maxX, x); maxY = Math.max(maxY, y); maxZ = Math.max(maxZ, z);
        }
        return new int[]{minX, minY, minZ, maxX, maxY, maxZ};
    }

    // ------------------------------------------------------------------ vanilla structure NBT
    public CompoundTag toNbt() {
        int[] b = bounds();
        CompoundTag root = new CompoundTag();
        Map<BlockState, Integer> index = new IdentityHashMap<>();
        ListTag palette = new ListTag();
        ListTag blocks = new ListTag();
        for (int i = 0; i < keys.length; i++) {
            BlockState state = states[i];
            Integer id = index.get(state);
            if (id == null) {
                id = palette.size();
                index.put(state, id);
                palette.add(NbtUtils.writeBlockState(state));
            }
            CompoundTag block = new CompoundTag();
            block.put("pos", ints(keyX(keys[i]) - b[0], keyY(keys[i]) - b[1], keyZ(keys[i]) - b[2]));
            block.putInt("state", id);
            CompoundTag be = blockEntities.get(keys[i]);
            if (be != null) {
                block.put("nbt", be.copy());
            }
            blocks.add(block);
        }
        root.put("size", ints(b[3] - b[0] + 1, b[4] - b[1] + 1, b[5] - b[2] + 1));
        root.put("palette", palette);
        root.put("blocks", blocks);
        root.put("entities", new ListTag());
        root.put("heist_offset", ints(b[0], b[1], b[2]));
        root.putInt("DataVersion", SharedConstants.getCurrentVersion().getDataVersion().getVersion());
        return root;
    }

    /** @param fallback procedural version of the same part: supplies the anchor offset (if the file has none) and the markers. */
    public static Schematic fromNbt(String name, CompoundTag root, HolderGetter<Block> blocksLookup, @Nullable Schematic fallback) {
        int ox = 0, oy = 0, oz = 0;
        if (root.contains("heist_offset", Tag.TAG_LIST)) {
            ListTag off = root.getList("heist_offset", Tag.TAG_INT);
            ox = off.getInt(0); oy = off.getInt(1); oz = off.getInt(2);
        } else if (fallback != null && fallback.size() > 0) {
            int[] b = fallback.bounds();
            ox = b[0]; oy = b[1]; oz = b[2];
        }
        ListTag paletteTag = root.getList("palette", Tag.TAG_COMPOUND);
        BlockState[] palette = new BlockState[paletteTag.size()];
        for (int i = 0; i < palette.length; i++) {
            palette[i] = NbtUtils.readBlockState(blocksLookup, paletteTag.getCompound(i));
        }
        ListTag blocks = root.getList("blocks", Tag.TAG_COMPOUND);
        Builder builder = new Builder(name);
        for (int i = 0; i < blocks.size(); i++) {
            CompoundTag block = blocks.getCompound(i);
            ListTag pos = block.getList("pos", Tag.TAG_INT);
            int state = block.getInt("state");
            if (state < 0 || state >= palette.length) {
                continue;
            }
            int x = pos.getInt(0) + ox, y = pos.getInt(1) + oy, z = pos.getInt(2) + oz;
            builder.set(x, y, z, palette[state]);
            if (block.contains("nbt", Tag.TAG_COMPOUND)) {
                builder.blockEntity(x, y, z, block.getCompound("nbt"));
            }
        }
        if (fallback != null) {
            builder.markers.addAll(fallback.markers);
        }
        return builder.build();
    }

    private static ListTag ints(int a, int b, int c) {
        ListTag list = new ListTag();
        list.add(IntTag.valueOf(a));
        list.add(IntTag.valueOf(b));
        list.add(IntTag.valueOf(c));
        return list;
    }

    // ------------------------------------------------------------------ builder
    public static final class Builder {
        private final String name;
        private final Long2ObjectOpenHashMap<BlockState> blocks = new Long2ObjectOpenHashMap<>();
        private final Long2ObjectOpenHashMap<CompoundTag> blockEntities = new Long2ObjectOpenHashMap<>();
        final List<Marker> markers = new ArrayList<>();

        public Builder(String name) {
            this.name = name;
        }

        public Builder set(int x, int y, int z, BlockState state) {
            blocks.put(key(x, y, z), state);
            return this;
        }

        @Nullable
        public BlockState get(int x, int y, int z) {
            return blocks.get(key(x, y, z));
        }

        public Builder blockEntity(int x, int y, int z, CompoundTag nbt) {
            blockEntities.put(key(x, y, z), nbt);
            return this;
        }

        /** Solid box (inclusive corners, any order). */
        public Builder fill(int x0, int y0, int z0, int x1, int y1, int z1, BlockState state) {
            for (int y = Math.min(y0, y1); y <= Math.max(y0, y1); y++) {
                for (int x = Math.min(x0, x1); x <= Math.max(x0, x1); x++) {
                    for (int z = Math.min(z0, z1); z <= Math.max(z0, z1); z++) {
                        blocks.put(key(x, y, z), state);
                    }
                }
            }
            return this;
        }

        /** Hollow shell: {@code wall} on the six faces, {@code inside} (usually air) in the interior. */
        public Builder shell(int x0, int y0, int z0, int x1, int y1, int z1, BlockState wall, BlockState inside) {
            int ax = Math.min(x0, x1), bx = Math.max(x0, x1), ay = Math.min(y0, y1), by = Math.max(y0, y1), az = Math.min(z0, z1), bz = Math.max(z0, z1);
            for (int y = ay; y <= by; y++) {
                for (int x = ax; x <= bx; x++) {
                    for (int z = az; z <= bz; z++) {
                        boolean edge = x == ax || x == bx || y == ay || y == by || z == az || z == bz;
                        blocks.put(key(x, y, z), edge ? wall : inside);
                    }
                }
            }
            return this;
        }

        /** Only the four vertical walls. */
        public Builder walls(int x0, int y0, int z0, int x1, int y1, int z1, BlockState state) {
            int ax = Math.min(x0, x1), bx = Math.max(x0, x1), az = Math.min(z0, z1), bz = Math.max(z0, z1);
            for (int y = Math.min(y0, y1); y <= Math.max(y0, y1); y++) {
                for (int x = ax; x <= bx; x++) {
                    blocks.put(key(x, y, az), state);
                    blocks.put(key(x, y, bz), state);
                }
                for (int z = az; z <= bz; z++) {
                    blocks.put(key(ax, y, z), state);
                    blocks.put(key(bx, y, z), state);
                }
            }
            return this;
        }

        /** Filled horizontal disc. */
        public Builder disc(int cx, int y, int cz, double radius, BlockState state) {
            int r = (int) Math.ceil(radius);
            for (int dx = -r; dx <= r; dx++) {
                for (int dz = -r; dz <= r; dz++) {
                    if (dx * dx + dz * dz <= radius * radius) {
                        blocks.put(key(cx + dx, y, cz + dz), state);
                    }
                }
            }
            return this;
        }

        /** Horizontal ring between two radii. */
        public Builder ring(int cx, int y, int cz, double inner, double outer, BlockState state) {
            int r = (int) Math.ceil(outer);
            for (int dx = -r; dx <= r; dx++) {
                for (int dz = -r; dz <= r; dz++) {
                    double d2 = dx * dx + dz * dz;
                    if (d2 <= outer * outer && d2 >= inner * inner) {
                        blocks.put(key(cx + dx, y, cz + dz), state);
                    }
                }
            }
            return this;
        }

        public Builder marker(String type, int x, int y, int z, String data) {
            markers.add(new Marker(type, new BlockPos(x, y, z), data));
            return this;
        }

        public Builder marker(String type, int x, int y, int z) {
            return marker(type, x, y, z, "");
        }

        public Schematic build() {
            long[] keys = blocks.keySet().toLongArray();
            Arrays.sort(keys);
            BlockState[] states = new BlockState[keys.length];
            for (int i = 0; i < keys.length; i++) {
                states[i] = blocks.get(keys[i]);
            }
            return new Schematic(name, keys, states, blockEntities, List.copyOf(markers));
        }
    }
}
'''

FILES['src/main/java/com/heistmod/world/SchematicPlacer.java'] = r'''package com.heistmod.world;

import com.heistmod.HeistConfig;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.function.Consumer;

/**
 * Places {@link Schematic}s over many ticks: at most {@code cityBlocksPerTick} blocks and {@code cityMillisPerTick}
 * milliseconds per server tick, so even the whole city never stalls the server thread. Jobs run strictly in order.
 */
public final class SchematicPlacer {
    private static final class Job {
        final ServerLevel level;
        final BlockPos origin;
        final Schematic schematic;
        final Consumer<Job> onDone;
        int index;

        Job(ServerLevel level, BlockPos origin, Schematic schematic, Consumer<Job> onDone) {
            this.level = level;
            this.origin = origin;
            this.schematic = schematic;
            this.onDone = onDone;
        }
    }

    private static final Deque<Job> QUEUE = new ArrayDeque<>();
    private static long totalQueued;
    private static long totalPlaced;

    private SchematicPlacer() {}

    public static void enqueue(ServerLevel level, BlockPos origin, Schematic schematic, Runnable onDone) {
        QUEUE.add(new Job(level, origin.immutable(), schematic, job -> onDone.run()));
        totalQueued += schematic.size();
    }

    public static boolean isBusy() {
        return !QUEUE.isEmpty();
    }

    /** 0..1 progress over everything queued since the placer was last idle. */
    public static double progress() {
        return totalQueued == 0 ? 1.0D : (double) totalPlaced / (double) totalQueued;
    }

    public static void clear() {
        QUEUE.clear();
        totalQueued = 0;
        totalPlaced = 0;
    }

    public static void tick(MinecraftServer server) {
        if (QUEUE.isEmpty()) {
            return;
        }
        long deadline = System.nanoTime() + HeistConfig.CITY_MILLIS_PER_TICK.get() * 1_000_000L;
        int budget = HeistConfig.CITY_BLOCKS_PER_TICK.get();
        BlockPos.MutableBlockPos pos = new BlockPos.MutableBlockPos();
        while (!QUEUE.isEmpty() && budget > 0) {
            Job job = QUEUE.peek();
            Schematic s = job.schematic;
            int minY = job.level.getMinBuildHeight();
            int maxY = job.level.getMaxBuildHeight();
            while (job.index < s.keys.length && budget > 0) {
                long key = s.keys[job.index];
                BlockState state = s.states[job.index];
                job.index++;
                totalPlaced++;
                pos.set(job.origin.getX() + Schematic.keyX(key), job.origin.getY() + Schematic.keyY(key), job.origin.getZ() + Schematic.keyZ(key));
                if (pos.getY() < minY || pos.getY() >= maxY) {
                    continue;
                }
                BlockState old = job.level.getBlockState(pos);
                if (old != state) {
                    if (old.hasBlockEntity()) {
                        job.level.removeBlockEntity(pos); // never spill a buried chest
                    }
                    job.level.setBlock(pos, state, 2 | 16);
                    budget--;
                }
                CompoundTag nbt = s.blockEntities.get(key);
                if (nbt != null) {
                    BlockEntity be = job.level.getBlockEntity(pos);
                    if (be != null) {
                        CompoundTag copy = nbt.copy();
                        copy.putInt("x", pos.getX());
                        copy.putInt("y", pos.getY());
                        copy.putInt("z", pos.getZ());
                        be.load(copy);
                        be.setChanged();
                    }
                }
                if ((job.index & 255) == 0 && System.nanoTime() > deadline) {
                    return;
                }
            }
            if (job.index >= s.keys.length) {
                QUEUE.poll();
                job.onDone.accept(job);
                if (QUEUE.isEmpty()) {
                    totalQueued = 0;
                    totalPlaced = 0;
                }
            }
        }
    }
}
'''

