# =====================================================================================================================
#  Sounds (embedded OGG Vorbis) + sounds.json built from the folder layout (drop-in friendly)
# =====================================================================================================================
def write_sounds():
    for rel, b64 in BLOBS.items():
        if rel.startswith("sounds/"):
            target = ASSETS + "/" + rel
            if not os.path.exists(out_path(target)) or not os.path.exists(out_path(target) + ".user"):
                write_bytes(target, base64.b64decode(b64))
    sync_sounds_json()


def sync_sounds_json():
    """Every <event/path>.ogg (+ <path>_2.ogg, _3 ... variants) under assets/heistmod/sounds becomes a sound event."""
    root = out_path(ASSETS + "/sounds")
    found = {}
    for dirpath, _, files in os.walk(root):
        for f in sorted(files):
            if not f.endswith(".ogg"):
                continue
            rel = os.path.relpath(os.path.join(dirpath, f), root).replace(os.sep, "/")[:-4]
            base = re.sub(r"_(\d+)$", "", rel) if re.search(r"_\d+$", rel) and not re.search(r"(line|chase)_\d+$", rel) else rel
            found.setdefault(base.replace("/", "."), []).append(rel)
    subtitles = dict(SOUND_EVENTS)
    doc = {}
    for event in sorted(set(found) | set(subtitles)):
        files = found.get(event, [])
        if not files:
            log("  warning: sound event %s has no .ogg file" % event)
            continue
        entry = {"sounds": [{"name": "heistmod:" + f, "stream": event in ("block.thaila.siphon", "item.gloves.siren")} for f in sorted(files)]}
        entry["subtitle"] = "subtitles.heistmod." + event
        doc[event] = entry
    write_json(ASSETS + "/sounds.json", doc)
    return doc


# =====================================================================================================================
#  Consistency checks: every Java registration has its lang entry, model, blockstate, loot table and sound
# =====================================================================================================================
def validate_registries():
    problems = []
    java = out_path("src/main/java/" + PKG)

    def read(rel):
        with open(os.path.join(java, rel), "r", encoding="utf-8") as f:
            return f.read()

    names = lambda src: [n for n in re.findall(r'(?:reg|blockItem)\("([a-z0-9_]+)"', src) if not n.endswith("_")]
    items = names(read("registry/ModItems.java")) + ["neon_" + c for c in NEON]
    blocks = names(read("registry/ModBlocks.java")) + ["neon_" + c for c in NEON]
    sounds_src = read("registry/ModSounds.java")
    sounds = re.findall(r'reg\("([a-z0-9_.]+)"\)', sounds_src)
    for prefix, count in re.findall(r'regN\("([a-z0-9_.]+)", (\d+)\)', sounds_src):
        sounds += [prefix + str(i) for i in range(1, int(count) + 1)]
    with open(out_path(ASSETS + "/lang/en_us.json"), encoding="utf-8") as f:
        lang = json.load(f)
    with open(out_path(ASSETS + "/sounds.json"), encoding="utf-8") as f:
        sound_doc = json.load(f)
    for it in items:
        if "item.heistmod." + it not in lang and "block.heistmod." + it not in lang:
            problems.append("missing lang for item " + it)
        if not os.path.exists(out_path(ASSETS + "/models/item/%s.json" % it)):
            problems.append("missing item model " + it)
    for b in blocks:
        for rel in ("/blockstates/%s.json" % b,):
            if not os.path.exists(out_path(ASSETS + rel)):
                problems.append("missing blockstate " + b)
        if not os.path.exists(out_path(DATA + "/loot_tables/blocks/%s.json" % b)):
            problems.append("missing loot table " + b)
        if "block.heistmod." + b not in lang:
            problems.append("missing lang for block " + b)
    for s in sounds:
        if s not in sound_doc:
            problems.append("sound event without sounds.json entry: " + s)
    for e in ENTITIES:
        if "entity.heistmod." + e not in lang:
            problems.append("missing lang for entity " + e)
    for model_id in GLTF_ITEMS:
        d = out_path(ASSETS + "/models/gltf/" + model_id)
        if not any(os.path.exists(os.path.join(d, f)) for f in ("model.glb", "model.gltf", "scene.gltf", "scene.glb")):
            problems.append("no glTF model for " + model_id)
    for p in problems:
        log("  PROBLEM: " + p)
    log("validation: %d items, %d blocks, %d sound events - %s" % (len(items), len(blocks), len(sounds),
                                                                     "OK" if not problems else "%d problem(s)" % len(problems)))
    return not problems


# =====================================================================================================================
#  main
# =====================================================================================================================
def write_project_files():
    for rel, text in FILES.items():
        write_text(rel, text)
    write_bytes("gradle/wrapper/gradle-wrapper.jar", base64.b64decode(BLOBS["gradle/wrapper/gradle-wrapper.jar"]))
    try:
        os.chmod(out_path("gradlew"), 0o755)
    except OSError:
        pass


def main(argv=None):
    global OUT
    ap = argparse.ArgumentParser(description="Generate the Secret City Heist Fabric 1.20.1 mod workspace.")
    ap.add_argument("--out", default=os.path.join(os.getcwd(), "SecretCityHeist"), help="output workspace folder")
    ap.add_argument("--models", default=os.path.join(SCRIPT_DIR, "source_models"), help="folder of glTF/GLB model folders to import")
    ap.add_argument("--build", action="store_true", help="run 'gradlew build' afterwards (JDK 17 required)")
    ap.add_argument("--sync-assets", action="store_true", help="only re-scan drop-in assets of an existing workspace")
    ap.add_argument("--clean", action="store_true", help="delete the output folder first")
    args = ap.parse_args(argv)
    OUT = os.path.abspath(args.out)
    if args.clean and os.path.isdir(OUT):
        shutil.rmtree(OUT)
    os.makedirs(OUT, exist_ok=True)
    log("workspace: " + OUT)

    if args.sync_assets:
        import_user_models(args.models)
        write_sidecars()
        sync_sounds_json()
        ok = validate_registries()
        log("assets synced (%d written, %d unchanged)" % (_stats["written"], _stats["unchanged"]))
        return 0 if ok else 1

    write_project_files()
    generate_textures()
    import_user_models(args.models)
    generate_procedural_models()
    write_sidecars()
    generate_data()
    write_sounds()
    ok = validate_registries()
    log("done: %d files written, %d unchanged" % (_stats["written"], _stats["unchanged"]))
    if args.build:
        gradlew = out_path("gradlew.bat" if os.name == "nt" else "gradlew")
        log("running %s build ..." % os.path.basename(gradlew))
        code = subprocess.call([gradlew, "build"], cwd=OUT)
        if code != 0:
            log("gradle build FAILED (exit %d)" % code)
            return code
        log("built: " + os.path.join(OUT, "build", "libs"))
    else:
        log("next: cd \"%s\" && ./gradlew runClient   (or ./gradlew build)" % OUT)
    return 0 if ok else 1



